internal fun quranFullAyahs58(): List<Ayah> = listOf(
    Ayah(1, 58, "قَدْ سَمِعَ اللّٰهُ قَوْلَ الَّتِيْ تُجَادِلُكَ فِيْ زَوْجِهَا وَتَشْتَكِيْٓ اِلَى اللّٰهِ ۖوَاللّٰهُ يَسْمَعُ تَحَاوُرَكُمَاۗ اِنَّ اللّٰهَ سَمِيْعٌۢ بَصِيْرٌ", "Qad sami‘allāhu qaulal-latī tujādiluka fī zaujihā wa tasytakī ilallāh(i), wallāhu yasma‘u taḥāwurakumā, innallāha samī‘um baṣīr(un).", "Sungguh, اللّه telah mendengar ucapan wanita yang mengajukan gugatan kepadamu (Nabi Muhammad) tentang suaminya dan mengadukan kepada اللّه, padahal اللّه mendengar percakapan kamu berdua. Sesungguhnya اللّه Maha Mendengar lagi Maha Melihat."),
    Ayah(2, 58, "اَلَّذِيْنَ يُظٰهِرُوْنَ مِنْكُمْ مِّنْ نِّسَاۤىِٕهِمْ مَّا هُنَّ اُمَّهٰتِهِمْۗ اِنْ اُمَّهٰتُهُمْ اِلَّا الّٰۤـِٔيْ وَلَدْنَهُمْۗ وَاِنَّهُمْ لَيَقُوْلُوْنَ مُنْكَرًا مِّنَ الْقَوْلِ وَزُوْرًاۗ وَاِنَّ اللّٰهَ لَعَفُوٌّ غَفُوْرٌ", "Allażīna yuẓāhirūna minkum min nisā'ihim mā hunna ummahātihim, in ummahātuhum illal-lā'ī waladnahum, wa innahum layaqūlūna munkaram minal-qauli wa zūrā(n), wa innallāha la‘afuwwun gafūr(un).", "Orang-orang yang menzihar istrinya (menganggapnya sebagai ibu) di antara kamu, istri mereka itu bukanlah ibunya. Ibu-ibu mereka tidak lain hanyalah perempuan yang melahirkannya. Sesungguhnya mereka benar-benar telah mengucapkan suatu perkataan yang mungkar dan dusta. Sesungguhnya اللّه benar-benar Maha Pemaaf lagi Maha Pengampun."),
    Ayah(3, 58, "وَالَّذِيْنَ يُظٰهِرُوْنَ مِنْ نِّسَاۤىِٕهِمْ ثُمَّ يَعُوْدُوْنَ لِمَا قَالُوْا فَتَحْرِيْرُ رَقَبَةٍ مِّنْ قَبْلِ اَنْ يَّتَمَاۤسَّاۗ ذٰلِكُمْ تُوْعَظُوْنَ بِهٖۗ وَاللّٰهُ بِمَا تَعْمَلُوْنَ خَبِيْرٌ", "Wal-lażīna yuẓāhirūna min nisā'ihim ṡumma ya‘ūdūna limā qālū fa taḥrīru raqabatim min qabli ay yatamāssā, żālikum tū‘aẓūna bih(ī), wallāhu bimā ta‘malūna khabīr(un).", "Orang-orang yang menzihar istrinya kemudian menarik kembali apa yang telah mereka ucapkan wajibmemerdekakan seorang budak sebelum kedua suami istri itu berhubungan badan. Demikianlah yang diajarkan kepadamu. اللّه Mahateliti terhadap apa yang kamu kerjakan."),
    Ayah(4, 58, "فَمَنْ لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ مِنْ قَبْلِ اَنْ يَّتَمَاۤسَّاۗ فَمَنْ لَّمْ يَسْتَطِعْ فَاِطْعَامُ سِتِّيْنَ مِسْكِيْنًاۗ ذٰلِكَ لِتُؤْمِنُوْا بِاللّٰهِ وَرَسُوْلِهٖۗ وَتِلْكَ حُدُوْدُ اللّٰهِ ۗوَلِلْكٰفِرِيْنَ عَذَابٌ اَلِيْمٌ", "Famal lam yajid faṣiyāmu syahraini mutatābi‘aini min qabli ay yatamāssā, famal lam yastaṭi‘ fa iṭ‘āmu sittīna miskīnā(n), żālika litu'minū billāhi wa rasūlih(ī), wa tilka ḥudūdullāh(i), wa lil-kāfirīna ‘ażābun alīm(un).", "Siapa yang tidak mendapatkan (hamba sahaya) wajib berpuasa dua bulan berturut-turut sebelum keduanya berhubungan badan. Akan tetapi, siapa yang tidak mampu, (wajib) memberi makan enam puluh orang miskin. Demikianlah agar kamu beriman kepada اللّه dan Rasul-Nya. Itulah ketentuan-ketentuan اللّه. Orang-orang kafir mendapat azab yang pedih."),
    Ayah(5, 58, "اِنَّ الَّذِيْنَ يُحَاۤدُّوْنَ اللّٰهَ وَرَسُوْلَهٗ كُبِتُوْا كَمَا كُبِتَ الَّذِيْنَ مِنْ قَبْلِهِمْ وَقَدْ اَنْزَلْنَآ اٰيٰتٍۢ بَيِّنٰتٍۗ وَلِلْكٰفِرِيْنَ عَذَابٌ مُّهِيْنٌۚ", "Innal-lażīna yuḥāddūnallāha wa rasūlahū kubitū kamā kubital-lażīna min qablihim wa qad anzalnā āyātim bayyināt(in), wa lil-kāfirīna ‘ażābum muhīn(un).", "Sesungguhnya orang-orang yang menentang اللّه dan Rasul-Nya dihinakan sebagaimana dihinakan orang-orang sebelum mereka. Sungguh, Kami telah menurunkan bukti-bukti yang nyata. Orang-orang kafir mendapat azab yang menghinakan."),
    Ayah(6, 58, "يَوْمَ يَبْعَثُهُمُ اللّٰهُ جَمِيْعًا فَيُنَبِّئُهُمْ بِمَا عَمِلُوْاۗ اَحْصٰىهُ اللّٰهُ وَنَسُوْهُۗ وَاللّٰهُ عَلٰى كُلِّ شَيْءٍ شَهِيْدٌ ࣖ", "Yauma yab‘aṡuhumullāhu jamī‘an fa yunabbi'uhum bimā ‘amilū, aḥṣāhullāhu wa nasūh(u), wallāhu ‘alā kulli syai'in syahīd(un).", "Pada hari itu اللّه membangkitkan mereka semua, lalu Dia memberitakan kepada mereka apa yang telah mereka kerjakan. اللّه menghitungnya (semua amal) meskipun mereka telah melupakannya. اللّه Maha Menyaksikan segala sesuatu."),
    Ayah(7, 58, "اَلَمْ تَرَ اَنَّ اللّٰهَ يَعْلَمُ مَا فِى السَّمٰوٰتِ وَمَا فِى الْاَرْضِۗ مَا يَكُوْنُ مِنْ نَّجْوٰى ثَلٰثَةٍ اِلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ اِلَّا هُوَ سَادِسُهُمْ وَلَآ اَدْنٰى مِنْ ذٰلِكَ وَلَآ اَكْثَرَ اِلَّا هُوَ مَعَهُمْ اَيْنَ مَا كَانُوْاۚ ثُمَّ يُنَبِّئُهُمْ بِمَا عَمِلُوْا يَوْمَ الْقِيٰمَةِۗ اِنَّ اللّٰهَ بِكُلِّ شَيْءٍ عَلِيْمٌ", "Alam tara annallāha ya‘lamu mā fis-samāwāti wa mā fil-arḍ(i), mā yakūnu min najwā ṡalāṡatin illā huwa rābi‘uhum wa lā khamsatin illā huwa sādisuhum wa lā adnā min żālika wa lā akṡara illā huwa ma‘ahum aina mā kānū, ṡumma yunabbi'uhum bimā ‘amilū yaumal-qiyāmah(ti), innallāha bikulli syai'in ‘alīm(un).", "Apakah engkau tidak memperhatikan bahwa اللّه mengetahui apa yang ada di langit dan apa yang ada di bumi? Tidak ada pembicaraan rahasia antara tiga orang, kecuali Dialah yang keempatnya dan tidak ada lima orang, kecuali Dialah yang keenamnya. Tidak kurang dari itu atau lebih banyak, kecuali Dia bersama mereka di mana pun mereka berada. Kemudian, Dia memberitakan apa yang telah mereka kerjakan kepada mereka pada hari Kiamat. Sesungguhnya اللّه Maha Mengetahui segala sesuatu."),
    Ayah(8, 58, "اَلَمْ تَرَ اِلَى الَّذِيْنَ نُهُوْا عَنِ النَّجْوٰى ثُمَّ يَعُوْدُوْنَ لِمَا نُهُوْا عَنْهُ وَيَتَنٰجَوْنَ بِالْاِثْمِ وَالْعُدْوَانِ وَمَعْصِيَتِ الرَّسُوْلِۖ وَاِذَا جَاۤءُوْكَ حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ بِهِ اللّٰهُ ۙوَيَقُوْلُوْنَ فِيْٓ اَنْفُسِهِمْ لَوْلَا يُعَذِّبُنَا اللّٰهُ بِمَا نَقُوْلُۗ حَسْبُهُمْ جَهَنَّمُۚ يَصْلَوْنَهَاۚ فَبِئْسَ الْمَصِيْرُ", "Alam tara ilal-lażīna nuhū ‘anin-najwā ṡummā ya‘ūdūna limā nuhū ‘anhu wa yatanājauna bil-iṡmi wal-‘udwāni wa ma‘ṣiyatir-rasūl(i), wa iżā jā'ūka ḥayyauka bimā lam yuḥayyika bihillāh(u), wa yaqūlūna fī anfusihim lau lā yu‘ażżibunallāhu bimā naqūl(u), ḥasbuhum jahannam(u), yaṣlaunahā, fa bi'sal-maṣīr(u).", "Apakah engkau tidak memperhatikan orang-orang yang telah dilarang mengadakan pembicaraan rahasia, kemudian mereka kembali (melakukan) apa yang telah dilarang itu? Mereka saling mengadakan pembicaraan rahasia untuk berbuat dosa, permusuhan, dan durhaka kepada Rasul. Apabila datang kepadamu (Nabi Muhammad), mereka mengucapkan salam kepadamu dengan cara yang bukan sebagaimana yang ditentukan اللّه untukmu. Mereka mengatakan dalam hati, “Mengapa اللّه tidak menyiksa kita atas apa yang kita katakan?” Cukuplah bagi mereka (neraka) Jahanam yang akan mereka masuki. Maka, (neraka itu) seburuk-buruk tempat kembali."),
    Ayah(9, 58, "يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْٓا اِذَا تَنَاجَيْتُمْ فَلَا تَتَنَاجَوْا بِالْاِثْمِ وَالْعُدْوَانِ وَمَعْصِيَتِ الرَّسُوْلِ وَتَنَاجَوْا بِالْبِرِّ وَالتَّقْوٰىۗ وَاتَّقُوا اللّٰهَ الَّذِيْٓ اِلَيْهِ تُحْشَرُوْنَ", "Yā ayyuhal-lażīna āmanū iżā tanājaitum falā tatanājau bil-iṡmi wal-‘udwāni wa ma‘ṣiyatir-rasūli wa tanājau bil-birri wat-taqwā, wattaqullāhal-lażī ilaihi tuḥsyarūn(a).", "Wahai orang-orang yang beriman, apabila kamu saling mengadakan pembicaraan rahasia, janganlah berbicara tentang perbuatan dosa, permusuhan, dan durhaka kepada Rasul. Akan tetapi, berbicaralah tentang perbuatan kebajikan dan takwa. Bertakwalah kepada اللّه yang hanya kepada-Nya kamu akan dikumpulkan."),
    Ayah(10, 58, "اِنَّمَا النَّجْوٰى مِنَ الشَّيْطٰنِ لِيَحْزُنَ الَّذِيْنَ اٰمَنُوْا وَلَيْسَ بِضَاۤرِّهِمْ شَيْـًٔا اِلَّا بِاِذْنِ اللّٰهِ ۗوَعَلَى اللّٰهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُوْنَ", "Innaman-najwā minasy-syaiṭāni liyaḥzunal-lażīna āmanū wa laisa biḍārrihim syai'an illā bi'iżnillāh(i), wa ‘alallāhi falyatawakkalil-mu'minūn(a).", "Sesungguhnya pembicaraan rahasia itu hanyalah dari setan, agar orang-orang yang beriman itu bersedih hati, sedangkan (pembicaraan) itu tidaklah memberi mudarat sedikit pun kepada mereka, kecuali dengan izin اللّه. Hanya kepada اللّه hendaknya orang-orang mukmin bertawakal."),
    Ayah(11, 58, "يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْٓا اِذَا قِيْلَ لَكُمْ تَفَسَّحُوْا فِى الْمَجٰلِسِ فَافْسَحُوْا يَفْسَحِ اللّٰهُ لَكُمْۚ وَاِذَا قِيْلَ انْشُزُوْا فَانْشُزُوْا يَرْفَعِ اللّٰهُ الَّذِيْنَ اٰمَنُوْا مِنْكُمْۙ وَالَّذِيْنَ اُوْتُوا الْعِلْمَ دَرَجٰتٍۗ وَاللّٰهُ بِمَا تَعْمَلُوْنَ خَبِيْرٌ", "Yā ayyuhal-lażīna āmanū iżā qīla lakum tafassaḥū fil-majālisi fafsaḥū yafsaḥillāhu lakum, wa iżā qīlansyuzū fansyuzū yarfa‘illāhul-lażīna āmanū minkum, wal-lażīna ūtul-‘ilma darajāt(in), wallāhu bimā ta‘malūna khabīr(un).", "Wahai orang-orang yang beriman, apabila dikatakan kepadamu “Berilah kelapangan di dalam majelis-majelis,” lapangkanlah, niscaya اللّه akan memberi kelapangan untukmu. Apabila dikatakan, “Berdirilah,” (kamu) berdirilah. اللّه niscaya akan mengangkat orang-orang yang beriman di antaramu dan orang-orang yang diberi ilmu beberapa derajat. اللّه Mahateliti terhadap apa yang kamu kerjakan."),
    Ayah(12, 58, "يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْٓا اِذَا نَاجَيْتُمُ الرَّسُوْلَ فَقَدِّمُوْا بَيْنَ يَدَيْ نَجْوٰىكُمْ صَدَقَةً ۗذٰلِكَ خَيْرٌ لَّكُمْ وَاَطْهَرُۗ فَاِنْ لَّمْ تَجِدُوْا فَاِنَّ اللّٰهَ غَفُوْرٌ رَّحِيْمٌ", "Yā ayyuhal-lażīna āmanū iżā nājaitumur-rasūla fa qaddimū baina yaday najwākum ṣadaqah(tan), żālika khairul lakum wa aṭhar(u), fa'illam tajidū fa innallāha gafūrur raḥīm(un).", "Wahai orang-orang yang beriman, apabila kamu (ingin) melakukan pembicaraan rahasia dengan Rasul, hendaklah kamu mengeluarkan sedekah (kepada orang miskin) sebelum (melakukan) pembicaraan itu. Hal itu lebih baik bagimu dan lebih bersih. Akan tetapi, jika kamu tidak mendapatkan (apa yang akan disedekahkan), sesungguhnya اللّه Maha Pengampun lagi Maha Penyayang."),
    Ayah(13, 58, "ءَاَشْفَقْتُمْ اَنْ تُقَدِّمُوْا بَيْنَ يَدَيْ نَجْوٰىكُمْ صَدَقٰتٍۗ فَاِذْ لَمْ تَفْعَلُوْا وَتَابَ اللّٰهُ عَلَيْكُمْ فَاَقِيْمُوا الصَّلٰوةَ وَاٰتُوا الزَّكٰوةَ وَاَطِيْعُوا اللّٰهَ وَرَسُوْلَهٗ ۗوَاللّٰهُ خَبِيْرٌ ۢبِمَا تَعْمَلُوْنَ ࣖ", "A'asyfaqtum an tuqaddimū baina yaday najwākum ṣadaqāt(in), fa iż lam taf‘alū wa tāballāhu ‘alaikum fa'aqīmuṣ-ṣalāta wa ātuz-zakāta wa aṭī‘ullāha wa rasūlah(ūwallāhu khabīrum bimā ta‘malūn(a).", "Apakah kamu takut (menjadi miskin) jika mengeluarkan sedekah sebelum (melakukan) pembicaraan rahasia dengan Rasul? Jika kamu tidak melakukannya dan اللّه mengampunimu, tegakkanlah salat, tunaikanlah zakat, serta taatlah kepada اللّه dan Rasul-Nya. اللّه Mahateliti terhadap apa yang kamu kerjakan."),
    Ayah(14, 58, "۞ اَلَمْ تَرَ اِلَى الَّذِيْنَ تَوَلَّوْا قَوْمًا غَضِبَ اللّٰهُ عَلَيْهِمْۗ مَا هُمْ مِّنْكُمْ وَلَا مِنْهُمْۙ وَيَحْلِفُوْنَ عَلَى الْكَذِبِ وَهُمْ يَعْلَمُوْنَ", "Alam tara ilal-lażīna tawallau qauman gaḍiballāhu ‘alaihim, mā hum minkum wa lā minhum, wa yaḥlifūna ‘alal-każibi wa hum ya‘lamūn(a).", "Tidakkah engkau memperhatikan orang-orang (munafik) yang menjadikan suatu kaum yang dimurkai اللّه sebagai sahabat? Orang-orang itu bukan dari (kaum)-mu dan bukan dari (kaum) mereka. Mereka bersumpah secara dusta (mengaku mukmin), padahal mereka mengetahuinya."),
    Ayah(15, 58, "اَعَدَّ اللّٰهُ لَهُمْ عَذَابًا شَدِيْدًاۗ اِنَّهُمْ سَاۤءَ مَا كَانُوْا يَعْمَلُوْنَ", "A‘addallāhu lahum ‘ażāban syadīdā(n), innahum sā'a mā kānū ya‘malūn(a).", "اللّه telah menyediakan azab yang sangat keras bagi mereka. Sesungguhnya sangat buruk apa yang selalu mereka kerjakan."),
    Ayah(16, 58, "اِتَّخَذُوْٓا اَيْمَانَهُمْ جُنَّةً فَصَدُّوْا عَنْ سَبِيْلِ اللّٰهِ فَلَهُمْ عَذَابٌ مُّهِيْنٌ", "Ittakhażū aimānahum junnatan fa ṣaddū ‘an sabīlillāhi falahum ‘ażābum muhīn(un).", "Mereka menjadikan sumpah-sumpahnya sebagai perisai, lalu menghalang-halangi (manusia) dari jalan اللّه. Maka, bagi mereka azab yang menghinakan."),
    Ayah(17, 58, "لَنْ تُغْنِيَ عَنْهُمْ اَمْوَالُهُمْ وَلَآ اَوْلَادُهُمْ مِّنَ اللّٰهِ شَيْـًٔاۗ اُولٰۤىِٕكَ اَصْحٰبُ النَّارِۗ هُمْ فِيْهَا خٰلِدُوْنَ", "Lan tugniya ‘anhum amwāluhum wa lā aulāduhum minallāhi syai'ā(n), ulā'ika aṣḥābun-nār(i), hum fīhā khālidūn(a).", "Harta benda dan anak-anak mereka tidak berguna sedikit pun (untuk menolong mereka) dari (azab) اللّه. Mereka itulah penghuni neraka. Mereka kekal di dalamnya."),
    Ayah(18, 58, "يَوْمَ يَبْعَثُهُمُ اللّٰهُ جَمِيْعًا فَيَحْلِفُوْنَ لَهٗ كَمَا يَحْلِفُوْنَ لَكُمْ وَيَحْسَبُوْنَ اَنَّهُمْ عَلٰى شَيْءٍۗ اَلَآ اِنَّهُمْ هُمُ الْكٰذِبُوْنَ", "Yauma yab‘aṡuhumullāhu jamī‘an fa yaḥlifūna lahū kamā yaḥlifūna lakum wa yaḥsabūna annahum ‘alā syai'(in), alā innahum humul-kāżibūn(a).", "(Ingatlah) pada hari (ketika) اللّه membangkitkan mereka semuanya. Lalu, mereka bersumpah kepada-Nya (bahwa mereka mukmin) sebagaimana mereka bersumpah kepadamu. Mereka menyangka bahwa mereka akan memperoleh sesuatu (manfaat dari dustanya). Ketahuilah, sesungguhnya mereka adalah para pendusta."),
    Ayah(19, 58, "اِسْتَحْوَذَ عَلَيْهِمُ الشَّيْطٰنُ فَاَنْسٰىهُمْ ذِكْرَ اللّٰهِ ۗ اُولٰۤىِٕكَ حِزْبُ الشَّيْطٰنِۗ اَلَآ اِنَّ حِزْبَ الشَّيْطٰنِ هُمُ الْخٰسِرُوْنَ", "Istaḥważa ‘alaihimusy-syaiṭānu fa'ansāhum żikrallāh(i), ulā'ika ḥizbusy-syaiṭān(i), alā inna ḥizbasy-syaiṭāni humul-khāsirūn(a).", "Setan telah menguasai mereka, lalu menjadikannya lupa mengingat اللّه. Mereka itulah golongan setan. Ketahuilah sesungguhnya golongan setan itulah orang-orang yang rugi."),
    Ayah(20, 58, "اِنَّ الَّذِيْنَ يُحَاۤدُّوْنَ اللّٰهَ وَرَسُوْلَهٗٓ اُولٰۤىِٕكَ فِى الْاَذَلِّيْنَ", "Innal-lażīna yuḥāddūnallāha wa rasūlahū ulā'ika fil-ażallīn(a).", "Sesungguhnya orang-orang yang menentang اللّه dan Rasul-Nya, mereka termasuk orang-orang yang sangat hina."),
    Ayah(21, 58, "كَتَبَ اللّٰهُ لَاَغْلِبَنَّ اَنَا۠ وَرُسُلِيْۗ اِنَّ اللّٰهَ قَوِيٌّ عَزِيْزٌ", "Kataballāhu la'aglibanna ana wa rusulī, innallāha qawiyyun ‘azīz(un).", "اللّه telah menetapkan, “Aku dan rasul-rasul-Ku pasti menang.” Sesungguhnya اللّه Mahakuat lagi Mahaperkasa."),
    Ayah(22, 58, "لَا تَجِدُ قَوْمًا يُّؤْمِنُوْنَ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِ يُوَاۤدُّوْنَ مَنْ حَاۤدَّ اللّٰهَ وَرَسُوْلَهٗ وَلَوْ كَانُوْٓا اٰبَاۤءَهُمْ اَوْ اَبْنَاۤءَهُمْ اَوْ اِخْوَانَهُمْ اَوْ عَشِيْرَتَهُمْۗ اُولٰۤىِٕكَ كَتَبَ فِيْ قُلُوْبِهِمُ الْاِيْمَانَ وَاَيَّدَهُمْ بِرُوْحٍ مِّنْهُ ۗوَيُدْخِلُهُمْ جَنّٰتٍ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِيْنَ فِيْهَاۗ رَضِيَ اللّٰهُ عَنْهُمْ وَرَضُوْا عَنْهُۗ اُولٰۤىِٕكَ حِزْبُ اللّٰهِ ۗ اَلَآ اِنَّ حِزْبَ اللّٰهِ هُمُ الْمُفْلِحُوْنَ ࣖ", "Lā tajidu qaumay yu'minūna billāhi wal-yaumil ākhiri yuwāddūna man ḥāddallāha wa rasūlahū wa lau kānū ābā'ahum au abnā'ahum au ikhwānahum au ‘asyīratahum, ulā'ika kataba fī qulūbihimul-īmāna wa ayyadahum birūḥim minh(u), wa yudkhiluhum jannātin tajrī min taḥtihal-anhāru khālidīna fīhā, raḍiyallāhu ‘anhum wa raḍū ‘anh(u), ulā'ika ḥizbullāh(i), alā inna ḥizballāhi humul-mufliḥūn(a).", "Engkau (Nabi Muhammad) tidak akan mendapatkan suatu kaum yang beriman kepada اللّه dan hari Akhir saling berkasih sayang dengan orang yang menentang اللّه dan Rasul-Nya sekalipun mereka itu bapaknya, anaknya, saudaranya, atau kerabatnya. Mereka itulah orang-orang yang telah اللّه tetapkan keimanan di dalam hatinya dan menguatkan mereka dengan pertolongan dari-Nya. Dia akan memasukkan mereka ke dalam surga yang mengalir di bawahnya sungai-sungai. Mereka kekal di dalamnya. اللّه rida kepada mereka dan mereka pun rida kepada-Nya. Merekalah golongan اللّه. Ingatlah, sesungguhnya golongan اللّه itulah orang-orang yang beruntung."),
)

internal fun quranFullAyahs59(): List<Ayah> = listOf(
    Ayah(1, 59, "سَبَّحَ لِلّٰهِ مَا فِى السَّمٰوٰتِ وَمَا فِى الْاَرْضِۚ وَهُوَ الْعَزِيْزُ الْحَكِيْمُ", "Sabbaḥa lillāhi mā fis-samāwāti wa mā fil-arḍ(i), wa huwal-‘azīzul-ḥakīm(u).", "Apa yang ada di langit dan apa yang ada di bumi bertasbih kepada اللّه. Dialah Yang Mahaperkasa lagi Mahabijaksana."),
    Ayah(2, 59, "هُوَ الَّذِيْٓ اَخْرَجَ الَّذِيْنَ كَفَرُوْا مِنْ اَهْلِ الْكِتٰبِ مِنْ دِيَارِهِمْ لِاَوَّلِ الْحَشْرِۗ مَا ظَنَنْتُمْ اَنْ يَّخْرُجُوْا وَظَنُّوْٓا اَنَّهُمْ مَّانِعَتُهُمْ حُصُوْنُهُمْ مِّنَ اللّٰهِ فَاَتٰىهُمُ اللّٰهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوْا وَقَذَفَ فِيْ قُلُوْبِهِمُ الرُّعْبَ يُخْرِبُوْنَ بُيُوْتَهُمْ بِاَيْدِيْهِمْ وَاَيْدِى الْمُؤْمِنِيْنَۙ فَاعْتَبِرُوْا يٰٓاُولِى الْاَبْصَارِ", "Huwal-lażī akhrajal-lażīna kafarū min ahlil-kitābi min diyārihim li'awwalil-ḥasyr(i), mā ẓanantum ay yakhrujū wa ẓannū annahum māni‘atuhum ḥuṣūnuhum minallāhi fa atāhumullāhu min ḥaiṡu lam yaḥtasibū wa qażafa fī qulūbihimur-ru‘ba yukhribūna buyūtahum bi'aidīhim wa aidil-mu'minīn(a), fa‘tabirū yā ulil-abṣār(i).", "Dialah yang mengeluarkan orang-orang yang kufur di antara Ahlulkitab (Yahudi Bani Nadir) dari kampung halaman mereka pada saat pengusiran yang pertama. Kamu tidak menyangka bahwa mereka akan keluar. Mereka pun yakin bahwa benteng-benteng mereka akan dapat menjaganya dari (azab) اللّه. Maka, (azab) اللّه datang kepada mereka dari arah yang tidak mereka sangka. Dia menanamkan rasa takut di dalam hati mereka sehingga mereka menghancurkan rumah-rumahnya dengan tangannya sendiri dan tangan orang-orang mukmin. Maka, ambillah pelajaran (dari kejadian itu), wahai orang-orang yang mempunyai penglihatan (mata hati)."),
    Ayah(3, 59, "وَلَوْلَآ اَنْ كَتَبَ اللّٰهُ عَلَيْهِمُ الْجَلَاۤءَ لَعَذَّبَهُمْ فِى الدُّنْيَاۗ وَلَهُمْ فِى الْاٰخِرَةِ عَذَابُ النَّارِ", "Wa lau lā an kataballāhu ‘alaihimul-jalā'a la‘ażżabahum fid-dun-yā, wa lahum fil-ākhirati ‘ażābun-nār(i).", "Sekiranya tidak karena اللّه telah menetapkan pengusiran terhadap mereka, Dia pasti mengazab mereka di dunia. Di akhirat mereka akan mendapat azab neraka."),
    Ayah(4, 59, "ذٰلِكَ بِاَنَّهُمْ شَاۤقُّوا اللّٰهَ وَرَسُوْلَهٗ ۖوَمَنْ يُّشَاۤقِّ اللّٰهَ فَاِنَّ اللّٰهَ شَدِيْدُ الْعِقَابِ", "Żālika bi'annahum syāqqullāha wa rasūlah(ū), wa may yusyāqqillāha fa'innallāha syadīdul-‘iqāb(i).", "Hal yang demikian itu karena sesungguhnya mereka telah menentang اللّه dan Rasul-Nya. Siapa yang menentang اللّه, sesungguhnya اللّه sangat keras hukuman-Nya."),
    Ayah(5, 59, "مَا قَطَعْتُمْ مِّنْ لِّيْنَةٍ اَوْ تَرَكْتُمُوْهَا قَاۤىِٕمَةً عَلٰٓى اُصُوْلِهَا فَبِاِذْنِ اللّٰهِ وَلِيُخْزِيَ الْفٰسِقِيْنَ", "Mā qaṭa‘tum mil līnatin au taraktumūhā qā'imatan ‘alā uṣūlihā fa bi'iżnillāhi wa liyukhziyal-fāsiqīn(a).", "Apa yang kamu tebang di antara pohon kurma (milik Yahudi Bani Nadir) atau yang kamu biarkan berdiri di atas pokoknya, (itu terjadi) dengan izin اللّه dan (juga) karena Dia hendak menghinakan orang-orang fasik."),
    Ayah(6, 59, "وَمَآ اَفَاۤءَ اللّٰهُ عَلٰى رَسُوْلِهٖ مِنْهُمْ فَمَآ اَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَّلَا رِكَابٍ وَّلٰكِنَّ اللّٰهَ يُسَلِّطُ رُسُلَهٗ عَلٰى مَنْ يَّشَاۤءُۗ وَاللّٰهُ عَلٰى كُلِّ شَيْءٍ قَدِيْرٌ", "Wa mā afā'allāhu ‘alā rasūlihī minhum famā aujaftum ‘alaihi min khailiw wa lā rikābiw wa lākinnallāha yusalliṭu rusulahū ‘alā may yasyā'(u), wallāhu ‘alā kulli syai'in qadīr(un).", "Apa saja (harta yang diperoleh tanpa peperangan) yang dianugerahkan اللّه kepada Rasul-Nya dari mereka tidak (perlu) kamu memacu kuda atau unta (untuk mendapatkannya). Akan tetapi, اللّه memberikan kekuasaan kepada rasul-rasul-Nya terhadap siapa yang Dia kehendaki. اللّه Mahakuasa atas segala sesuatu."),
    Ayah(7, 59, "مَآ اَفَاۤءَ اللّٰهُ عَلٰى رَسُوْلِهٖ مِنْ اَهْلِ الْقُرٰى فَلِلّٰهِ وَلِلرَّسُوْلِ وَلِذِى الْقُرْبٰى وَالْيَتٰمٰى وَالْمَسٰكِيْنِ وَابْنِ السَّبِيْلِۙ كَيْ لَا يَكُوْنَ دُوْلَةً ۢ بَيْنَ الْاَغْنِيَاۤءِ مِنْكُمْۗ وَمَآ اٰتٰىكُمُ الرَّسُوْلُ فَخُذُوْهُ وَمَا نَهٰىكُمْ عَنْهُ فَانْتَهُوْاۚ وَاتَّقُوا اللّٰهَ ۗاِنَّ اللّٰهَ شَدِيْدُ الْعِقَابِۘ", "Mā afā'allāhu ‘alā rasūlihī min ahlil-qurā fa lillāhi wa lir-rasūli wa liżil-qurbā wal-yatāmā wal-masākīni wabnis-sabīl(i), kailā yakūna dūlatam bainal-agniyā'i minkum, wa mā ātākumur-rasūlu fa khużūhu wa mā nahākum ‘anhu fantahū, wattaqullāh(a), innallāha syadīdul-‘iqāb(i).", "Apa saja (harta yang diperoleh tanpa peperangan) yang dianugerahkan اللّه kepada Rasul-Nya dari penduduk beberapa negeri adalah untuk اللّه, Rasul, kerabat (Rasul), anak yatim, orang miskin, dan orang yang dalam perjalanan. (Demikian) agar harta itu tidak hanya beredar di antara orang-orang kaya saja di antara kamu. Apa yang diberikan Rasul kepadamu terimalah. Apa yang dilarangnya bagimu tinggalkanlah. Bertakwalah kepada اللّه. Sesungguhnya اللّه sangat keras hukuman-Nya."),
    Ayah(8, 59, "لِلْفُقَرَاۤءِ الْمُهٰجِرِيْنَ الَّذِيْنَ اُخْرِجُوْا مِنْ دِيَارِهِمْ وَاَمْوَالِهِمْ يَبْتَغُوْنَ فَضْلًا مِّنَ اللّٰهِ وَرِضْوَانًا وَّيَنْصُرُوْنَ اللّٰهَ وَرَسُوْلَهٗ ۗ اُولٰۤىِٕكَ هُمُ الصّٰدِقُوْنَۚ", "Lil-fuqarā'il-muhājirīnal-lażīna ukhrijū min diyārihim wa amwālihim yabtagūna faḍlam minallāhi wa riḍwānaw wa yanṣurūnallāha wa rasūlah(ū), ulā'ika humuṣ-ṣādiqūn(a).", "(Harta rampasan itu pula) untuk orang-orang fakir yang berhijrah, yaitu orang-orang yang diusir dari kampung halamannya dan (meninggalkan) harta bendanya demi mencari karunia dari اللّه, keridaan(-Nya), serta (demi) menolong (agama) اللّه dan Rasul-Nya. Mereka itulah orang-orang benar."),
    Ayah(9, 59, "وَالَّذِيْنَ تَبَوَّءُو الدَّارَ وَالْاِيْمَانَ مِنْ قَبْلِهِمْ يُحِبُّوْنَ مَنْ هَاجَرَ اِلَيْهِمْ وَلَا يَجِدُوْنَ فِيْ صُدُوْرِهِمْ حَاجَةً مِّمَّآ اُوْتُوْا وَيُؤْثِرُوْنَ عَلٰٓى اَنْفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ ۗوَمَنْ يُّوْقَ شُحَّ نَفْسِهٖ فَاُولٰۤىِٕكَ هُمُ الْمُفْلِحُوْنَۚ", "Wal-lażīna tabawwa'ud-dāra wal-īmāna min qablihim yuḥibbūna man hājara ilaihim wa lā yajidūna fī ṣudūrihim ḥājatam mimmā ūtū wa yu'ṡirūna ‘alā anfusihim wa lau kāna bihim khaṣāṣah(tun), wa may yūqa syuḥḥa nafsihī fa ulā'ika humul-mufliḥūn(a).", "Orang-orang (Ansar) yang telah menempati kota (Madinah) dan beriman sebelum (kedatangan) mereka (Muhajirin) mencintai orang yang berhijrah ke (tempat) mereka. Mereka tidak mendapatkan keinginan di dalam hatinya terhadap apa yang diberikan (kepada Muhajirin). Mereka mengutamakan (Muhajirin) daripada dirinya sendiri meskipun mempunyai keperluan yang mendesak. Siapa yang dijaga dirinya dari kekikiran itulah orang-orang yang beruntung."),
    Ayah(10, 59, "وَالَّذِيْنَ جَاۤءُوْ مِنْۢ بَعْدِهِمْ يَقُوْلُوْنَ رَبَّنَا اغْفِرْ لَنَا وَلِاِخْوَانِنَا الَّذِيْنَ سَبَقُوْنَا بِالْاِيْمَانِ وَلَا تَجْعَلْ فِيْ قُلُوْبِنَا غِلًّا لِّلَّذِيْنَ اٰمَنُوْا رَبَّنَآ اِنَّكَ رَءُوْفٌ رَّحِيْمٌ ࣖ", "Wal-lażīna jā'ū mim ba‘dihim yaqūlūna rabbanagfir lanā wa li'ikhwāninal-lażīna sabaqūnā bil-īmāni wa lā taj‘al fī qulūbinā gillal lil-lażīna āmanū rabbanā innaka ra'ūfur raḥīm(un).", "Orang-orang yang datang sesudah mereka (Muhajirin dan Ansar) berdoa, “Ya Tuhan kami, ampunilah kami serta saudara-saudara kami yang telah beriman lebih dahulu daripada kami dan janganlah Engkau jadikan dalam hati kami kedengkian terhadap orang-orang yang beriman. Ya Tuhan kami, sesungguhnya Engkaulah Yang Maha Penyantun lagi Maha Penyayang.”"),
    Ayah(11, 59, "۞ اَلَمْ تَرَ اِلَى الَّذِيْنَ نَافَقُوْا يَقُوْلُوْنَ لِاِخْوَانِهِمُ الَّذِيْنَ كَفَرُوْا مِنْ اَهْلِ الْكِتٰبِ لَىِٕنْ اُخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلَا نُطِيْعُ فِيْكُمْ اَحَدًا اَبَدًاۙ وَّاِنْ قُوْتِلْتُمْ لَنَنْصُرَنَّكُمْۗ وَاللّٰهُ يَشْهَدُ اِنَّهُمْ لَكٰذِبُوْنَ", "Alam tara ilal-lażīna nāfaqū yaqūlūna li'ikhwānihimul-lażīna kafarū min ahlil-kitābi la'in ukhrijtum lanakhrujanna ma‘akum wa lā nuṭī‘u fīkum aḥadan abadā(n), wa in qūtiltum lananṣurannakum, wallāhu yasyhadu innahum lakāżibūn(a).", "Tidakkah engkau memperhatikan orang-orang munafik? Mereka berkata kepada saudara-saudaranya yang kufur di antara Ahlulkitab, “Sungguh, jika kamu diusir, kami pasti akan keluar bersamamu dan kami selamanya tidak akan patuh kepada siapa pun demi kamu. Jika kamu diperangi, kami pasti menolongmu.” اللّه bersaksi bahwa mereka benar-benar para pendusta."),
    Ayah(12, 59, "لَىِٕنْ اُخْرِجُوْا لَا يَخْرُجُوْنَ مَعَهُمْۚ وَلَىِٕنْ قُوْتِلُوْا لَا يَنْصُرُوْنَهُمْۚ وَلَىِٕنْ نَّصَرُوْهُمْ لَيُوَلُّنَّ الْاَدْبَارَۙ ثُمَّ لَا يُنْصَرُوْنَ", "La'in ukhrijū lā yakhrujūna ma‘ahum, wa la'in qūtilū lā yanṣurūnahum, wa la'in naṣarūhum layuwallunnal-adbār(a), ṡumma lā yunṣarūn(a).", "Jika mereka benar-benar diusir, orang-orang (munafik) itu tidak akan keluar bersama mereka. Jika mereka benar-benar diperangi, orang-orang (munafik) itu tidak akan menolongnya. Kalaupun menolongnya, niscaya orang-orang (munafik) itu akan berpaling (untuk lari) ke belakang, kemudian mereka tidak akan ditolong."),
    Ayah(13, 59, "لَاَنْتُمْ اَشَدُّ رَهْبَةً فِيْ صُدُوْرِهِمْ مِّنَ اللّٰهِ ۗذٰلِكَ بِاَنَّهُمْ قَوْمٌ لَّا يَفْقَهُوْنَ", "La'antum asyaddu rahbatan fī ṣudūrihim minallāh(i), żālika bi'annahum qaumul lā yafqahūn(a).", "Kamu (kaum yang beriman) benar-benar lebih ditakuti di dalam hati mereka daripada اللّه. Hal itu disebabkan mereka kaum yang tidak mengerti."),
    Ayah(14, 59, "لَا يُقَاتِلُوْنَكُمْ جَمِيْعًا اِلَّا فِيْ قُرًى مُّحَصَّنَةٍ اَوْ مِنْ وَّرَاۤءِ جُدُرٍۗ بَأْسُهُمْ بَيْنَهُمْ شَدِيْدٌ ۗ تَحْسَبُهُمْ جَمِيْعًا وَّقُلُوْبُهُمْ شَتّٰىۗ ذٰلِكَ بِاَنَّهُمْ قَوْمٌ لَّا يَعْقِلُوْنَۚ", "Lā yuqātilūnakum jamī‘an illā fī quram muḥaṣṣanatin au miw warā'i judur(in), ba'suhum bainahum syadīd(un), taḥsabuhum jamī‘aw wa qulūbuhum syattā, żālika bi'annahum qaumul lā ya‘qilūn(a).", "Mereka tidak akan memerangi kamu (secara) bersama-sama, kecuali di negeri-negeri yang berbenteng atau di balik tembok. Permusuhan antar sesama mereka sangat hebat. Kamu mengira bahwa mereka itu bersatu, padahal hati mereka terpecah belah. Hal itu disebabkan mereka kaum yang tidak berakal."),
    Ayah(15, 59, "كَمَثَلِ الَّذِيْنَ مِنْ قَبْلِهِمْ قَرِيْبًا ذَاقُوْا وَبَالَ اَمْرِهِمْۚ وَلَهُمْ عَذَابٌ اَلِيْمٌۚ", "Kamaṡalil-lażīna min qablihim qarīban żāqū wabāla amrihim, wa lahum ‘ażābun alīm(un).", "(Kaum Yahudi itu) seperti orang-orang sebelumnya (musyrik Makkah) yang belum lama berselang telah merasakan akibat buruk perbuatannya sendiri (di dunia). Mereka akan mendapatkan azab yang pedih (di akhirat)."),
    Ayah(16, 59, "كَمَثَلِ الشَّيْطٰنِ اِذْ قَالَ لِلْاِنْسَانِ اكْفُرْۚ فَلَمَّا كَفَرَ قَالَ اِنِّيْ بَرِيْۤءٌ مِّنْكَ اِنِّيْٓ اَخَافُ اللّٰهَ رَبَّ الْعٰلَمِيْنَ", "Kamaṡalisy-syaiṭāni iż qāla lil-insānikfur, falammā kafara qāla innī barī'um minka innī akhāfullāha rabbal-‘ālamīn(a).", "(Perumpamaan bujukan orang-orang munafik kepada kaum Yahudi) seperti setan ketika berkata kepada manusia, “Kufurlah kamu!” Ketika orang itu kufur, ia berkata, “Sesungguhnya aku berlepas diri darimu karena sesungguhnya aku takut kepada اللّه, Tuhan semesta alam.”"),
    Ayah(17, 59, "فَكَانَ عَاقِبَتَهُمَآ اَنَّهُمَا فِى النَّارِ خٰلِدَيْنِ فِيْهَاۗ وَذٰلِكَ جَزٰۤؤُا الظّٰلِمِيْنَ ࣖ", "Fa kāna ‘āqibatahumā annahumā fin-nāri khālidaini fīhā, wa żālika jazā'uẓ-ẓālimīn(a).", "Maka, kesudahan bagi keduanya (setan dan manusia yang mengikutinya) bahwa keduanya berada dalam neraka, kekal di dalamnya. Itulah balasan bagi orang-orang zalim."),
    Ayah(18, 59, "يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اتَّقُوا اللّٰهَ وَلْتَنْظُرْ نَفْسٌ مَّا قَدَّمَتْ لِغَدٍۚ وَاتَّقُوا اللّٰهَ ۗاِنَّ اللّٰهَ خَبِيْرٌ ۢبِمَا تَعْمَلُوْنَ", "Yā ayyuhal-lażīna āmanuttaqullāha waltanẓur nafsum mā qaddamat ligad(in), wattaqullāh(a), innallāha khabīrum bimā ta‘malūn(a).", "Wahai orang-orang yang beriman, bertakwalah kepada اللّه dan hendaklah setiap orang memperhatikan apa yang telah diperbuatnya untuk hari esok (akhirat). Bertakwalah kepada اللّه. Sesungguhnya اللّه Mahateliti terhadap apa yang kamu kerjakan."),
    Ayah(19, 59, "وَلَا تَكُوْنُوْا كَالَّذِيْنَ نَسُوا اللّٰهَ فَاَنْسٰىهُمْ اَنْفُسَهُمْۗ اُولٰۤىِٕكَ هُمُ الْفٰسِقُوْنَ", "Wa lā takūnū kal-lażīna nasullāha fa'ansāhum anfusahum, ulā'ika humul-fāsiqūn(a).", "Janganlah kamu seperti orang-orang yang melupakan اللّه sehingga Dia menjadikan mereka lupa kepada diri mereka sendiri. Mereka itulah orang-orang fasik."),
    Ayah(20, 59, "لَا يَسْتَوِيْٓ اَصْحٰبُ النَّارِ وَاَصْحٰبُ الْجَنَّةِۗ اَصْحٰبُ الْجَنَّةِ هُمُ الْفَاۤىِٕزُوْنَ", "Lā yastawī aṣḥābun-nāri wa aṣḥābul-jannah(ti), aṣḥābul-jannati humul-fā'izūn(a).", "Tidak sama para penghuni neraka dengan para penghuni surga. Penghuni-penghuni surga itulah orang-orang yang memperoleh kemenangan."),
    Ayah(21, 59, "لَوْ اَنْزَلْنَا هٰذَا الْقُرْاٰنَ عَلٰى جَبَلٍ لَّرَاَيْتَهٗ خَاشِعًا مُّتَصَدِّعًا مِّنْ خَشْيَةِ اللّٰهِ ۗوَتِلْكَ الْاَمْثَالُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُوْنَ", "Lau anzalnā hāżal-qur'āna ‘alā jabalil lara'aitahū khāsyi‘am mutaṣaddi‘am min khasy-yatillāh(i), wa tilkal-amṡālu naḍribuhā lin-nāsi la‘allahum yatafakkarūn(a).", "Seandainya Kami turunkan Al-Qur’an ini kepada sebuah gunung, pasti kamu akan melihatnya tunduk terpecah belah karena takut kepada اللّه. Perumpamaan-perumpamaan itu Kami buat untuk manusia agar mereka berpikir."),
    Ayah(22, 59, "هُوَ اللّٰهُ الَّذِيْ لَآ اِلٰهَ اِلَّا هُوَۚ عَالِمُ الْغَيْبِ وَالشَّهَادَةِۚ هُوَ الرَّحْمٰنُ الرَّحِيْمُ", "Huwallāhul-lażī lā ilāha illā huw(a), ‘ālimul-gaibi wasy-syahādah(ti), huwar-raḥmānur-raḥīm(u).", "Dialah اللّه Yang tidak ada tuhan selain Dia. (Dialah) Yang Mengetahui yang gaib dan yang nyata. Dialah Yang Maha Pengasih lagi Maha Penyayang."),
    Ayah(23, 59, "هُوَ اللّٰهُ الَّذِيْ لَآ اِلٰهَ اِلَّا هُوَ ۚ اَلْمَلِكُ الْقُدُّوْسُ السَّلٰمُ الْمُؤْمِنُ الْمُهَيْمِنُ الْعَزِيْزُ الْجَبَّارُ الْمُتَكَبِّرُۗ سُبْحٰنَ اللّٰهِ عَمَّا يُشْرِكُوْنَ", "Huwallāhul-lażī lā ilāha illā huw(a), al-malikul-quddūsus-salāmul-mu'minul-muhaiminul-‘azīzul-jabbārul-mutakabbir(u), subḥānallāhi ‘ammā yusyrikūn(a).", "Dialah اللّه Yang tidak ada tuhan selain Dia. Dia (adalah) Maharaja, Yang Mahasuci, Yang Mahadamai, Yang Maha Mengaruniakan keamanan, Maha Mengawasi, Yang Mahaperkasa, Yang Mahakuasa, dan Yang Memiliki segala keagungan. Mahasuci اللّه dari apa yang mereka persekutukan."),
    Ayah(24, 59, "هُوَ اللّٰهُ الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ لَهُ الْاَسْمَاۤءُ الْحُسْنٰىۗ يُسَبِّحُ لَهٗ مَا فِى السَّمٰوٰتِ وَالْاَرْضِۚ وَهُوَ الْعَزِيْزُ الْحَكِيْمُ ࣖ", "Huwallāhul-khāliqul-bāri'ul-muṣawwiru lahul-asmā'ul-ḥusnā, yusabbiḥu lahū mā fis-samāwāti wal-arḍ(i), wa huwal-‘azīzul-ḥakīm(u).", "Dialah اللّه Yang Maha Pencipta, Yang Mewujudkan dari tiada, dan Yang Membentuk rupa. Dia memiliki nama-nama yang indah. Apa yang di langit dan di bumi senantiasa bertasbih kepada-Nya. Dialah Yang Mahaperkasa lagi Mahabijaksana."),
)

internal fun quranFullAyahs60(): List<Ayah> = listOf(
    Ayah(1, 60, "يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا لَا تَتَّخِذُوْا عَدُوِّيْ وَعَدُوَّكُمْ اَوْلِيَاۤءَ تُلْقُوْنَ اِلَيْهِمْ بِالْمَوَدَّةِ وَقَدْ كَفَرُوْا بِمَا جَاۤءَكُمْ مِّنَ الْحَقِّۚ يُخْرِجُوْنَ الرَّسُوْلَ وَاِيَّاكُمْ اَنْ تُؤْمِنُوْا بِاللّٰهِ رَبِّكُمْۗ اِنْ كُنْتُمْ خَرَجْتُمْ جِهَادًا فِيْ سَبِيْلِيْ وَابْتِغَاۤءَ مَرْضَاتِيْ تُسِرُّوْنَ اِلَيْهِمْ بِالْمَوَدَّةِ وَاَنَا۠ اَعْلَمُ بِمَآ اَخْفَيْتُمْ وَمَآ اَعْلَنْتُمْۗ وَمَنْ يَّفْعَلْهُ مِنْكُمْ فَقَدْ ضَلَّ سَوَاۤءَ السَّبِيْلِ", "Yā ayyuhal-lażīna āmanū lā tattakhiżū ‘aduwwī wa ‘aduwwakum auliyā'a tulqūna ilaihim bil-mawaddati wa qad kafarū bimā jā'akum minal-ḥaqq(i), yukhrijūnar-rasūla wa iyyākum an tu'minū billāhi rabbikum, in kuntum kharajtum jihādan fī sabīlī wabtigā'a marḍātī tusirrūna ilaihim bil-mawaddah(ti), wa ana a‘lamu bimā akhfaitum wa mā a‘lantum, wa may yaf‘alhu minkum faqad ḍalla sawā'as-sabīl(i).", "Wahai orang-orang yang beriman. Janganlah kamu menjadikan musuh-Ku dan musuhmu sebagai teman setia. Kamu sampaikan kepada mereka (hal-hal yang seharusnya dirahasiakan) karena rasa kasih sayang (kamu kepada mereka). Padahal, mereka telah mengingkari kebenaran yang datang kepadamu. Mereka mengusir Rasul dan kamu (dari Makkah) karena kamu beriman kepada اللّه, Tuhanmu. Jika kamu keluar untuk berjihad pada jalan-Ku dan mencari keridaan-Ku, (janganlah kamu berbuat demikian). Kamu memberitahukan secara rahasia (hal-hal yang seharusnya dirahasiakan) kepada mereka karena rasa kasih sayang. Aku lebih tahu tentang apa yang kamu sembunyikan dan apa yang kamu nyatakan. Siapa di antara kamu yang melakukannya sungguh telah tersesat dari jalan yang lurus."),
    Ayah(2, 60, "اِنْ يَّثْقَفُوْكُمْ يَكُوْنُوْا لَكُمْ اَعْدَاۤءً وَّيَبْسُطُوْٓا اِلَيْكُمْ اَيْدِيَهُمْ وَاَلْسِنَتَهُمْ بِالسُّوْۤءِ وَوَدُّوْا لَوْ تَكْفُرُوْنَۗ", "Iy yaṡqafūkum yakūnū lakum a‘dā'aw wa yabsuṭū ilaikum aidiyahum wa alsinatahum bis-sū'i wa waddū lau takfurūn(a).", "Jika (suatu saat) mereka menangkapmu, niscaya mereka bertindak sebagai musuh bagimu. Lalu, mereka melepaskan tangan dan lidahnya kepadamu untuk menyakiti dan mereka ingin agar kamu (kembali) kafir."),
    Ayah(3, 60, "لَنْ تَنْفَعَكُمْ اَرْحَامُكُمْ وَلَآ اَوْلَادُكُمْ ۛيَوْمَ الْقِيٰمَةِ ۛيَفْصِلُ بَيْنَكُمْۗ وَاللّٰهُ بِمَا تَعْمَلُوْنَ بَصِيْرٌ", "Lan tanfa‘akum arḥāmukum wa lā aulādukum yaumal-qiyāmati yafṣilu bainakum, wallāhu bimā ta‘malūna baṣīr(un).", "Kaum kerabatmu dan anak-anakmu tidak akan bermanfaat bagimu pada hari Kiamat. Kelak Dia akan memisahkan antara kamu. اللّه Maha Melihat apa yang kamu kerjakan."),
    Ayah(4, 60, "قَدْ كَانَتْ لَكُمْ اُسْوَةٌ حَسَنَةٌ فِيْٓ اِبْرٰهِيْمَ وَالَّذِيْنَ مَعَهٗۚ اِذْ قَالُوْا لِقَوْمِهِمْ اِنَّا بُرَءٰۤؤُا مِنْكُمْ وَمِمَّا تَعْبُدُوْنَ مِنْ دُوْنِ اللّٰهِ ۖ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ الْعَدَاوَةُ وَالْبَغْضَاۤءُ اَبَدًا حَتّٰى تُؤْمِنُوْا بِاللّٰهِ وَحْدَهٗٓ اِلَّا قَوْلَ اِبْرٰهِيْمَ لِاَبِيْهِ لَاَسْتَغْفِرَنَّ لَكَ وَمَآ اَمْلِكُ لَكَ مِنَ اللّٰهِ مِنْ شَيْءٍۗ رَبَّنَا عَلَيْكَ تَوَكَّلْنَا وَاِلَيْكَ اَنَبْنَا وَاِلَيْكَ الْمَصِيْرُ", "Qad kānat lakum uswatun ḥasanatun fī ibrāhīma wal-lażīna ma‘ah(ū), iż qālū liqaumihim innā bura'ā'u minkum wa mimmā ta‘budūna min dūnillāh(i), kafarnā bikum wa badā bainanā wa bainakumul-‘adāwatu wal-bagḍā'u abadan ḥattā tu'minū billāhi waḥdahū illā qaula ibrāhīma li'abīhi la'astagfiranna laka wa mā amliku laka minallāhi min syai'(in), rabbanā ‘alaika tawakkalnā wa ilaika anabnā wa ilaikal-maṣīr(u).", "Sungguh, benar-benar ada suri teladan yang baik bagimu pada (diri) Ibrahim dan orang-orang yang bersama dengannya ketika mereka berkata kepada kaumnya, “Sesungguhnya kami berlepas diri dari kamu dan dari apa yang kamu sembah selain اللّه. Kami mengingkari (kekufuran)-mu dan telah nyata antara kami dan kamu ada permusuhan dan kebencian untuk selama-lamanya sampai kamu beriman kepada اللّه saja.” Akan tetapi, (janganlah engkau teladani) perkataan Ibrahim kepada ayahnya, “Sungguh, aku akan memohonkan ampunan bagimu, tetapi aku sama sekali tidak dapat menolak (siksaan) اللّه terhadapmu.” (Ibrahim berkata,) “Ya Tuhan kami, hanya kepada Engkau kami bertawakal, hanya kepada Engkau kami bertobat, dan hanya kepada Engkaulah kami kembali."),
    Ayah(5, 60, "رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلَّذِيْنَ كَفَرُوْا وَاغْفِرْ لَنَا رَبَّنَاۚ اِنَّكَ اَنْتَ الْعَزِيْزُ الْحَكِيْمُ", "Rabbanā lā taj‘alnā fitnatal lil-lażīna kafarū wagfir lanā rabbanā, innaka antal-‘azīzul-ḥakīm(u).", "Ya Tuhan kami, janganlah Engkau jadikan kami (sasaran) fitnah bagi orang-orang kafir. Ampunilah kami, ya Tuhan kami. Sesungguhnya Engkau Yang Mahaperkasa lagi Mahabijaksana.”"),
    Ayah(6, 60, "لَقَدْ كَانَ لَكُمْ فِيْهِمْ اُسْوَةٌ حَسَنَةٌ لِّمَنْ كَانَ يَرْجُوا اللّٰهَ وَالْيَوْمَ الْاٰخِرَۗ وَمَنْ يَّتَوَلَّ فَاِنَّ اللّٰهَ هُوَ الْغَنِيُّ الْحَمِيْدُ ࣖ", "Laqad kāna lakum fīhim uswatun ḥasanatul liman kāna yarjullāha wal-yaumal-ākhir(a), wa may yatawalla fa'innallāha huwal-ganiyyul-ḥamīd(u).", "Sungguh pada mereka itu (Ibrahim dan umatnya) benar-benar terdapat suri teladan yang baik bagimu, (yaitu) bagi orang yang mengharap (pahala) اللّه dan (keselamatan pada) hari Kemudian. Siapa yang berpaling, sesungguhnya اللّه, Dialah Yang Mahakaya lagi Maha Terpuji."),
    Ayah(7, 60, "۞ عَسَى اللّٰهُ اَنْ يَّجْعَلَ بَيْنَكُمْ وَبَيْنَ الَّذِيْنَ عَادَيْتُمْ مِّنْهُمْ مَّوَدَّةًۗ وَاللّٰهُ قَدِيْرٌۗ وَاللّٰهُ غَفُوْرٌ رَّحِيْمٌ", "‘Asallāhu ay yaj‘ala bainakum wa bainal-lażīna ‘ādaitum minhum mawaddah(tan), wallāhu qadīr(un), wallāhu gafūrur raḥīm(un).", "Mudah-mudahan اللّه menimbulkan kasih sayang di antara kamu dengan orang-orang yang pernah kamu musuhi di antara mereka. اللّه Mahakuasa dan اللّه Maha Pengampun lagi Maha Penyayang."),
    Ayah(8, 60, "لَا يَنْهٰىكُمُ اللّٰهُ عَنِ الَّذِيْنَ لَمْ يُقَاتِلُوْكُمْ فِى الدِّيْنِ وَلَمْ يُخْرِجُوْكُمْ مِّنْ دِيَارِكُمْ اَنْ تَبَرُّوْهُمْ وَتُقْسِطُوْٓا اِلَيْهِمْۗ اِنَّ اللّٰهَ يُحِبُّ الْمُقْسِطِيْنَ", "Lā yanhākumullāhu ‘anil-lażīna lam yuqātilūkum fid-dīni wa lam yukhrijūkum min diyārikum an tabarrūhum wa tuqsiṭū ilaihim, innallāha yuḥibbul-muqsiṭīn(a).", "اللّه tidak melarang kamu berbuat baik dan berlaku adil terhadap orang-orang yang tidak memerangimu dalam urusan agama dan tidak mengusir kamu dari kampung halamanmu. Sesungguhnya اللّه mencintai orang-orang yang berlaku adil."),
    Ayah(9, 60, "اِنَّمَا يَنْهٰىكُمُ اللّٰهُ عَنِ الَّذِيْنَ قَاتَلُوْكُمْ فِى الدِّيْنِ وَاَخْرَجُوْكُمْ مِّنْ دِيَارِكُمْ وَظَاهَرُوْا عَلٰٓى اِخْرَاجِكُمْ اَنْ تَوَلَّوْهُمْۚ وَمَنْ يَّتَوَلَّهُمْ فَاُولٰۤىِٕكَ هُمُ الظّٰلِمُوْنَ", "Innamā yanhākumullāhu ‘anil-lażīna qātalūkum fid-dīni wa akhrajūkum min diyārikum wa ẓāharū ‘alā ikhrājikum an tawallauhum, wa may yatawallahum fa'ulā'ika humuẓ-ẓālimūn(a).", "Sesungguhnya اللّه hanya melarangmu (berteman akrab) dengan orang-orang yang memerangimu dalam urusan agama, mengusirmu dari kampung halamanmu, dan membantu (orang lain) dalam mengusirmu. Siapa yang menjadikan mereka sebagai teman akrab, mereka itulah orang-orang yang zalim."),
    Ayah(10, 60, "يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْٓا اِذَا جَاۤءَكُمُ الْمُؤْمِنٰتُ مُهٰجِرٰتٍ فَامْتَحِنُوْهُنَّۗ اَللّٰهُ اَعْلَمُ بِاِيْمَانِهِنَّ فَاِنْ عَلِمْتُمُوْهُنَّ مُؤْمِنٰتٍ فَلَا تَرْجِعُوْهُنَّ اِلَى الْكُفَّارِۗ لَا هُنَّ حِلٌّ لَّهُمْ وَلَا هُمْ يَحِلُّوْنَ لَهُنَّۗ وَاٰتُوْهُمْ مَّآ اَنْفَقُوْاۗ وَلَا جُنَاحَ عَلَيْكُمْ اَنْ تَنْكِحُوْهُنَّ اِذَآ اٰتَيْتُمُوْهُنَّ اُجُوْرَهُنَّۗ وَلَا تُمْسِكُوْا بِعِصَمِ الْكَوَافِرِ وَسْـَٔلُوْا مَآ اَنْفَقْتُمْ وَلْيَسْـَٔلُوْا مَآ اَنْفَقُوْاۗ ذٰلِكُمْ حُكْمُ اللّٰهِ ۗيَحْكُمُ بَيْنَكُمْۗ وَاللّٰهُ عَلِيْمٌ حَكِيْمٌ", "Yā ayyuhal-lażīna āmanū iżā jā'akumul-mu'minātu muhājirātin famtaḥinūhunn(a), allāhu a‘lamu bi'īmānihinna fa'in ‘alimtumūhunna mu'minātin falā tarji‘ūhunna ilal-kuffār(i), lā hunna ḥillul lahum wa lā hum yaḥillūna lahunn(a), wa ātūhum mā anfaqū, wa lā junāḥa ‘alaikum an tankiḥūhunna iżā ātaitumūhunna ujūrahunn(a), wa lā tumsikū bi‘iṣamil-kawāfiri was'alū mā anfaqū, żālikum ḥukmullāh(i), yaḥkumu bainakum, wallāhu ‘alīmun ḥakīm(un).", "Wahai orang-orang yang beriman, apabila perempuan-perempuan mukmin datang berhijrah kepadamu, hendaklah kamu uji (keimanan) mereka. اللّه lebih tahu tentang keimanan mereka. Jika kamu telah mengetahui (keadaan) mereka bahwa mereka (benar-benar sebagai) perempuan-perempuan mukmin, janganlah kamu kembalikan mereka kepada orang-orang kafir (suami mereka). Mereka tidak halal bagi orang-orang kafir itu dan orang-orang kafir itu tidak halal pula bagi mereka. Berikanlah kepada (suami) mereka mahar yang telah mereka berikan. Tidak ada dosa bagimu menikahi mereka apabila kamu membayar mahar kepada mereka. Janganlah kamu tetap berpegang pada tali (pernikahan) dengan perempuan-perempuan kafir. Hendaklah kamu meminta kembali (dari orang-orang kafir) mahar yang telah kamu berikan (kepada istri yang kembali kafir). Hendaklah mereka (orang-orang kafir) meminta kembali mahar yang telah mereka bayar (kepada mantan istrinya yang telah beriman). Demikianlah hukum اللّه yang ditetapkan-Nya di antara kamu. اللّه Maha Mengetahui lagi Mahabijaksana."),
    Ayah(11, 60, "وَاِنْ فَاتَكُمْ شَيْءٌ مِّنْ اَزْوَاجِكُمْ اِلَى الْكُفَّارِ فَعَاقَبْتُمْ فَاٰتُوا الَّذِيْنَ ذَهَبَتْ اَزْوَاجُهُمْ مِّثْلَ مَآ اَنْفَقُوْاۗ وَاتَّقُوا اللّٰهَ الَّذِيْٓ اَنْتُمْ بِهٖ مُؤْمِنُوْنَ", "Wa in fātakum syai'um min azwājikum ilal-kuffāri fa‘āqabtum fa'ātul-lażīna żahabat azwājuhum miṡla mā anfaqū, wattaqullāhal-lażī antum bihī mu'minūn(a).", "Jika ada sesuatu (pengembalian mahar) yang belum kamu selesaikan dari istri-istrimu yang lari kepada orang-orang kafir, lalu kamu dapat mengalahkan mereka, berikanlah (dari harta rampasan) kepada orang-orang yang istrinya lari itu sebanyak mahar yang telah mereka berikan. Bertakwalah kepada اللّه yang kepada-Nya kamu beriman."),
    Ayah(12, 60, "يٰٓاَيُّهَا النَّبِيُّ اِذَا جَاۤءَكَ الْمُؤْمِنٰتُ يُبَايِعْنَكَ عَلٰٓى اَنْ لَّا يُشْرِكْنَ بِاللّٰهِ شَيْـًٔا وَّلَا يَسْرِقْنَ وَلَا يَزْنِيْنَ وَلَا يَقْتُلْنَ اَوْلَادَهُنَّ وَلَا يَأْتِيْنَ بِبُهْتَانٍ يَّفْتَرِيْنَهٗ بَيْنَ اَيْدِيْهِنَّ وَاَرْجُلِهِنَّ وَلَا يَعْصِيْنَكَ فِيْ مَعْرُوْفٍ فَبَايِعْهُنَّ وَاسْتَغْفِرْ لَهُنَّ اللّٰهَ ۗاِنَّ اللّٰهَ غَفُوْرٌ رَّحِيْمٌ", "Yā ayyuhan-nabiyyu iżā jā'akal-mu'minātu yubāyi‘naka ‘alā allā yusyrikna billāhi syai'aw wa lā yasriqna wa lā yaznīna wa lā yaqtulna aulādahunna wa lā ya'tīna bibuhtāniy yaftarīnahū baina aidīhinna wa arjulihinna wa lā ya‘ṣīnaka fī ma‘rūfin fabāyi‘hunna wastagfir lahunnallāh(a), innallāha gafūrur raḥīm(un).", "Wahai Nabi, apabila perempuan-perempuan mukmin datang kepadamu untuk mengadakan baiat (janji setia) bahwa mereka tidak akan mempersekutukan sesuatu apa pun dengan اللّه, tidak akan mencuri, tidak akan berzina, tidak akan membunuh anak-anaknya, tidak akan berbuat dusta yang mereka ada-adakan antara tangan dan kaki mereka dan tidak akan mendurhakaimu dalam urusan yang baik, terimalah baiat mereka dan mohonkanlah ampunan untuk mereka kepada اللّه. Sesungguhnya اللّه Maha Pengampun lagi Maha Penyayang."),
    Ayah(13, 60, "يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا لَا تَتَوَلَّوْا قَوْمًا غَضِبَ اللّٰهُ عَلَيْهِمْ قَدْ يَىِٕسُوْا مِنَ الْاٰخِرَةِ كَمَا يَىِٕسَ الْكُفَّارُ مِنْ اَصْحٰبِ الْقُبُوْرِ ࣖ", "Yā ayyuhal-lażīna āmanū lā tatawallau qauman gaḍiballāhu ‘alaihim qad ya'isū minal-ākhirati kamā ya'isal-kuffāru min aṣḥābil-qubūr(i).", "Wahai orang-orang yang beriman, janganlah kamu jadikan kaum yang dimurkai اللّه sebagai teman-teman akrab. Sungguh, mereka telah putus asa terhadap akhirat sebagaimana orang-orang kafir yang telah berada dalam kubur juga berputus asa (dari rahmat اللّه di akhirat)."),
)

internal fun quranFullAyahs61(): List<Ayah> = listOf(
    Ayah(1, 61, "سَبَّحَ لِلّٰهِ مَا فِى السَّمٰوٰتِ وَمَا فِى الْاَرْضِۚ وَهُوَ الْعَزِيْزُ الْحَكِيْمُ", "Sabbaḥa lillāhi mā fis-samāwāti wa mā fil-arḍ(i), wa huwal-‘azīzul-ḥakīm(u).", "Apa yang ada di langit dan apa yang ada di bumi bertasbih kepada اللّه. Dialah Yang Mahaperkasa lagi Mahabijaksana."),
    Ayah(2, 61, "يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا لِمَ تَقُوْلُوْنَ مَا لَا تَفْعَلُوْنَ", "Yā ayyuhal-lażīna āmanū lima taqūlūna mā lā taf‘alūn(a).", "Wahai orang-orang yang beriman, mengapa kamu mengatakan sesuatu yang tidak kamu kerjakan?"),
    Ayah(3, 61, "كَبُرَ مَقْتًا عِنْدَ اللّٰهِ اَنْ تَقُوْلُوْا مَا لَا تَفْعَلُوْنَ", "Kabura maqtan ‘indallāhi an taqūlū mā lā taf‘alūn(a).", "Sangat besarlah kemurkaan di sisi اللّه bahwa kamu mengatakan apa yang tidak kamu kerjakan."),
    Ayah(4, 61, "اِنَّ اللّٰهَ يُحِبُّ الَّذِيْنَ يُقَاتِلُوْنَ فِيْ سَبِيْلِهٖ صَفًّا كَاَنَّهُمْ بُنْيَانٌ مَّرْصُوْصٌ", "Innallāha yuḥibbul-lażīna yuqātilūna fī sabīlihī ṣaffan ka'annahum bun-yānum marṣūṣ(un).", "Sesungguhnya اللّه mencintai orang-orang yang berperang di jalan-Nya dalam satu barisan, seakan-akan mereka suatu bangunan yang tersusun kukuh."),
    Ayah(5, 61, "وَاِذْ قَالَ مُوْسٰى لِقَوْمِهٖ يٰقَوْمِ لِمَ تُؤْذُوْنَنِيْ وَقَدْ تَّعْلَمُوْنَ اَنِّيْ رَسُوْلُ اللّٰهِ اِلَيْكُمْۗ فَلَمَّا زَاغُوْٓا اَزَاغَ اللّٰهُ قُلُوْبَهُمْۗ وَاللّٰهُ لَا يَهْدِى الْقَوْمَ الْفٰسِقِيْنَ", "Wa iż qāla mūsā liqaumihī yā qaumi lima tu'żūnanī wa qad ta‘lamūna annī rasūlullāhi ilaikum, falammā zāgū azāgallāhu qulūbahum, wallāhu lā yahdil-qaumal-fāsiqīn(a).", "(Ingatlah) ketika Musa berkata kepada kaumnya, “Wahai kaumku, mengapa kamu menyakitiku? Padahal, kamu sungguh mengetahui bahwa aku adalah utusan اللّه kepadamu.” Maka, ketika mereka berpaling (dari perintah اللّه), اللّه memalingkan hati mereka (dari kebenaran). اللّه tidak memberi petunjuk kepada kaum yang fasik."),
    Ayah(6, 61, "وَاِذْ قَالَ عِيْسَى ابْنُ مَرْيَمَ يٰبَنِيْٓ اِسْرَاۤءِيْلَ اِنِّيْ رَسُوْلُ اللّٰهِ اِلَيْكُمْ مُّصَدِّقًا لِّمَا بَيْنَ يَدَيَّ مِنَ التَّوْرٰىةِ وَمُبَشِّرًاۢ بِرَسُوْلٍ يَّأْتِيْ مِنْۢ بَعْدِى اسْمُهٗٓ اَحْمَدُۗ فَلَمَّا جَاۤءَهُمْ بِالْبَيِّنٰتِ قَالُوْا هٰذَا سِحْرٌ مُّبِيْنٌ", "Wa iż qāla ‘īsabnu maryama yā banī isrā'īla innī rasūlullāhi ilaikum muṣaddiqal limā baina yadayya minat-taurāti wa mubasysyiram birasūliy ya'tī mim ba‘dismuhū aḥmad(u), falammā jā'ahum bil-bayyināti qālū hāżā siḥrum mubīn(un).", "(Ingatlah) ketika Isa putra Maryam berkata, “Wahai Bani Israil, sesungguhnya aku adalah utusan اللّه kepadamu untuk membenarkan kitab (yang turun) sebelumku, yaitu Taurat, dan memberi kabar gembira tentang seorang utusan اللّه yang akan datang setelahku yang namanya Ahmad (Nabi Muhammad).” Akan tetapi, ketika utusan itu datang kepada mereka dengan membawa bukti-bukti yang nyata, mereka berkata, “Ini adalah sihir yang nyata.”"),
    Ayah(7, 61, "وَمَنْ اَظْلَمُ مِمَّنِ افْتَرٰى عَلَى اللّٰهِ الْكَذِبَ وَهُوَ يُدْعٰىٓ اِلَى الْاِسْلَامِۗ وَاللّٰهُ لَا يَهْدِى الْقَوْمَ الظّٰلِمِيْنَ", "Wa man aẓlamu mimmaniftarā ‘alallāhil-każiba wa huwa yud‘ā ilal-islām(i), wallāhu lā yahdil-qaumaẓ-ẓālimīn(a).", "Siapakah yang lebih zalim daripada orang yang mengada-adakan kebohongan terhadap اللّه, padahal dia diseru kepada (agama) Islam? اللّه tidak memberi petunjuk kepada kaum yang zalim."),
    Ayah(8, 61, "يُرِيْدُوْنَ لِيُطْفِـُٔوْا نُوْرَ اللّٰهِ بِاَفْوَاهِهِمْۗ وَاللّٰهُ مُتِمُّ نُوْرِهٖ وَلَوْ كَرِهَ الْكٰفِرُوْنَ", "Yurīdūna liyuṭfi'ū nūrallāhi bi'afwāhihim, wallāhu mutimmu nūrihī wa lau karihal-kāfirūn(a).", "Mereka hendak memadamkan cahaya (agama) اللّه dengan mulut mereka, sedangkan اللّه tetap menyempurnakan cahaya-Nya walaupun orang-orang kafir tidak menyukai."),
    Ayah(9, 61, "هُوَ الَّذِيْٓ اَرْسَلَ رَسُوْلَهٗ بِالْهُدٰى وَدِيْنِ الْحَقِّ لِيُظْهِرَهٗ عَلَى الدِّيْنِ كُلِّهٖۙ وَلَوْ كَرِهَ الْمُشْرِكُوْنَ ࣖ", "Wa huwal-lażī arsala rasūlahū bil-hudā wa dīnil-ḥaqqi liyuẓhirahū ‘alad-dīni kullih(ī), wa lau karihal-musyrikūn(a).", "Dialah yang mengutus Rasul-Nya dengan (membawa) petunjuk dan agama yang benar agar Dia mengunggulkannya atas semua agama walaupun orang-orang musyrik tidak menyukai."),
    Ayah(10, 61, "يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا هَلْ اَدُلُّكُمْ عَلٰى تِجَارَةٍ تُنْجِيْكُمْ مِّنْ عَذَابٍ اَلِيْمٍ", "Yā ayyuhal-lażīna āmanū hal adullukum ‘alā tijāratin tunjīkum min ‘ażābin alīm(in).", "Wahai orang-orang yang beriman, maukah kamu Aku tunjukkan suatu perdagangan yang (dapat) menyelamatkan kamu dari azab yang pedih?"),
    Ayah(11, 61, "تُؤْمِنُوْنَ بِاللّٰهِ وَرَسُوْلِهٖ وَتُجَاهِدُوْنَ فِيْ سَبِيْلِ اللّٰهِ بِاَمْوَالِكُمْ وَاَنْفُسِكُمْۗ ذٰلِكُمْ خَيْرٌ لَّكُمْ اِنْ كُنْتُمْ تَعْلَمُوْنَۙ", "Tu'minūna billāhi wa rasūlihī wa tujāhidūna fī sabīlillāhi bi'amwālikum wa anfusikum, żālikum khairul lakum in kuntum ta‘lamūn(a).", "(Caranya) kamu beriman kepada اللّه dan Rasul-Nya dan berjihad di jalan اللّه dengan harta dan jiwamu. Yang demikian itu lebih baik bagimu jika kamu mengetahui."),
    Ayah(12, 61, "يَغْفِرْ لَكُمْ ذُنُوْبَكُمْ وَيُدْخِلْكُمْ جَنّٰتٍ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ وَمَسٰكِنَ طَيِّبَةً فِيْ جَنّٰتِ عَدْنٍۗ ذٰلِكَ الْفَوْزُ الْعَظِيْمُۙ", "Yagfir lakum żunūbakum wa yudkhilkum jannātin tajrī min taḥtihal-anhāru wa masākina ṭayyibatan fī jannāti ‘adn(in), żālikal-fauzul-‘aẓīm(u).", "(Jika kamu beriman dan berjihad,) niscaya اللّه mengampuni dosa-dosamu dan memasukkanmu ke dalam surga yang mengalir di bawahnya sungai-sungai dan ke tempat-tempat tinggal yang baik di dalam surga ‘Adn. Itulah kemenangan yang agung."),
    Ayah(13, 61, "وَاُخْرٰى تُحِبُّوْنَهَاۗ نَصْرٌ مِّنَ اللّٰهِ وَفَتْحٌ قَرِيْبٌۗ وَبَشِّرِ الْمُؤْمِنِيْنَ", "Wa ukhrā tuḥibbūnahā, naṣrum minallāhi wa fatḥun qarīb(un), wa basysyiril-mu'minīn(a).", "(Ada balasan) lain yang kamu sukai, (yaitu) pertolongan dari اللّه dan kemenangan yang dekat (waktunya). Sampaikanlah berita gembira kepada orang-orang mukmin."),
    Ayah(14, 61, "يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا كُوْنُوْٓا اَنْصَارَ اللّٰهِ كَمَا قَالَ عِيْسَى ابْنُ مَرْيَمَ لِلْحَوَارِيّٖنَ مَنْ اَنْصَارِيْٓ اِلَى اللّٰهِ ۗقَالَ الْحَوَارِيُّوْنَ نَحْنُ اَنْصَارُ اللّٰهِ فَاٰمَنَتْ طَّاۤىِٕفَةٌ مِّنْۢ بَنِيْٓ اِسْرَاۤءِيْلَ وَكَفَرَتْ طَّاۤىِٕفَةٌ ۚفَاَيَّدْنَا الَّذِيْنَ اٰمَنُوْا عَلٰى عَدُوِّهِمْ فَاَصْبَحُوْا ظٰهِرِيْنَ ࣖ", "Yā ayyuhal-lażīna āmanū kūnū anṣārallāhi kamā qāla ‘īsabnu maryama lil-ḥawāriyyīna man anṣārī ilallāh(i), qālal-ḥawāriyyūna naḥnu anṣārullāhi fa'āmanaṭ-ṭā'ifatum mim banī isrā'īla wa kafaraṭ-ṭā'ifah(tun), fa'ayyadnal-lażīna āmanū ‘alā ‘aduwwihim fa'aṣbaḥū ẓāhirīn(a).", "Wahai orang-orang yang beriman, jadilah penolong-penolong (agama) اللّه sebagaimana Isa putra Maryam berkata kepada pengikut-pengikutnya yang setia, “Siapakah para penolongku menuju kepada (pertolongan) اللّه?” Para pengikutnya yang setia itu berkata, “Kamilah penolong-penolong (agama) اللّه.” Maka, segolongan dari Bani Israil beriman dan segolongan (yang lain) kufur. Lalu, Kami menguatkan orang-orang yang beriman menghadapi musuh-musuh mereka sehingga menjadi orang-orang yang menang."),
)

internal fun quranFullAyahs62(): List<Ayah> = listOf(
    Ayah(1, 62, "يُسَبِّحُ لِلّٰهِ مَا فِى السَّمٰوٰتِ وَمَا فِى الْاَرْضِ الْمَلِكِ الْقُدُّوْسِ الْعَزِيْزِ الْحَكِيْمِ", "Yusabbiḥu lillāhi mā fis-samāwāti wa mā fil-arḍil-malikil-quddūsil-‘azīzil-ḥakīm(i).", "Apa yang ada di langit dan apa yang ada di bumi senantiasa bertasbih kepada اللّه Yang Maharaja, Mahasuci, Mahaperkasa, lagi Mahabijaksana."),
    Ayah(2, 62, "هُوَ الَّذِيْ بَعَثَ فِى الْاُمِّيّٖنَ رَسُوْلًا مِّنْهُمْ يَتْلُوْا عَلَيْهِمْ اٰيٰتِهٖ وَيُزَكِّيْهِمْ وَيُعَلِّمُهُمُ الْكِتٰبَ وَالْحِكْمَةَ وَاِنْ كَانُوْا مِنْ قَبْلُ لَفِيْ ضَلٰلٍ مُّبِيْنٍۙ", "Huwal-lażī ba‘aṡa fil-ummiyyīna rasūlam minhum yatlū ‘alaihim āyātihī wa yuzakkīhim wa yu‘allimuhumul-kitāba wal-ḥikmata wa in kānū min qablu lafī ḍalālim mubīn(in).", "Dialah yang mengutus seorang Rasul (Nabi Muhammad) kepada kaum yang buta huruf dari (kalangan) mereka sendiri, yang membacakan kepada mereka ayat-ayat-Nya, menyucikan (jiwa) mereka, serta mengajarkan kepada mereka Kitab (Al-Qur’an) dan Hikmah (sunah), meskipun sebelumnya mereka benar-benar dalam kesesatan yang nyata."),
    Ayah(3, 62, "وَّاٰخَرِيْنَ مِنْهُمْ لَمَّا يَلْحَقُوْا بِهِمْۗ وَهُوَ الْعَزِيْزُ الْحَكِيْمُۙ", "Wa ākharīna minhum lammā yalḥaqū bihim, wa huwal-‘azīzul-ḥakīm(u).", "(اللّه juga mengutus Nabi Muhammad) kepada (kaum) selain mereka yang belum (datang) menyusul mereka. Dialah Yang Mahaperkasa lagi Mahabijaksana."),
    Ayah(4, 62, "ذٰلِكَ فَضْلُ اللّٰهِ يُؤْتِيْهِ مَنْ يَّشَاۤءُۗ وَاللّٰهُ ذُو الْفَضْلِ الْعَظِيْمِ", "Żālika faḍlullāhi yu'tīhi may yasyā'(u), wallāhu żul-faḍlil-‘aẓīm(i).", "Itulah karunia اللّه yang dianugerahkan kepada siapa yang Dia kehendaki. اللّه memiliki karunia yang besar."),
    Ayah(5, 62, "مَثَلُ الَّذِيْنَ حُمِّلُوا التَّوْرٰىةَ ثُمَّ لَمْ يَحْمِلُوْهَا كَمَثَلِ الْحِمَارِ يَحْمِلُ اَسْفَارًاۗ بِئْسَ مَثَلُ الْقَوْمِ الَّذِيْنَ كَذَّبُوْا بِاٰيٰتِ اللّٰهِ ۗوَاللّٰهُ لَا يَهْدِى الْقَوْمَ الظّٰلِمِيْنَ", "Maṡalul-lażīna ḥummilut-taurāta ṡumma lam yaḥmilūhā kamaṡalil-ḥimāri yaḥmilu asfārā(n), bi'sa maṡalul-qaumil-lażīna każżabū bi'āyātillāh(i), wallāhu lā yahdil-qaumaẓ-ẓālimīn(a).", "Perumpamaan orang-orang yang dibebani tugas mengamalkan Taurat, kemudian tidak mengamalkannya, adalah seperti keledai yang membawa kitab-kitab (tebal tanpa mengerti kandungannya). Sangat buruk perumpamaan kaum yang mendustakan ayat-ayat اللّه. اللّه tidak memberi petunjuk kepada kaum yang zalim."),
    Ayah(6, 62, "قُلْ يٰٓاَيُّهَا الَّذِيْنَ هَادُوْٓا اِنْ زَعَمْتُمْ اَنَّكُمْ اَوْلِيَاۤءُ لِلّٰهِ مِنْ دُوْنِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ اِنْ كُنْتُمْ صٰدِقِيْنَ", "Qul yā ayyuhal-lażīna hādū in za‘amtum annakum auliyā'u lillāhi min dūnin-nāsi fa tamannawul-mauta in kuntum ṣādiqīn(a).", "Katakanlah (Nabi Muhammad), “Wahai orang-orang Yahudi, jika kamu mengira bahwa kamulah kekasih اللّه (dan) bukan orang lain, harapkanlah kematianmu, jika kamu orang-orang benar.”"),
    Ayah(7, 62, "وَلَا يَتَمَنَّوْنَهٗٓ اَبَدًاۢ بِمَا قَدَّمَتْ اَيْدِيْهِمْۗ وَاللّٰهُ عَلِيْمٌۢ بِالظّٰلِمِيْنَ", "Wa lā yatamannaunahū abadam bimā qaddamat aidīhim, wallāhu ‘alīmum biẓ-ẓālimīn(a).", "Mereka tidak akan mengharapkan kematian itu selamanya disebabkan apa (keburukan) yang telah mereka perbuat dengan tangan mereka sendiri. اللّه Maha Mengetahui orang-orang zalim."),
    Ayah(8, 62, "قُلْ اِنَّ الْمَوْتَ الَّذِيْ تَفِرُّوْنَ مِنْهُ فَاِنَّهٗ مُلٰقِيْكُمْ ثُمَّ تُرَدُّوْنَ اِلٰى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُوْنَ ࣖ", "Qul innal-mautal-lażī tafirrūna minhu fa innahū mulāqīkum ṡumma turaddūna ilā ‘ālimil-gaibi wasy-syahādati fa yunabbi'ukum bimā kuntum ta‘malūn(a).", "Katakanlah, “Sesungguhnya kematian yang kamu lari darinya pasti akan menemuimu. Kamu kemudian akan dikembalikan kepada Yang Maha Mengetahui yang gaib dan yang nyata, lalu Dia beritakan kepadamu apa yang selama ini kamu kerjakan.”"),
    Ayah(9, 62, "يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْٓا اِذَا نُوْدِيَ لِلصَّلٰوةِ مِنْ يَّوْمِ الْجُمُعَةِ فَاسْعَوْا اِلٰى ذِكْرِ اللّٰهِ وَذَرُوا الْبَيْعَۗ ذٰلِكُمْ خَيْرٌ لَّكُمْ اِنْ كُنْتُمْ تَعْلَمُوْنَ", "Yā ayyuhal-lażīna āmanū iżā nūdiya liṣ-ṣalāti miy yaumil-jumu‘ati fas‘au ilā żikrillāhi wa żarul-bai‘(a), żālikum khairul lakum in kuntum ta‘lamūn(a).", "Wahai orang-orang yang beriman, apabila (seruan) untuk melaksanakan salat pada hari Jumat telah dikumandangkan, segeralah mengingat اللّه dan tinggalkanlah jual beli. Yang demikian itu lebih baik bagimu jika kamu mengetahui."),
    Ayah(10, 62, "فَاِذَا قُضِيَتِ الصَّلٰوةُ فَانْتَشِرُوْا فِى الْاَرْضِ وَابْتَغُوْا مِنْ فَضْلِ اللّٰهِ وَاذْكُرُوا اللّٰهَ كَثِيْرًا لَّعَلَّكُمْ تُفْلِحُوْنَ", "Fa iżā quḍiyatiṣ-ṣalātu fantasyirū fil-arḍi wabtagū min faḍlillāhi ważkurullāha kaṡīral la‘allakum tufliḥūn(a).", "Apabila salat (Jumat) telah dilaksanakan, bertebaranlah kamu di bumi, carilah karunia اللّه, dan ingatlah اللّه sebanyak-banyaknya agar kamu beruntung."),
    Ayah(11, 62, "وَاِذَا رَاَوْا تِجَارَةً اَوْ لَهْوًا ۨانْفَضُّوْٓا اِلَيْهَا وَتَرَكُوْكَ قَاۤىِٕمًاۗ قُلْ مَا عِنْدَ اللّٰهِ خَيْرٌ مِّنَ اللَّهْوِ وَمِنَ التِّجَارَةِۗ وَاللّٰهُ خَيْرُ الرّٰزِقِيْنَ ࣖ", "Wa iżā ra'au tijāratan au lahwaninfaḍḍū ilaihā wa tarakūka qā'imā(n), qul mā ‘indallāhi khairum minal-lahwi wa minat-tijārah(ti), wallāhu khairur-rāziqīn(a).", "Apabila (sebagian) mereka melihat perdagangan atau permainan, mereka segera berpencar (menuju) padanya dan meninggalkan engkau (Nabi Muhammad) yang sedang berdiri (berkhotbah). Katakanlah, “Apa yang ada di sisi اللّه lebih baik daripada permainan dan perdagangan.” اللّه pemberi rezeki yang terbaik."),
)

internal fun quranFullAyahs63(): List<Ayah> = listOf(
    Ayah(1, 63, "اِذَا جَاۤءَكَ الْمُنٰفِقُوْنَ قَالُوْا نَشْهَدُ اِنَّكَ لَرَسُوْلُ اللّٰهِ ۘوَاللّٰهُ يَعْلَمُ اِنَّكَ لَرَسُوْلُهٗ ۗوَاللّٰهُ يَشْهَدُ اِنَّ الْمُنٰفِقِيْنَ لَكٰذِبُوْنَۚ", "Iżā jā'akal-munāfiqūna qālū nasyhadu innaka larasūlullāh(i), wallāhu ya‘lamu innaka larasūluh(ū), wallāhu yasyhadu innal-munāfiqīna lakāżibūn(a).", "Apabila orang-orang munafik datang kepadamu (Nabi Muhammad), mereka berkata, “Kami bersaksi bahwa engkau adalah benar-benar utusan اللّه.” اللّه mengetahui bahwa engkau benar-benar utusan-Nya. اللّه pun bersaksi bahwa orang-orang munafik itu benar-benar para pendusta."),
    Ayah(2, 63, "اِتَّخَذُوْٓا اَيْمَانَهُمْ جُنَّةً فَصَدُّوْا عَنْ سَبِيْلِ اللّٰهِ ۗاِنَّهُمْ سَاۤءَ مَا كَانُوْا يَعْمَلُوْنَ", "Ittakhażū aimānahum junnatan faṣaddū ‘an sabīlillāh(i), innahum sā'a mā kānū ya‘malūn(a).", "Mereka menjadikan sumpah-sumpah mereka sebagai perisai lalu mereka menghalang-halangi (orang lain) dari jalan اللّه. Sesungguhnya apa yang selalu mereka kerjakan itu sangatlah buruk."),
    Ayah(3, 63, "ذٰلِكَ بِاَنَّهُمْ اٰمَنُوْا ثُمَّ كَفَرُوْا فَطُبِعَ عَلٰى قُلُوْبِهِمْ فَهُمْ لَا يَفْقَهُوْنَ", "Żālika bi'annahum āmanū ṡumma kafarū faṭubi‘a ‘alā qulūbihim fahum lā yafqahūn(a).", "Yang demikian itu karena sesungguhnya mereka telah beriman, kemudian kufur. Maka, hati mereka dikunci sehingga tidak dapat mengerti."),
    Ayah(4, 63, "۞ وَاِذَا رَاَيْتَهُمْ تُعْجِبُكَ اَجْسَامُهُمْۗ وَاِنْ يَّقُوْلُوْا تَسْمَعْ لِقَوْلِهِمْۗ كَاَنَّهُمْ خُشُبٌ مُّسَنَّدَةٌ ۗيَحْسَبُوْنَ كُلَّ صَيْحَةٍ عَلَيْهِمْۗ هُمُ الْعَدُوُّ فَاحْذَرْهُمْۗ قَاتَلَهُمُ اللّٰهُ ۖاَنّٰى يُؤْفَكُوْنَ", "Wa iżā ra'aitahum tu‘jibuka ajsāmuhum, wa iy yaqūlū tasma‘ liqaulihim, ka'annahum khusyubum musannadah(tun), yaḥsabūna kulla ṣaiḥatin ‘alaihim, humul-‘aduwwu faḥżarhum, qātalahumullāh(u), annā yu'fakūn(a).", "Apabila engkau melihat mereka, tubuhnya mengagumkanmu. Jika mereka bertutur kata, engkau mendengarkan tutur katanya (dengan saksama karena kefasihannya). Mereka bagaikan (seonggok) kayu yang tersandar. Mereka mengira bahwa setiap teriakan (kutukan) ditujukan kepada mereka. Mereka itulah musuh (yang sebenarnya). Maka, waspadalah terhadap mereka. Semoga اللّه membinasakan mereka. Bagaimanakah mereka dapat dipalingkan (dari kebenaran)?"),
    Ayah(5, 63, "وَاِذَا قِيْلَ لَهُمْ تَعَالَوْا يَسْتَغْفِرْ لَكُمْ رَسُوْلُ اللّٰهِ لَوَّوْا رُءُوْسَهُمْ وَرَاَيْتَهُمْ يَصُدُّوْنَ وَهُمْ مُّسْتَكْبِرُوْنَ", "Wa iżā qīla lahum ta‘ālau yastagfir lakum rasūlullāhi lawwau ru'ūsahum wa ra'aitahum yaṣuddūna wa hum mustakbirūn(a).", "Apabila dikatakan kepada mereka, “Marilah (beriman) agar Rasulullah memohonkan ampunan bagimu,” mereka membuang muka dan engkau melihat mereka menolak (ajakan itu) sambil menyombongkan diri."),
    Ayah(6, 63, "سَوَاۤءٌ عَلَيْهِمْ اَسْتَغْفَرْتَ لَهُمْ اَمْ لَمْ تَسْتَغْفِرْ لَهُمْۗ لَنْ يَّغْفِرَ اللّٰهُ لَهُمْۗ اِنَّ اللّٰهَ لَا يَهْدِى الْقَوْمَ الْفٰسِقِيْنَ", "Sawā'un ‘alaihim astagfarta lahum am lam tastagfir lahum, lay yagfirallāhu lahum, innallāha lā yahdil-qaumal-fāsiqīn(a).", "Sama saja bagi mereka apakah engkau (Nabi Muhammad) memohonkan ampunan untuk mereka atau tidak, اللّه tidak akan mengampuni mereka. Sesungguhnya اللّه tidak akan memberi petunjuk kepada kaum fasik."),
    Ayah(7, 63, "هُمُ الَّذِيْنَ يَقُوْلُوْنَ لَا تُنْفِقُوْا عَلٰى مَنْ عِنْدَ رَسُوْلِ اللّٰهِ حَتّٰى يَنْفَضُّوْاۗ وَلِلّٰهِ خَزَاۤىِٕنُ السَّمٰوٰتِ وَالْاَرْضِۙ وَلٰكِنَّ الْمُنٰفِقِيْنَ لَا يَفْقَهُوْنَ", "Humul-lażīna yaqūlūna lā tunfiqū ‘alā man ‘inda rasūlillāhi ḥattā yanfaḍḍū, wa lillāhi khazā'inus-samāwāti wal-arḍ(i), wa lākinnal-munāfiqīna lā yafqahūn(a).", "Merekalah orang-orang yang berkata (kepada kaum Ansar), “Janganlah bersedekah kepada orang-orang (Muhajirin) yang ada di sisi Rasulullah sampai mereka bubar (meninggalkan Rasulullah),” padahal milik Allahlah perbendaharaan langit dan bumi. Akan tetapi, orang-orang munafik itu tidak mengerti."),
    Ayah(8, 63, "يَقُوْلُوْنَ لَىِٕنْ رَّجَعْنَآ اِلَى الْمَدِيْنَةِ لَيُخْرِجَنَّ الْاَعَزُّ مِنْهَا الْاَذَلَّ ۗوَلِلّٰهِ الْعِزَّةُ وَلِرَسُوْلِهٖ وَلِلْمُؤْمِنِيْنَ وَلٰكِنَّ الْمُنٰفِقِيْنَ لَا يَعْلَمُوْنَ ࣖ", "Yaqūlūna la'ir raja‘nā ilal-madīnati layukhrijannal-a‘azzu minhal-ażall(a), wa lillāhil-‘izzatu wa lirasūlihī wa lil-mu'minīna wa lākinnal-munāfiqīna lā ya‘lamūn(a).", "Mereka berkata, “Sungguh, jika kita kembali ke Madinah (dari perang Bani Mustaliq), pastilah orang yang kuat akan mengusir orang-orang yang lemah dari sana,” padahal kekuatan itu hanyalah milik اللّه, Rasul-Nya, dan orang-orang mukmin. Akan tetapi, orang-orang munafik itu tidak mengetahui."),
    Ayah(9, 63, "يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا لَا تُلْهِكُمْ اَمْوَالُكُمْ وَلَآ اَوْلَادُكُمْ عَنْ ذِكْرِ اللّٰهِ ۚوَمَنْ يَّفْعَلْ ذٰلِكَ فَاُولٰۤىِٕكَ هُمُ الْخٰسِرُوْنَ", "Yā ayyuhal-lażīna āmanū lā tulhikum amwālukum wa lā aulādukum ‘an żikrillāh(i), wa may yaf‘al żālika fa ulā'ika humul-khāsirūn(a).", "Wahai orang-orang yang beriman, janganlah harta bendamu dan anak-anakmu membuatmu lalai dari mengingat اللّه. Siapa yang berbuat demikian, mereka itulah orang-orang yang merugi."),
    Ayah(10, 63, "وَاَنْفِقُوْا مِنْ مَّا رَزَقْنٰكُمْ مِّنْ قَبْلِ اَنْ يَّأْتِيَ اَحَدَكُمُ الْمَوْتُ فَيَقُوْلَ رَبِّ لَوْلَآ اَخَّرْتَنِيْٓ اِلٰٓى اَجَلٍ قَرِيْبٍۚ فَاَصَّدَّقَ وَاَكُنْ مِّنَ الصّٰلِحِيْنَ", "Wa anfiqū mimmā razaqnākum min qabli ay ya'tiya aḥadakumul-mautu fa yaqūla rabbi lau lā akhkhartanī ilā ajalin qarīb(in), fa aṣṣaddaqa wa akum minaṣ-ṣāliḥīn(a).", "Infakkanlah sebagian dari apa yang telah Kami anugerahkan kepadamu sebelum kematian datang kepada salah seorang di antaramu. Dia lalu berkata (sambil menyesal), “Ya Tuhanku, sekiranya Engkau berkenan menunda (kematian)-ku sedikit waktu lagi, aku akan dapat bersedekah dan aku akan termasuk orang-orang saleh.”"),
    Ayah(11, 63, "وَلَنْ يُّؤَخِّرَ اللّٰهُ نَفْسًا اِذَا جَاۤءَ اَجَلُهَاۗ وَاللّٰهُ خَبِيْرٌۢ بِمَا تَعْمَلُوْنَ ࣖ", "Wa lay yu'akhkhirallāhu nafsan iżā jā'a ajaluhā, wallāhu khabīrum bimā ta‘malūn(a).", "اللّه tidak akan menunda (kematian) seseorang apabila waktu kematiannya telah datang. اللّه Mahateliti terhadap apa yang kamu kerjakan."),
)

internal fun quranFullAyahs64(): List<Ayah> = listOf(
    Ayah(1, 64, "يُسَبِّحُ لِلّٰهِ مَا فِى السَّمٰوٰتِ وَمَا فِى الْاَرْضِۗ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُۖ وَهُوَ عَلٰى كُلِّ شَيْءٍ قَدِيْرٌ", "Yusabbiḥu lillāhi mā fis-samāwāti wa mā fil-arḍ(i), lahul-mulku wa lahul-ḥamdu wa huwa ‘alā kulli syai'in qadīr(un).", "Apa yang ada di langit dan apa yang ada di bumi senantiasa bertasbih kepada اللّه. Milik-Nyalah segala kerajaan dan segala pujian, dan Dia Mahakuasa atas segala sesuatu."),
    Ayah(2, 64, "هُوَ الَّذِيْ خَلَقَكُمْ فَمِنْكُمْ كَافِرٌ وَّمِنْكُمْ مُّؤْمِنٌۗ وَاللّٰهُ بِمَا تَعْمَلُوْنَ بَصِيْرٌ", "Huwal-lażī khalaqakum fa minkum kāfiruw wa minkum mu'min(un), wallāhu bimā ta‘malūna baṣīr(un).", "Dialah yang menciptakan kamu, lalu di antara kamu ada yang kafir dan ada yang mukmin. اللّه Maha Melihat apa yang kamu kerjakan."),
    Ayah(3, 64, "خَلَقَ السَّمٰوٰتِ وَالْاَرْضَ بِالْحَقِّ وَصَوَّرَكُمْ فَاَحْسَنَ صُوَرَكُمْۚ وَاِلَيْهِ الْمَصِيْرُ", "Khalaqas-samāwāti wal-arḍa bil-ḥaqqi wa ṣawwarakum fa'aḥsana ṣuwarakum, wa ilaihil-maṣīr(u).", "Dia menciptakan langit dan bumi dengan benar, Dia membentuk kamu lalu memperindah bentukmu, dan kepada-Nyalah kembali(-mu)."),
    Ayah(4, 64, "يَعْلَمُ مَا فِى السَّمٰوٰتِ وَالْاَرْضِ وَيَعْلَمُ مَا تُسِرُّوْنَ وَمَا تُعْلِنُوْنَۗ وَاللّٰهُ عَلِيْمٌ ۢبِذَاتِ الصُّدُوْرِ", "Ya‘lamu mā fis-samāwāti wal-arḍi wa ya‘lamu mā tusirrūna wa mā tu‘linūn(a), wallāhu ‘alīmum biżātiṣ-ṣudūr(i).", "Dia mengetahui apa yang di langit dan di bumi. Dia juga mengetahui apa yang kamu rahasiakan dan apa yang kamu tampakkan. اللّه Maha Mengetahui segala isi hati."),
    Ayah(5, 64, "اَلَمْ يَأْتِكُمْ نَبَؤُا الَّذِيْنَ كَفَرُوْا مِنْ قَبْلُ ۖفَذَاقُوْا وَبَالَ اَمْرِهِمْ وَلَهُمْ عَذَابٌ اَلِيْمٌ", "Alam ya'tikum naba'ul-lażīna kafarū min qabl(u), fa żāqū wabāla amrihim wa lahum ‘ażābun alīm(un).", "Apakah belum sampai kepadamu (orang-orang kafir) berita (tentang) orang-orang yang kufur dahulu? Mereka telah merasakan akibat buruk dari perbuatannya dan bagi mereka azab yang sangat pedih."),
    Ayah(6, 64, "ذٰلِكَ بِاَنَّهٗ كَانَتْ تَّأْتِيْهِمْ رُسُلُهُمْ بِالْبَيِّنٰتِ فَقَالُوْٓا اَبَشَرٌ يَّهْدُوْنَنَاۖ فَكَفَرُوْا وَتَوَلَّوْا وَّاسْتَغْنَى اللّٰهُ ۗوَاللّٰهُ غَنِيٌّ حَمِيْدٌ", "Żālika bi'annahū kānat ta'tīhim rusuluhum bil-bayyināti fa qālū abasyaruy yahdūnanā, fa kafarū wa tawallau wastagnallāh(u), wallāhu ganiyyun ḥamīd(un).", "(Hukuman) yang demikian itu (terjadi) karena sesungguhnya telah datang kepada mereka rasul-rasul (yang membawa) keterangan-keterangan lalu mereka berkata, “Apakah (pantas jenis) manusia yang memberi petunjuk kepada kami?” Lalu mereka ingkar dan berpaling; padahal اللّه tidak memerlukan (mereka). اللّه Mahakaya lagi Maha Terpuji."),
    Ayah(7, 64, "زَعَمَ الَّذِيْنَ كَفَرُوْٓا اَنْ لَّنْ يُّبْعَثُوْاۗ قُلْ بَلٰى وَرَبِّيْ لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْۗ وَذٰلِكَ عَلَى اللّٰهِ يَسِيْرٌ", "Za‘amal-lażīna kafarū allay yub‘aṡū, qul balā wa rabbī latub‘aṡunna ṡumma latunabba'unna bimā ‘amiltum, wa żālika ‘alallāhi yasīr(un).", "Orang-orang yang kufur mengira bahwa sesungguhnya mereka tidak akan dibangkitkan. Katakanlah (Nabi Muhammad), “Tidak demikian. Demi Tuhanku, kamu pasti akan dibangkitkan, kemudian pasti akan diberitakan apa yang telah kamu kerjakan.” Yang demikian itu mudah bagi اللّه."),
    Ayah(8, 64, "فَاٰمِنُوْا بِاللّٰهِ وَرَسُوْلِهٖ وَالنُّوْرِ الَّذِيْٓ اَنْزَلْنَاۗ وَاللّٰهُ بِمَا تَعْمَلُوْنَ خَبِيْرٌ", "Fa āminū billāhi wa rasūlihī wan-nūril-lażī anzalnā, wallāhu bimā ta‘malūna khabīr(un).", "(Jika demikian halnya,) berimanlah kamu kepada اللّه, Rasul-Nya, dan cahaya (Al-Qur’an) yang telah Kami turunkan. اللّه Mahateliti terhadap apa yang kamu kerjakan."),
    Ayah(9, 64, "يَوْمَ يَجْمَعُكُمْ لِيَوْمِ الْجَمْعِ ذٰلِكَ يَوْمُ التَّغَابُنِۗ وَمَنْ يُّؤْمِنْۢ بِاللّٰهِ وَيَعْمَلْ صَالِحًا يُّكَفِّرْ عَنْهُ سَيِّاٰتِهٖ وَيُدْخِلْهُ جَنّٰتٍ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِيْنَ فِيْهَآ اَبَدًاۗ ذٰلِكَ الْفَوْزُ الْعَظِيْمُ", "Yauma yajma‘ukum liyaumil-jam‘i żālika yaumut-tagābun(i), wa may yu'mim billāhi wa ya‘mal ṣāliḥay yukaffir ‘anhu sayyi'ātihī wa yudkhilhu jannātin tajrī min taḥtihal-anhāru khālidīna fīhā abadā(n), żālikal-fauzul-‘aẓīm(u).", "(Ingatlah) hari (ketika) اللّه mengumpulkan kamu pada hari berhimpun (hari Kiamat). Itulah hari pengungkapan kesalahan. Siapa yang beriman kepada اللّه dan mengerjakan kebajikan, niscaya Dia akan menghapus kesalahan-kesalahannya dan memasukkannya ke dalam surga yang mengalir di bawahnya sungai-sungai. Mereka kekal di dalamnya selama-lamanya. Itulah kemenangan yang agung."),
    Ayah(10, 64, "وَالَّذِيْنَ كَفَرُوْا وَكَذَّبُوْا بِاٰيٰتِنَآ اُولٰۤىِٕكَ اَصْحٰبُ النَّارِ خٰلِدِيْنَ فِيْهَاۗ وَبِئْسَ الْمَصِيْرُ ࣖ", "Wal-lażīna kafarū wa każżabū bi'āyātinā ulā'ika aṣḥābun-nāri khālidīna fīhā, wa bi'sal-maṣīr(u).", "Adapun orang-orang yang kufur dan mendustakan ayat-ayat Kami, mereka itulah penghuni neraka. Mereka kekal di dalamnya. Itulah seburuk-buruk tempat kembali."),
    Ayah(11, 64, "مَآ اَصَابَ مِنْ مُّصِيْبَةٍ اِلَّا بِاِذْنِ اللّٰهِ ۗوَمَنْ يُّؤْمِنْۢ بِاللّٰهِ يَهْدِ قَلْبَهٗ ۗوَاللّٰهُ بِكُلِّ شَيْءٍ عَلِيْمٌ", "Mā aṣāba mim muṣībatin illā bi'iżnillāh(i), wa may yu'mim billāhi yahdi qalbah(ū), wallāhu bikulli syai'in ‘alīm(un).", "Tidak ada suatu musibah pun yang menimpa (seseorang), kecuali dengan izin اللّه. Siapa yang beriman kepada اللّه, niscaya Dia akan memberi petunjuk kepada hatinya. اللّه Maha Mengetahui segala sesuatu."),
    Ayah(12, 64, "وَاَطِيْعُوا اللّٰهَ وَاَطِيْعُوا الرَّسُوْلَۚ فَاِنْ تَوَلَّيْتُمْ فَاِنَّمَا عَلٰى رَسُوْلِنَا الْبَلٰغُ الْمُبِيْنُ", "Wa aṭī‘ullāha wa aṭī‘ur-rasūl(a), fa'in tawallaitum fa innamā ‘alā rasūlinal-balāgul-mubīn(u).", "Taatlah kepada اللّه dan taatlah kepada Rasul. Jika kamu berpaling, sesungguhnya kewajiban rasul Kami hanyalah menyampaikan (risalah) dengan terang."),
    Ayah(13, 64, "اَللّٰهُ لَآ اِلٰهَ اِلَّا هُوَۗ وَعَلَى اللّٰهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُوْنَ", "Allāhu lā ilāha illā huw(a), wa ‘alallāhi falyatawakkalil-mu'minūn(a).", "(Dialah) اللّه. Tidak ada tuhan selain Dia. Kepada Allahlah hendaknya orang-orang mukmin itu bertawakal."),
    Ayah(14, 64, "يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْٓا اِنَّ مِنْ اَزْوَاجِكُمْ وَاَوْلَادِكُمْ عَدُوًّا لَّكُمْ فَاحْذَرُوْهُمْۚ وَاِنْ تَعْفُوْا وَتَصْفَحُوْا وَتَغْفِرُوْا فَاِنَّ اللّٰهَ غَفُوْرٌ رَّحِيْمٌ", "Yā ayyuhal-lażīna āmanū inna min azwājikum wa aulādikum ‘aduwwal lakum faḥżarūhum, wa in ta‘fū wa taṣfaḥū wa tagfirū fa innallāha gafūrur raḥīm(un).", "Wahai orang-orang yang beriman, sesungguhnya di antara istri-istrimu dan anak-anakmu ada yang menjadi musuh bagimu. Maka, berhati-hatilah kamu terhadap mereka. Jika kamu memaafkan, menyantuni, dan mengampuni (mereka), sesungguhnya اللّه Maha Pengampun lagi Maha Penyayang."),
    Ayah(15, 64, "اِنَّمَآ اَمْوَالُكُمْ وَاَوْلَادُكُمْ فِتْنَةٌ ۗوَاللّٰهُ عِنْدَهٗٓ اَجْرٌ عَظِيْمٌ", "Innamā amwālukum wa aulādukum fitnah(tun), wallāhu ‘indahū ajrun ‘aẓīm(un).", "Sesungguhnya hartamu dan anak-anakmu hanyalah cobaan (bagimu). Di sisi Allahlah (ada) pahala yang besar."),
    Ayah(16, 64, "فَاتَّقُوا اللّٰهَ مَا اسْتَطَعْتُمْ وَاسْمَعُوْا وَاَطِيْعُوْا وَاَنْفِقُوْا خَيْرًا لِّاَنْفُسِكُمْۗ وَمَنْ يُّوْقَ شُحَّ نَفْسِهٖ فَاُولٰۤىِٕكَ هُمُ الْمُفْلِحُوْنَ", "Fattaqullāha mastaṭa‘tum wasma‘ū wa aṭī‘ū wa anfiqū khairal li'anfusikum, wa may yūqa syuḥḥa nafsihī fa ulā'ika humul-mufliḥūn(a).", "Bertakwalah kamu kepada اللّه sekuat kemampuanmu! Dengarkanlah, taatlah, dan infakkanlah harta yang baik untuk dirimu! Siapa yang dijaga dirinya dari kekikiran, mereka itulah orang-orang yang beruntung."),
    Ayah(17, 64, "اِنْ تُقْرِضُوا اللّٰهَ قَرْضًا حَسَنًا يُّضٰعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْۗ وَاللّٰهُ شَكُوْرٌ حَلِيْمٌۙ", "In tuqriḍullāha qarḍan ḥasanay yuḍā‘ifhu lakum wa yagfir lakum, wallāhu syakūrun ḥalīm(un).", "Jika kamu meminjamkan kepada اللّه pinjaman yang baik, niscaya Dia akan melipatgandakan (balasan) untukmu dan mengampunimu. اللّه Maha Mensyukuri lagi Maha Penyantun."),
    Ayah(18, 64, "عٰلِمُ الْغَيْبِ وَالشَّهَادَةِ الْعَزِيْزُ الْحَكِيْمُ ࣖ", "‘Ālimul-gaibi wasy-syahādatil-‘azīzul-ḥakīm(u).", "Dialah yang mengetahui semua yang gaib dan yang nyata. (Dialah) Yang Mahaperkasa lagi Mahabijaksana."),
)

internal fun quranFullAyahs65(): List<Ayah> = listOf(
    Ayah(1, 65, "يٰٓاَيُّهَا النَّبِيُّ اِذَا طَلَّقْتُمُ النِّسَاۤءَ فَطَلِّقُوْهُنَّ لِعِدَّتِهِنَّ وَاَحْصُوا الْعِدَّةَۚ وَاتَّقُوا اللّٰهَ رَبَّكُمْۚ لَا تُخْرِجُوْهُنَّ مِنْۢ بُيُوْتِهِنَّ وَلَا يَخْرُجْنَ اِلَّآ اَنْ يَّأْتِيْنَ بِفَاحِشَةٍ مُّبَيِّنَةٍۗ وَتِلْكَ حُدُوْدُ اللّٰهِ ۗوَمَنْ يَّتَعَدَّ حُدُوْدَ اللّٰهِ فَقَدْ ظَلَمَ نَفْسَهٗ ۗ لَا تَدْرِيْ لَعَلَّ اللّٰهَ يُحْدِثُ بَعْدَ ذٰلِكَ اَمْرًا", "Yā ayyuhan-nabiyyu iżā ṭallaqtumun-nisā'a fa ṭalliqūhunna li‘iddatihinna wa aḥṣul-‘iddah(ta), wattaqullāha rabbakum, lā tukhrijūhunna mim buyūtihinna wa lā yakhrujna illā ay ya'tīna bifāḥisyatim mubayyinah(tin), wa tilka ḥudūdullāh(i), wa may yata‘adda ḥudūdallāhi faqad ẓalama nafsah(ū), lā tadrī la‘allallāha yuḥdiṡu ba‘da żālika amrā(n).", "Wahai Nabi, apabila kamu menceraikan istri-istrimu, hendaklah kamu ceraikan mereka pada waktu mereka dapat (menghadapi) idahnya (yang wajar), dan hitunglah waktu idah itu, serta bertakwalah kepada اللّه Tuhanmu. Janganlah kamu keluarkan mereka dari rumahnya dan janganlah (diizinkan) keluar kecuali jika mereka mengerjakan perbuatan keji yang jelas. Itulah hukum-hukum اللّه. Siapa melanggar hukum-hukum اللّه, maka sungguh, dia telah berbuat zalim terhadap dirinya sendiri. Kamu tidak mengetahui boleh jadi setelah itu اللّه mengadakan suatu ketentuan yang baru."),
    Ayah(2, 65, "فَاِذَا بَلَغْنَ اَجَلَهُنَّ فَاَمْسِكُوْهُنَّ بِمَعْرُوْفٍ اَوْ فَارِقُوْهُنَّ بِمَعْرُوْفٍ وَّاَشْهِدُوْا ذَوَيْ عَدْلٍ مِّنْكُمْ وَاَقِيْمُوا الشَّهَادَةَ لِلّٰهِ ۗذٰلِكُمْ يُوْعَظُ بِهٖ مَنْ كَانَ يُؤْمِنُ بِاللّٰهِ وَالْيَوْمِ الْاٰخِرِ ەۗ وَمَنْ يَّتَّقِ اللّٰهَ يَجْعَلْ لَّهٗ مَخْرَجًا ۙ", "Fa iżā balagna ajalahunna fa amsikūhunna bima‘rūfin au fāriqūhunna bima‘rūfiw wa asyhidū żawai ‘adlim minkum wa aqīmusy-syahādata lillāh(i), żālikum yū‘aẓu bihī man kāna yu'minu billāhi wal-yaumil-ākhir(i), wa may yattaqillāha yaj‘al lahū makhrajā(n).", "Apabila mereka telah mendekati akhir idahnya, rujuklah dengan mereka secara baik atau lepaskanlah mereka secara baik dan persaksikanlah dengan dua orang saksi yang adil dari kamu dan hendaklah kamu tegakkan kesaksian itu karena اللّه. Yang demikian itu dinasihatkan kepada orang-orang di antara kamu yang beriman kepada اللّه dan hari akhir. Siapa yang bertakwa kepada اللّه, niscaya Dia akan membukakan jalan keluar baginya"),
    Ayah(3, 65, "وَّيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُۗ وَمَنْ يَّتَوَكَّلْ عَلَى اللّٰهِ فَهُوَ حَسْبُهٗ ۗاِنَّ اللّٰهَ بَالِغُ اَمْرِهٖۗ قَدْ جَعَلَ اللّٰهُ لِكُلِّ شَيْءٍ قَدْرًا", "Wa yarzuqhu min ḥaiṡu lā yaḥtasib(u), wa may yatawakkal ‘alallāhi fa huwa ḥasbuh(ū), innallāha bāligu amrih(ī), qad ja‘alallāhu likulli syai'in qadrā(n).", "dan menganugerahkan kepadanya rezeki dari arah yang tidak dia duga. Siapa yang bertawakal kepada اللّه, niscaya اللّه akan mencukupkan (keperluan)-nya. Sesungguhnya Allahlah yang menuntaskan urusan-Nya. Sungguh, اللّه telah membuat ketentuan bagi setiap sesuatu."),
    Ayah(4, 65, "وَالّٰۤـِٔيْ يَىِٕسْنَ مِنَ الْمَحِيْضِ مِنْ نِّسَاۤىِٕكُمْ اِنِ ارْتَبْتُمْ فَعِدَّتُهُنَّ ثَلٰثَةُ اَشْهُرٍۙ وَّالّٰۤـِٔيْ لَمْ يَحِضْنَۗ وَاُولٰتُ الْاَحْمَالِ اَجَلُهُنَّ اَنْ يَّضَعْنَ حَمْلَهُنَّۗ وَمَنْ يَّتَّقِ اللّٰهَ يَجْعَلْ لَّهٗ مِنْ اَمْرِهٖ يُسْرًا", "Wal-lā'ī ya'isna minal-maḥīḍi min nisā'ikum inirtabtum fa ‘iddatuhunna ṡalāṡatu asyhur(in), wal-lā'ī lam yaḥiḍn(a), wa ulātul-aḥmāli ajaluhunna ay yaḍa‘na ḥamlahunn(a), wa may yattaqillāha yaj‘al lahū min amrihī yusrā(n).", "Perempuan-perempuan yang tidak mungkin haid lagi (menopause) di antara istri-istrimu jika kamu ragu-ragu (tentang masa idahnya) maka idahnya adalah tiga bulan. Begitu (pula) perempuan-perempuan yang tidak haid (belum dewasa). Adapun perempuan-perempuan yang hamil, waktu idah mereka adalah sampai mereka melahirkan kandungannya. Siapa yang bertakwa kepada اللّه, niscaya Dia menjadikan kemudahan baginya dalam urusannya."),
    Ayah(5, 65, "ذٰلِكَ اَمْرُ اللّٰهِ اَنْزَلَهٗٓ اِلَيْكُمْۗ وَمَنْ يَّتَّقِ اللّٰهَ يُكَفِّرْ عَنْهُ سَيِّاٰتِهٖ وَيُعْظِمْ لَهٗٓ اَجْرًا", "Żālika amrullāhi anzalahū ilaikum, wa may yattaqillāha yukaffir ‘anhu sayyi'ātihī wa yu‘ẓim lahū ajrā(n).", "(Ketentuan idah) itu merupakan perintah اللّه yang diturunkan-Nya kepada kamu. Siapa yang bertakwa kepada اللّه, niscaya اللّه akan menghapus kesalahan-kesalahannya dan akan memperbesar pahala baginya."),
    Ayah(6, 65, "اَسْكِنُوْهُنَّ مِنْ حَيْثُ سَكَنْتُمْ مِّنْ وُّجْدِكُمْ وَلَا تُضَاۤرُّوْهُنَّ لِتُضَيِّقُوْا عَلَيْهِنَّۗ وَاِنْ كُنَّ اُولٰتِ حَمْلٍ فَاَنْفِقُوْا عَلَيْهِنَّ حَتّٰى يَضَعْنَ حَمْلَهُنَّۚ فَاِنْ اَرْضَعْنَ لَكُمْ فَاٰتُوْهُنَّ اُجُوْرَهُنَّۚ وَأْتَمِرُوْا بَيْنَكُمْ بِمَعْرُوْفٍۚ وَاِنْ تَعَاسَرْتُمْ فَسَتُرْضِعُ لَهٗٓ اُخْرٰىۗ", "Askinūhunna min ḥaiṡu sakantum miw wujdikum wa lā tuḍārrūhunna lituḍayyiqū ‘alaihinn(a), wa in kunna ulāti ḥamlin fa anfiqū ‘alaihinna ḥattā yaḍa‘na ḥamlahunn(a), fa in arḍa‘na lakum fa ātūhunna ujūrahunn(a), wa'tamirū bainakum bima‘rūf(in), wa in ta‘āsartum fasaturḍi‘u lahū ukhrā.", "Tempatkanlah mereka (para istri yang dicerai) di mana kamu bertempat tinggal menurut kemampuanmu dan janganlah kamu menyusahkan mereka untuk menyempitkan (hati) mereka. Jika mereka (para istri yang dicerai) itu sedang hamil, maka berikanlah kepada mereka nafkahnya sampai mereka melahirkan, kemudian jika mereka menyusukan (anak-anak)-mu maka berikanlah imbalannya kepada mereka; dan musyawarahkanlah di antara kamu (segala sesuatu) dengan baik; dan jika kamu sama-sama menemui kesulitan (dalam hal penyusuan), maka perempuan lain boleh menyusukan (anak itu) untuknya."),
    Ayah(7, 65, "لِيُنْفِقْ ذُوْ سَعَةٍ مِّنْ سَعَتِهٖۗ وَمَنْ قُدِرَ عَلَيْهِ رِزْقُهٗ فَلْيُنْفِقْ مِمَّآ اٰتٰىهُ اللّٰهُ ۗ لَا يُكَلِّفُ اللّٰهُ نَفْسًا اِلَّا مَآ اٰتٰىهَاۗ سَيَجْعَلُ اللّٰهُ بَعْدَ عُسْرٍ يُّسْرًا ࣖ", "Liyunfiq żū sa‘atim min sa‘atih(ī), wa man qudira ‘alaihi rizquhū falyunfiq mimmā ātāhullāh(u), lā yukallifullāhu nafsan illā mā ātāhā, sayaj‘alullāhu ba‘da ‘usriy yusrā(n).", "Hendaklah orang yang lapang (rezekinya) memberi nafkah menurut kemampuannya, dan orang yang disempitkan rezekinya, hendaklah memberi nafkah dari apa (harta) yang dianugerahkan اللّه kepadanya. اللّه tidak membebani kepada seseorang melainkan (sesuai) dengan apa yang dianugerahkan اللّه kepadanya. اللّه kelak akan menganugerahkan kelapangan setelah kesempitan."),
    Ayah(8, 65, "وَكَاَيِّنْ مِّنْ قَرْيَةٍ عَتَتْ عَنْ اَمْرِ رَبِّهَا وَرُسُلِهٖ فَحَاسَبْنٰهَا حِسَابًا شَدِيْدًاۙ وَّعَذَّبْنٰهَا عَذَابًا نُّكْرًا", "Wa ka'ayyim min qaryatin ‘atat ‘an amri rabbihā wa rusulihī fa ḥāsabnāhā ḥisāban syadīdā(n), wa ‘ażżabnāhā ‘ażāban nukrā(n).", "Betapa banyak (penduduk) negeri yang mendurhakai perintah Tuhan mereka dan rasul-rasul-Nya, maka Kami buat perhitungan terhadap penduduk negeri itu dengan perhitungan yang ketat, dan Kami azab mereka dengan azab yang mengerikan."),
    Ayah(9, 65, "فَذَاقَتْ وَبَالَ اَمْرِهَا وَكَانَ عَاقِبَةُ اَمْرِهَا خُسْرًا", "Fa żāqat wabāla amrihā wa kāna ‘āqibatu amrihā khusrā(n).", "Maka, mereka telah merasakan akibat buruk dari perbuatannya, dan akibat perbuatan mereka itu adalah kerugian yang besar."),
    Ayah(10, 65, "اَعَدَّ اللّٰهُ لَهُمْ عَذَابًا شَدِيْدًا فَاتَّقُوا اللّٰهَ يٰٓاُولِى الْاَلْبَابِۛ الَّذِيْنَ اٰمَنُوْا ۛ قَدْ اَنْزَلَ اللّٰهُ اِلَيْكُمْ ذِكْرًاۙ", "A‘addallāhu lahum ‘ażāban syadīdan fattaqullāha yā ulil-albāb(i) - allażīna āmanū - qad anzalallāhu ilaikum żikrā(n).", "اللّه telah menyediakan azab yang sangat pedih bagi mereka. Maka, bertakwalah kepada اللّه, wahai ululalbab (orang-orang yang berakal sehat, berhati bersih, dan cerdas,) (yaitu) orang-orang yang beriman. Sungguh, اللّه telah menurunkan peringatan kepadamu"),
    Ayah(11, 65, "رَّسُوْلًا يَّتْلُوْا عَلَيْكُمْ اٰيٰتِ اللّٰهِ مُبَيِّنٰتٍ لِّيُخْرِجَ الَّذِيْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ مِنَ الظُّلُمٰتِ اِلَى النُّوْرِۗ وَمَنْ يُّؤْمِنْۢ بِاللّٰهِ وَيَعْمَلْ صَالِحًا يُّدْخِلْهُ جَنّٰتٍ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِيْنَ فِيْهَآ اَبَدًاۗ قَدْ اَحْسَنَ اللّٰهُ لَهٗ رِزْقًا", "Rasūlay yatlū ‘alaikum āyātillāhi mubayyinātil liyukhrijal-lażīna āmanū wa ‘amiluṣ-ṣāliḥāti minaẓ-ẓulumāti ilan-nūr(i), wa may yu'mim billāhi wa ya‘mal ṣāliḥay yudkhilhu jannātin tajrī min taḥtihal-anhāru khālidīna fīhā abadā(n), qad aḥsanallāhu lahū rizqā(n).", "(berupa) seorang Rasul yang membacakan ayat-ayat اللّه kepadamu yang menerangkan (bermacam-macam hukum) agar dia mengeluarkan orang-orang yang beriman dan mengerjakan kebajikan dari kegelapan kepada cahaya. Siapa yang beriman kepada اللّه dan mengerjakan kebajikan, niscaya akan Dia masukkan ke dalam surga-surga yang mengalir di bawahnya sungai-sungai. Mereka kekal di dalamnya selama-lamanya. Sungguh, اللّه telah menganugerahkan rezeki yang baik kepadanya."),
    Ayah(12, 65, "اَللّٰهُ الَّذِيْ خَلَقَ سَبْعَ سَمٰوٰتٍ وَّمِنَ الْاَرْضِ مِثْلَهُنَّۗ يَتَنَزَّلُ الْاَمْرُ بَيْنَهُنَّ لِتَعْلَمُوْٓا اَنَّ اللّٰهَ عَلٰى كُلِّ شَيْءٍ قَدِيْرٌ ەۙ وَّاَنَّ اللّٰهَ قَدْ اَحَاطَ بِكُلِّ شَيْءٍ عِلْمًا ࣖ", "Allāhul-lażī khalaqa sab‘a samāwātiw wa minal-arḍi miṡlahunn(a), yatanazzalul-amru bainahunna lita‘lamū annallāha ‘alā kulli syai'in qadīr(un), wa annallāha qad aḥāṭa bikulli syai'in ‘ilmā(n).", "Allahlah yang menciptakan tujuh langit dan (menciptakan pula) bumi seperti itu. Perintah-Nya berlaku padanya agar kamu mengetahui bahwa اللّه Mahakuasa atas segala sesuatu dan ilmu اللّه benar-benar meliputi segala sesuatu."),
)

internal fun quranFullAyahs66(): List<Ayah> = listOf(
    Ayah(1, 66, "يٰٓاَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَآ اَحَلَّ اللّٰهُ لَكَۚ تَبْتَغِيْ مَرْضَاتَ اَزْوَاجِكَۗ وَاللّٰهُ غَفُوْرٌ رَّحِيْمٌ", "Yā ayyuhan-nabiyyu lima tuḥarrimu mā aḥallallāhu lak(a), tabtagī marḍāta azwājik(a), wallāhu gafūrur raḥīm(un).", "Wahai Nabi (Muhammad), mengapa engkau mengharamkan apa yang dihalalkan اللّه bagimu? Engkau bermaksud menyenangkan hati istri-istrimu. اللّه Maha Pengampun lagi Maha Penyayang."),
    Ayah(2, 66, "قَدْ فَرَضَ اللّٰهُ لَكُمْ تَحِلَّةَ اَيْمَانِكُمْۚ وَاللّٰهُ مَوْلٰىكُمْۚ وَهُوَ الْعَلِيْمُ الْحَكِيْمُ", "Qad faraḍallāhu lakum taḥillata aimānikum, wallāhu maulākum, wa huwal-‘alīmul-ḥakīm(u).", "Sungguh, اللّه telah mensyariatkan untukmu pembebasan diri dari sumpahmu. اللّه adalah pelindungmu dan Dia Maha Mengetahui lagi Mahabijaksana."),
    Ayah(3, 66, "وَاِذْ اَسَرَّ النَّبِيُّ اِلٰى بَعْضِ اَزْوَاجِهٖ حَدِيْثًاۚ فَلَمَّا نَبَّاَتْ بِهٖ وَاَظْهَرَهُ اللّٰهُ عَلَيْهِ عَرَّفَ بَعْضَهٗ وَاَعْرَضَ عَنْۢ بَعْضٍۚ فَلَمَّا نَبَّاَهَا بِهٖ قَالَتْ مَنْ اَنْۢبَاَكَ هٰذَاۗ قَالَ نَبَّاَنِيَ الْعَلِيْمُ الْخَبِيْرُ", "Wa iż asarran-nabiyyu ilā ba‘ḍi azwājihī ḥadīṡā(n), falammā nabba'at bihī wa aẓharahullāhu ‘alaihi ‘arrafa ba‘ḍahū wa a‘raḍa ‘am baḍ(in), falammā nabba'ahā bihī qālat man amba'aka hāżā, qāla nabba'aniyal-‘alīmul-khabīr(u).", "(Ingatlah) ketika Nabi membicarakan secara rahasia suatu peristiwa kepada salah seorang istrinya (Hafsah). Kemudian, ketika dia menceritakan (peristiwa) itu (kepada Aisyah) dan اللّه memberitahukannya (kejadian ini) kepadanya (Nabi), dia (Nabi) memberitahukan (kepada Hafsah) sebagian dan menyembunyikan sebagian yang lain. Ketika dia (Nabi) memberitahukan (pembicaraan) itu kepadanya (Hafsah), dia bertanya, “Siapa yang telah memberitahumu hal ini?” Nabi menjawab, “Yang memberitahuku adalah اللّه Yang Maha Mengetahui lagi Mahateliti.”"),
    Ayah(4, 66, "اِنْ تَتُوْبَآ اِلَى اللّٰهِ فَقَدْ صَغَتْ قُلُوْبُكُمَاۚ وَاِنْ تَظٰهَرَا عَلَيْهِ فَاِنَّ اللّٰهَ هُوَ مَوْلٰىهُ وَجِبْرِيْلُ وَصَالِحُ الْمُؤْمِنِيْنَۚ وَالْمَلٰۤىِٕكَةُ بَعْدَ ذٰلِكَ ظَهِيْرٌ", "In tatūbā ilallāhi faqad ṣagat qulūbukumā, wa in taẓāharā ‘alaihi fa innallāha huwa maulāhu wa jibrīlu wa ṣāliḥul-mu'minīn(a), wal-malā'ikatu ba‘da żālika ẓahīr(un).", "Jika kamu berdua bertobat kepada اللّه, sungguh hati kamu berdua telah condong (pada kebenaran) dan jika kamu berdua saling membantu menyusahkan dia (Nabi), sesungguhnya Allahlah pelindungnya. Demikian juga Jibril dan orang-orang mukmin yang saleh. Selain itu, malaikat-malaikat (juga ikut) menolong."),
    Ayah(5, 66, "عَسٰى رَبُّهٗٓ اِنْ طَلَّقَكُنَّ اَنْ يُّبْدِلَهٗٓ اَزْوَاجًا خَيْرًا مِّنْكُنَّ مُسْلِمٰتٍ مُّؤْمِنٰتٍ قٰنِتٰتٍ تٰۤىِٕبٰتٍ عٰبِدٰتٍ سٰۤىِٕحٰتٍ ثَيِّبٰتٍ وَّاَبْكَارًا", "‘Asā rabbuhū in ṭallaqakunna ay yubdilahū azwājan khairam minkunna muslimātim mu'minātin qānitātin tā'ibātin ‘ābidātin sā'iḥātin ṡayyibātiw wa abkārā(n).", "Jika dia (Nabi) menceraikan kamu, boleh jadi Tuhannya akan memberi ganti kepadanya istri-istri yang lebih baik daripada kamu, yang berserah diri, yang beriman, yang taat, yang bertobat, yang beribadah, dan yang berpuasa, baik yang janda maupun yang perawan."),
    Ayah(6, 66, "يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا قُوْٓا اَنْفُسَكُمْ وَاَهْلِيْكُمْ نَارًا وَّقُوْدُهَا النَّاسُ وَالْحِجَارَةُ عَلَيْهَا مَلٰۤىِٕكَةٌ غِلَاظٌ شِدَادٌ لَّا يَعْصُوْنَ اللّٰهَ مَآ اَمَرَهُمْ وَيَفْعَلُوْنَ مَا يُؤْمَرُوْنَ", "Yā ayyuhal-lażīna āmanū qū anfusakum wa ahlīkum nāraw waqūduhan-nāsu wal-ḥijāratu ‘alaihā malā'ikatun gilāẓun syidādul lā ya‘ṣūnallāha mā amarahum wa yaf‘alūna mā yu'marūn(a).", "Wahai orang-orang yang beriman, jagalah dirimu dan keluargamu dari api neraka yang bahan bakarnya adalah manusia dan batu. Penjaganya adalah malaikat-malaikat yang kasar dan keras. Mereka tidak durhaka kepada اللّه terhadap apa yang Dia perintahkan kepadanya dan selalu mengerjakan apa yang diperintahkan."),
    Ayah(7, 66, "يٰٓاَيُّهَا الَّذِيْنَ كَفَرُوْا لَا تَعْتَذِرُوا الْيَوْمَۗ اِنَّمَا تُجْزَوْنَ مَا كُنْتُمْ تَعْمَلُوْنَ ࣖ", "Yā ayyuhal-lażīna kafarū lā ta‘tażīrul-yaum(a), innamā tujzauna mā kuntum ta‘malūn(a).", "Wahai orang-orang yang kufur, janganlah kamu mencari-cari alasan pada hari ini. Sesungguhnya kamu hanya diberi balasan (sesuai dengan) apa yang selama ini kamu kerjakan."),
    Ayah(8, 66, "يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا تُوْبُوْٓا اِلَى اللّٰهِ تَوْبَةً نَّصُوْحًاۗ عَسٰى رَبُّكُمْ اَنْ يُّكَفِّرَ عَنْكُمْ سَيِّاٰتِكُمْ وَيُدْخِلَكُمْ جَنّٰتٍ تَجْرِيْ مِنْ تَحْتِهَا الْاَنْهٰرُۙ يَوْمَ لَا يُخْزِى اللّٰهُ النَّبِيَّ وَالَّذِيْنَ اٰمَنُوْا مَعَهٗۚ نُوْرُهُمْ يَسْعٰى بَيْنَ اَيْدِيْهِمْ وَبِاَيْمَانِهِمْ يَقُوْلُوْنَ رَبَّنَآ اَتْمِمْ لَنَا نُوْرَنَا وَاغْفِرْ لَنَاۚ اِنَّكَ عَلٰى كُلِّ شَيْءٍ قَدِيْرٌ", "Yā ayyuhal-lażīna āmanū tūbū ilallāhi taubatan naṣūḥā(n), ‘asā rabbukum ay yukaffira ‘ankum sayyi'ātikum wa yudkhilakum jannātin tajrī min taḥtihal-anhār(u), yauma lā yukhzillāhun-nabiyya wal-lażīna āmanū ma‘ah(ū), nūruhum yas‘ā baina aidīhim wa bi'aimānihim yaqūlūna rabbanā atmim lanā nūranā wagfir lanā, innaka ‘alā kulli syai'in qadīr(un).", "Wahai orang-orang yang beriman, bertobatlah kepada اللّه dengan tobat yang semurni-murninya. Mudah-mudahan Tuhanmu akan menghapus kesalahan-kesalahanmu dan memasukkanmu ke dalam surga yang mengalir di bawahnya sungai-sungai pada hari ketika اللّه tidak menghinakan Nabi dan orang-orang yang beriman bersamanya. Cahaya mereka memancar di hadapan dan di sebelah kanannya. Mereka berkata, “Ya Tuhan kami, sempurnakanlah untuk kami cahaya kami dan ampunilah kami. Sesungguhnya Engkau Mahakuasa atas segala sesuatu.”"),
    Ayah(9, 66, "يٰٓاَيُّهَا النَّبِيُّ جَاهِدِ الْكُفَّارَ وَالْمُنٰفِقِيْنَ وَاغْلُظْ عَلَيْهِمْۗ وَمَأْوٰىهُمْ جَهَنَّمُۗ وَبِئْسَ الْمَصِيْرُ", "Yā ayyuhan-nabiyyu jāhidil-kuffāra wal-munāfiqīna wagluẓ ‘alaihim, wa ma'wāhum jahannam(u), wa bi'sal-maṣīr(u).", "Wahai Nabi, berjihadlah (melawan) orang-orang kafir dan orang-orang munafik dan bersikap keraslah terhadap mereka. Tempat mereka adalah (neraka) Jahanam dan itulah seburuk-buruk tempat kembali."),
    Ayah(10, 66, "ضَرَبَ اللّٰهُ مَثَلًا لِّلَّذِيْنَ كَفَرُوا امْرَاَتَ نُوْحٍ وَّامْرَاَتَ لُوْطٍۗ كَانَتَا تَحْتَ عَبْدَيْنِ مِنْ عِبَادِنَا صَالِحَيْنِ فَخَانَتٰهُمَا فَلَمْ يُغْنِيَا عَنْهُمَا مِنَ اللّٰهِ شَيْـًٔا وَّقِيْلَ ادْخُلَا النَّارَ مَعَ الدّٰخِلِيْنَ", "Ḍaraballāhu maṡalal lil-lażīna kafarumra'ata nūḥiw wamra'ata lūṭ(in), kānatā taḥta ‘abdaini min ‘ibādinā ṣāliḥaini fa khānatāhumā falam yugniyā ‘anhumā minallāhi syai'aw wa qīladkhulan-nāra ma‘ad-dākhilīn(a).", "اللّه membuat perumpamaan bagi orang-orang yang kufur, yaitu istri Nuh dan istri Lut. Keduanya berada di bawah (tanggung jawab) dua orang hamba yang saleh di antara hamba-hamba Kami, lalu keduanya berkhianat kepada (suami-suami)-nya. Mereka (kedua suami itu) tidak dapat membantunya sedikit pun dari (siksaan) اللّه, dan dikatakan (kepada kedua istri itu), “Masuklah kamu berdua ke neraka bersama orang-orang yang masuk (neraka).”"),
    Ayah(11, 66, "وَضَرَبَ اللّٰهُ مَثَلًا لِّلَّذِيْنَ اٰمَنُوا امْرَاَتَ فِرْعَوْنَۘ اِذْ قَالَتْ رَبِّ ابْنِ لِيْ عِنْدَكَ بَيْتًا فِى الْجَنَّةِ وَنَجِّنِيْ مِنْ فِرْعَوْنَ وَعَمَلِهٖ وَنَجِّنِيْ مِنَ الْقَوْمِ الظّٰلِمِيْنَۙ", "Wa ḍaraballāhu maṡalal lil-lażīna āmanumra'ata fir‘aun(a), iż qālat rabbibni lī ‘indaka baitan fil jannati wa najjinī min fir‘auna wa ‘amalihī wa najjinī minal qaumiẓ-ẓālimīn(a).", "اللّه juga membuat perumpamaan bagi orang-orang yang beriman, yaitu istri Fir‘aun, ketika dia berkata, “Ya Tuhanku, bangunkanlah untukku di sisi-Mu sebuah rumah dalam surga, selamatkanlah aku dari Fir‘aun dan perbuatannya, serta selamatkanlah aku dari kaum yang zalim.”"),
    Ayah(12, 66, "وَمَرْيَمَ ابْنَتَ عِمْرٰنَ الَّتِيْٓ اَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيْهِ مِنْ رُّوْحِنَا وَصَدَّقَتْ بِكَلِمٰتِ رَبِّهَا وَكُتُبِهٖ وَكَانَتْ مِنَ الْقٰنِتِيْنَ ࣖ ۔", "Wa maryamabnata ‘imrānal-latī aḥṣanat farjahā fa nafakhnā fīhi mir rūḥinā wa ṣaddaqat bikalimāti rabbihā wa kutubihī wa kānat minal-qānitīn(a).", "Demikian pula Maryam putri Imran yang memelihara kehormatannya, lalu Kami meniupkan ke dalam rahimnya sebagian dari roh (ciptaan) Kami, dan yang membenarkan kalimat-kalimat Tuhannya dan kitab-kitab-Nya, serta yang termasuk orang-orang taat."),
)

internal fun quranFullAyahs67(): List<Ayah> = listOf(
    Ayah(1, 67, "تَبٰرَكَ الَّذِيْ بِيَدِهِ الْمُلْكُۖ وَهُوَ عَلٰى كُلِّ شَيْءٍ قَدِيْرٌۙ", "Tabārakal-lażī biyadihil-mulk(u), wa huwa ‘alā kulli syai'in qadīr(un).", "Mahaberkah Zat yang menguasai (segala) kerajaan dan Dia Mahakuasa atas segala sesuatu,"),
    Ayah(2, 67, "ۨالَّذِيْ خَلَقَ الْمَوْتَ وَالْحَيٰوةَ لِيَبْلُوَكُمْ اَيُّكُمْ اَحْسَنُ عَمَلًاۗ وَهُوَ الْعَزِيْزُ الْغَفُوْرُۙ", "Allażī khalaqal-mauta wal-ḥayāta liyabluwakum ayyukum aḥsanu ‘amalā(n), wa huwal-‘azīzul-gafūr(u).", "yaitu yang menciptakan kematian dan kehidupan untuk menguji kamu, siapa di antara kamu yang lebih baik amalnya. Dia Mahaperkasa lagi Maha Pengampun."),
    Ayah(3, 67, "الَّذِيْ خَلَقَ سَبْعَ سَمٰوٰتٍ طِبَاقًاۗ مَا تَرٰى فِيْ خَلْقِ الرَّحْمٰنِ مِنْ تَفٰوُتٍۗ فَارْجِعِ الْبَصَرَۙ هَلْ تَرٰى مِنْ فُطُوْرٍ", "Allażī khalaqa sab‘a samāwātin ṭibāqā(n), mā tarā fī khalqir-raḥmāni min tafāwut(in), farji‘il-baṣara hal tarā min fuṭūr(in).", "(Dia juga) yang menciptakan tujuh langit berlapis-lapis. Kamu tidak akan melihat pada ciptaan Tuhan Yang Maha Pengasih ketidakseimbangan sedikit pun. Maka, lihatlah sekali lagi! Adakah kamu melihat suatu cela?"),
    Ayah(4, 67, "ثُمَّ ارْجِعِ الْبَصَرَ كَرَّتَيْنِ يَنْقَلِبْ اِلَيْكَ الْبَصَرُ خَاسِئًا وَّهُوَ حَسِيْرٌ", "Ṡummarji‘il-baṣara karrataini yanqalib ilaikal-baṣaru khāsi'aw wa huwa ḥasīr(un).", "Kemudian, lihatlah sekali lagi (dan) sekali lagi (untuk mencari cela dalam ciptaan اللّه), niscaya pandanganmu akan kembali kepadamu dengan kecewa dan dalam keadaan letih (karena tidak menemukannya)."),
    Ayah(5, 67, "وَلَقَدْ زَيَّنَّا السَّمَاۤءَ الدُّنْيَا بِمَصَابِيْحَ وَجَعَلْنٰهَا رُجُوْمًا لِّلشَّيٰطِيْنِ وَاَعْتَدْنَا لَهُمْ عَذَابَ السَّعِيْرِ", "Wa laqad zayyannas-samā'ad-dun-yā bimaṣābīḥa wa ja‘alnāhā rujūmal lisy-syayāṭīni wa a‘tadnā lahum ‘ażābas-sa‘īr(i).", "Sungguh, Kami benar-benar telah menghiasi langit dunia dengan bintang-bintang, menjadikannya (bintang-bintang itu) sebagai alat pelempar terhadap setan, dan menyediakan bagi mereka (setan-setan itu) azab (neraka) Sa‘ir (yang menyala-nyala)."),
    Ayah(6, 67, "وَلِلَّذِيْنَ كَفَرُوْا بِرَبِّهِمْ عَذَابُ جَهَنَّمَۗ وَبِئْسَ الْمَصِيْرُ", "Wa lil-lażīna kafarū birabbihim ‘ażābu jahannam(a), wa bi'sal-maṣīr(u).", "Orang-orang yang kufur kepada Tuhannya akan mendapat azab (neraka) Jahanam. Itulah seburuk-buruk tempat kembali."),
    Ayah(7, 67, "اِذَآ اُلْقُوْا فِيْهَا سَمِعُوْا لَهَا شَهِيْقًا وَّهِيَ تَفُوْرُۙ", "Iżā ulqū fīhā sami‘ū lahā syahīqaw wa hiya tafūr(u).", "Apabila dilemparkan ke dalamnya (neraka), mereka pasti mendengar suaranya yang mengerikan saat ia membara."),
    Ayah(8, 67, "تَكَادُ تَمَيَّزُ مِنَ الْغَيْظِۗ كُلَّمَآ اُلْقِيَ فِيْهَا فَوْجٌ سَاَلَهُمْ خَزَنَتُهَآ اَلَمْ يَأْتِكُمْ نَذِيْرٌۙ", "Takādu tamayyazu minal-gaiẓ(i), kullamā ulqiya fīhā faujun sa'alahum khazanatuhā alam ya'tikum nażīr(un).", "(Neraka itu) hampir meledak karena marah. Setiap kali ada sekumpulan (orang-orang kafir) dilemparkan ke dalamnya, penjaga-penjaganya bertanya kepada mereka, “Tidak pernahkah seorang pemberi peringatan datang kepadamu (di dunia)?”"),
    Ayah(9, 67, "قَالُوْا بَلٰى قَدْ جَاۤءَنَا نَذِيْرٌ ەۙ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ اللّٰهُ مِنْ شَيْءٍۖ اِنْ اَنْتُمْ اِلَّا فِيْ ضَلٰلٍ كَبِيْرٍ", "Qālū balā qad jā'anā nażīr(un), fa każżabnā wa qulnā mā nazzalallāhu min syai'(in), in antum illā fī ḍalālin kabīr(in).", "Mereka menjawab, “Pernah! Sungguh, seorang pemberi peringatan telah datang kepada kami, tetapi kami mendustakan(-nya) dan mengatakan, ‘اللّه tidak menurunkan sesuatu apa pun.’” (Para malaikat berkata,) “Kamu tidak lain hanyalah (berada) dalam kesesatan yang besar.”"),
    Ayah(10, 67, "وَقَالُوْا لَوْ كُنَّا نَسْمَعُ اَوْ نَعْقِلُ مَا كُنَّا فِيْٓ اَصْحٰبِ السَّعِيْرِ", "Wa qālū lau kunnā nasma‘u au na‘qilu mā kunnā fī aṣḥābis-sa‘īr(i).", "Mereka juga berkata, “Andaikan dahulu kami mendengarkan atau memikirkan (peringatan itu), tentulah kami tidak termasuk ke dalam (golongan) para penghuni (neraka) Sa‘ir (yang menyala-nyala).”"),
    Ayah(11, 67, "فَاعْتَرَفُوْا بِذَنْۢبِهِمْۚ فَسُحْقًا لِّاَصْحٰبِ السَّعِيْرِ", "Fa‘tarafū biżambihim, fasuḥqal li'aṣḥābis-sa‘īr(i).", "Mereka mengakui dosanya (saat penyesalan tidak lagi bermanfaat). Maka, jauhlah (dari rahmat اللّه) bagi para penghuni (neraka) Sa‘ir (yang menyala-nyala) itu."),
    Ayah(12, 67, "اِنَّ الَّذِيْنَ يَخْشَوْنَ رَبَّهُمْ بِالْغَيْبِ لَهُمْ مَّغْفِرَةٌ وَّاَجْرٌ كَبِيْرٌ", "Innal-lażīna yakhsyauna rabbahum bil-gaibi lahum magfiratuw wa ajrun kabīr(un).", "Sesungguhnya orang-orang yang takut kepada Tuhannya dengan tanpa melihat-Nya akan memperoleh ampunan dan pahala yang besar."),
    Ayah(13, 67, "وَاَسِرُّوْا قَوْلَكُمْ اَوِ اجْهَرُوْا بِهٖۗ اِنَّهٗ عَلِيْمٌ ۢبِذَاتِ الصُّدُوْرِ", "Wa asirrū qaulakum awijharū bih(ī), innahū ‘alīmum biżātiṣ-ṣudūr(i).", "Rahasiakanlah perkataanmu atau nyatakanlah. Sesungguhnya Dia Maha Mengetahui segala isi hati."),
    Ayah(14, 67, "اَلَا يَعْلَمُ مَنْ خَلَقَۗ وَهُوَ اللَّطِيْفُ الْخَبِيْرُ ࣖ", "Alā ya‘lamu man khalaq(a), wa huwal-laṭīful-khabīr(u).", "Apakah (pantas) Zat yang menciptakan itu tidak mengetahui, sedangkan Dia (juga) Mahahalus lagi Maha Mengetahui?"),
    Ayah(15, 67, "هُوَ الَّذِيْ جَعَلَ لَكُمُ الْاَرْضَ ذَلُوْلًا فَامْشُوْا فِيْ مَنَاكِبِهَا وَكُلُوْا مِنْ رِّزْقِهٖۗ وَاِلَيْهِ النُّشُوْرُ", "Huwal-lażī ja‘ala lakumul-arḍa żalūlan famsyū fī manākibihā wa kulū mir rizqih(ī), wa ilaihin-nusyūr(u).", "Dialah yang menjadikan bumi untuk kamu dalam keadaan mudah dimanfaatkan. Maka, jelajahilah segala penjurunya dan makanlah sebagian dari rezeki-Nya. Hanya kepada-Nya kamu (kembali setelah) dibangkitkan."),
    Ayah(16, 67, "ءَاَمِنْتُمْ مَّنْ فِى السَّمَاۤءِ اَنْ يَّخْسِفَ بِكُمُ الْاَرْضَ فَاِذَا هِيَ تَمُوْرُۙ", "A'amintum man fis-samā'i ay yakhsifa bikumul-arḍa fa'iżā hiya tamūr(u).", "Sudah merasa amankah kamu dari Zat yang di langit, yaitu (dari bencana) dibenamkannya bumi oleh-Nya bersama kamu ketika tiba-tiba ia terguncang?"),
    Ayah(17, 67, "اَمْ اَمِنْتُمْ مَّنْ فِى السَّمَاۤءِ اَنْ يُّرْسِلَ عَلَيْكُمْ حَاصِبًاۗ فَسَتَعْلَمُوْنَ كَيْفَ نَذِيْرِ", "Am amintum man fis-samā'i ay yursila ‘alaikum ḥāṣibā(n), fa sata‘lamūna kaifa nażīr(i).", "Atau, sudah merasa amankah kamu dari Zat yang di langit, yaitu (dari bencana) dikirimkannya badai batu oleh-Nya kepadamu? Kelak kamu akan mengetahui bagaimana (akibat mendustakan) peringatan-Ku."),
    Ayah(18, 67, "وَلَقَدْ كَذَّبَ الَّذِيْنَ مِنْ قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيْرِ", "Wa laqad każżabal-lażīna min qablihim fakaifa kāna nakīr(i).", "Sungguh, orang-orang sebelum mereka pun benar-benar telah mendustakan (rasul-rasul-Nya). Maka, betapa hebatnya kemurkaan-Ku!"),
    Ayah(19, 67, "اَوَلَمْ يَرَوْا اِلَى الطَّيْرِ فَوْقَهُمْ صٰۤفّٰتٍ وَّيَقْبِضْنَۘ مَا يُمْسِكُهُنَّ اِلَّا الرَّحْمٰنُۗ اِنَّهٗ بِكُلِّ شَيْءٍۢ بَصِيْرٌ", "Awalam yarau ilaṭ-ṭairi fauqahum ṣāffātiw wa yaqbiḍn(a), mā yumsikuhunna illar-raḥmān(u), innahū bikulli syai'im baṣīr(un).", "Tidakkah mereka memperhatikan burung-burung yang mengembangkan dan mengatupkan sayapnya di atas mereka? Tidak ada yang menahannya (di udara) selain Yang Maha Pengasih. Sesungguhnya Dia Maha Melihat segala sesuatu."),
    Ayah(20, 67, "اَمَّنْ هٰذَا الَّذِيْ هُوَ جُنْدٌ لَّكُمْ يَنْصُرُكُمْ مِّنْ دُوْنِ الرَّحْمٰنِۗ اِنِ الْكٰفِرُوْنَ اِلَّا فِيْ غُرُوْرٍۚ", "Am man hāżal-lażī huwa jundul lakum yanṣurukum min dūnir-raḥmān(i), inil-kāfirūna illā fī gurūr(in).", "Atau, siapakah yang akan menjadi bala tentara bagimu yang dapat menolongmu selain (اللّه) Yang Maha Pengasih? Orang-orang kafir itu tidak lain hanyalah dalam (keadaan) tertipu."),
    Ayah(21, 67, "اَمَّنْ هٰذَا الَّذِيْ يَرْزُقُكُمْ اِنْ اَمْسَكَ رِزْقَهٗ ۚ بَلْ لَّجُّوْا فِيْ عُتُوٍّ وَّنُفُوْرٍ", "Am man hāżal-lażī yarzuqukum in amsaka rizqah(ū), bal lajjū fī ‘utuwwiw wa nufūr(in).", "Atau, siapakah yang dapat memberimu rezeki jika Dia menahan rezeki-Nya? Sebaliknya, mereka terus-menerus dalam kesombongan dan menjauhkan diri (dari kebenaran)."),
    Ayah(22, 67, "اَفَمَنْ يَّمْشِيْ مُكِبًّا عَلٰى وَجْهِهٖٓ اَهْدٰىٓ اَمَّنْ يَّمْشِيْ سَوِيًّا عَلٰى صِرَاطٍ مُّسْتَقِيْمٍ", "Afamay yamsyī mukibban ‘alā wajhihī ahdā ammay yamsyī sawiyyan ‘alā ṣirāṭim mustaqīm(in).", "Apakah orang yang berjalan dengan wajah tertelungkup itu lebih mendapatkan petunjuk ataukah orang yang berjalan tegap di atas jalan yang lurus?"),
    Ayah(23, 67, "قُلْ هُوَ الَّذِيْٓ اَنْشَاَكُمْ وَجَعَلَ لَكُمُ السَّمْعَ وَالْاَبْصَارَ وَالْاَفْـِٕدَةَۗ قَلِيْلًا مَّا تَشْكُرُوْنَ", "Qul huwal-lażī ansya'akum wa ja‘ala lakumus-sam‘a wal-abṣāra wal-af'idah(ta), qalīlam mā tasykurūn(a).", "Katakanlah, “Dialah Zat yang menciptakanmu dan menjadikan bagimu pendengaran, penglihatan, dan hati nurani. (Akan tetapi,) sedikit sekali kamu bersyukur.”"),
    Ayah(24, 67, "قُلْ هُوَ الَّذِيْ ذَرَاَكُمْ فِى الْاَرْضِ وَاِلَيْهِ تُحْشَرُوْنَ", "Qul huwal-lażī żara'akum fil-arḍi wa ilaihi tuḥsyarūn(a).", "Katakanlah, “Dialah yang menjadikan kamu berkembang biak di muka bumi dan kepada-Nyalah kamu akan dikumpulkan.”"),
    Ayah(25, 67, "وَيَقُوْلُوْنَ مَتٰى هٰذَا الْوَعْدُ اِنْ كُنْتُمْ صٰدِقِيْنَ", "Wa yaqūlūna matā hāżal-wa‘du in kuntum ṣādiqīn(a).", "Mereka berkata, “Kapankah (datangnya) janji (azab) ini jika kamu orang-orang benar?”"),
    Ayah(26, 67, "قُلْ اِنَّمَا الْعِلْمُ عِنْدَ اللّٰهِ ۖوَاِنَّمَآ اَنَا۠ نَذِيْرٌ مُّبِيْنٌ", "Qul innamal-‘ilmu ‘indallāh(i), wa innamā ana nażīrum mubīn(un).", "Katakanlah (Nabi Muhammad), “Sesungguhnya ilmu (tentang hari Kiamat itu) hanya ada pada اللّه. Aku hanyalah seorang pemberi peringatan yang jelas.”"),
    Ayah(27, 67, "فَلَمَّا رَاَوْهُ زُلْفَةً سِيْۤـَٔتْ وُجُوْهُ الَّذِيْنَ كَفَرُوْا وَقِيْلَ هٰذَا الَّذِيْ كُنْتُمْ بِهٖ تَدَّعُوْنَ", "Falammā ra'auhu zulfatan sī'at wujūhul-lażīna kafarū wa qīla hāżal-lażī kuntum bihī tadda‘ūn(a).", "Ketika mereka melihat azab (pada hari Kiamat) sudah dekat, wajah orang-orang kafir itu menjadi muram. Dikatakan (kepada mereka), “Ini adalah (sesuatu) yang dahulu kamu selalu mengaku (bahwa kamu tidak akan dibangkitkan).”"),
    Ayah(28, 67, "قُلْ اَرَءَيْتُمْ اِنْ اَهْلَكَنِيَ اللّٰهُ وَمَنْ مَّعِيَ اَوْ رَحِمَنَاۙ فَمَنْ يُّجِيْرُ الْكٰفِرِيْنَ مِنْ عَذَابٍ اَلِيْمٍ", "Qul ara'aitum in ahlakaniyallāhu wa mam ma‘iya au raḥimanā, famay yujīrul-kāfirīna min ‘ażābin alīm(in).", "Katakanlah (Nabi Muhammad), “Tahukah kamu jika اللّه mematikan aku dan orang-orang yang bersamaku atau memberi rahmat kepada kami (dengan memperpanjang umur kami,) lalu siapa yang dapat melindungi orang-orang kafir dari azab yang pedih?”"),
    Ayah(29, 67, "قُلْ هُوَ الرَّحْمٰنُ اٰمَنَّا بِهٖ وَعَلَيْهِ تَوَكَّلْنَاۚ فَسَتَعْلَمُوْنَ مَنْ هُوَ فِيْ ضَلٰلٍ مُّبِيْنٍ", "Qul huwar-raḥmānu āmannā bihī wa ‘alaihi tawakkalnā, fasata‘lamūna man huwa fī ḍalālim mubīn(in).", "Katakanlah (Nabi Muhammad), “Dialah Zat Yang Maha Pengasih, kami beriman kepada-Nya dan hanya kepada-Nya kami bertawakal. Kelak kamu akan tahu siapa yang berada dalam kesesatan yang nyata.”"),
    Ayah(30, 67, "قُلْ اَرَءَيْتُمْ اِنْ اَصْبَحَ مَاۤؤُكُمْ غَوْرًا فَمَنْ يَّأْتِيْكُمْ بِمَاۤءٍ مَّعِيْنٍ ࣖ", "Qul ara'aitum in aṣbaḥa mā'ukum gauran famay ya'tīkum bimā'im ma‘īn(in).", "Katakanlah (Nabi Muhammad), “Terangkanlah kepadaku jika (sumber) air kamu surut ke dalam tanah, siapa yang akan memberimu air yang mengalir?”"),
)

internal fun quranFullAyahs68(): List<Ayah> = listOf(
    Ayah(1, 68, "نۤ ۚوَالْقَلَمِ وَمَا يَسْطُرُوْنَۙ", "Nūn, wal-qalami wa mā yasṭurūn(a).", "Nūn. Demi pena dan apa yang mereka tuliskan,"),
    Ayah(2, 68, "مَآ اَنْتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُوْنٍ", "Mā anta bini‘mati rabbika bimajnūn(in).", "berkat karunia Tuhanmu engkau (Nabi Muhammad) bukanlah orang gila."),
    Ayah(3, 68, "وَاِنَّ لَكَ لَاَجْرًا غَيْرَ مَمْنُوْنٍۚ", "Wa inna laka la'ajran gaira mamnūn(in).", "Sesungguhnya bagi engkaulah pahala yang tidak putus-putus."),
    Ayah(4, 68, "وَاِنَّكَ لَعَلٰى خُلُقٍ عَظِيْمٍ", "Wa innaka la‘alā khuluqin ‘aẓīm(in).", "Sesungguhnya engkau benar-benar berbudi pekerti yang agung."),
    Ayah(5, 68, "فَسَتُبْصِرُ وَيُبْصِرُوْنَۙ", "Fasatubṣiru wa yubṣirūn(a).", "Kelak engkau akan melihat dan mereka (orang-orang kafir) pun akan melihat,"),
    Ayah(6, 68, "بِاَيِّىكُمُ الْمَفْتُوْنُ", "Bi'ayyikumul-maftūn(u).", "siapa di antara kamu yang gila?"),
    Ayah(7, 68, "اِنَّ رَبَّكَ هُوَ اَعْلَمُ بِمَنْ ضَلَّ عَنْ سَبِيْلِهٖۖ وَهُوَ اَعْلَمُ بِالْمُهْتَدِيْنَ", "Inna rabbaka huwa a‘lamu biman ḍalla ‘an sabīlih(ī), wa huwa a‘lamu bil-muhtadīn(a).", "Sesungguhnya Tuhanmulah yang paling mengetahui siapa yang sesat dari jalan-Nya. Dialah yang paling mengetahui siapa orang yang mendapat petunjuk."),
    Ayah(8, 68, "فَلَا تُطِعِ الْمُكَذِّبِيْنَ", "Falā tuṭi‘il-mukażżibīn(a).", "Maka, janganlah engkau patuhi orang-orang yang mendustakan (ayat-ayat اللّه)."),
    Ayah(9, 68, "وَدُّوْا لَوْ تُدْهِنُ فَيُدْهِنُوْنَۚ", "Waddū lau tudhinu fayudhinūn(a).", "Mereka menginginkan agar engkau bersikap lunak. Maka, mereka bersikap lunak (pula)."),
    Ayah(10, 68, "وَلَا تُطِعْ كُلَّ حَلَّافٍ مَّهِيْنٍۙ", "Wa lā tuṭi‘ kulla ḥallāfim mahīn(in).", "Janganlah engkau patuhi setiap orang yang suka bersumpah lagi berkepribadian hina,"),
    Ayah(11, 68, "هَمَّازٍ مَّشَّاۤءٍۢ بِنَمِيْمٍۙ", "Hammāzim masysyā'im binamīm(in).", "suka mencela, (berjalan) kian kemari menyebarkan fitnah (berita bohong),"),
    Ayah(12, 68, "مَّنَّاعٍ لِّلْخَيْرِ مُعْتَدٍ اَثِيْمٍۙ", "Mannā‘il lil-khairi mu‘tadin aṡīm(in).", "merintangi segala yang baik, melampaui batas dan banyak dosa,"),
    Ayah(13, 68, "عُتُلٍّۢ بَعْدَ ذٰلِكَ زَنِيْمٍۙ", "‘Utullim ba‘da żālika zanīm(in).", "bertabiat kasar, dan selain itu juga terkenal kejahatannya,"),
    Ayah(14, 68, "اَنْ كَانَ ذَا مَالٍ وَّبَنِيْنَۗ", "An kāna żā māliw wa banīn(a).", "karena dia kaya dan mempunyai banyak anak."),
    Ayah(15, 68, "اِذَا تُتْلٰى عَلَيْهِ اٰيٰتُنَا قَالَ اَسَاطِيْرُ الْاَوَّلِيْنَۗ", "Iżā tutlā ‘alaihi āyātunā qāla asāṭīrul-awwalīn(a).", "Apabila ayat-ayat Kami dibacakan kepadanya, dia berkata, “(Ini adalah) dongengan orang-orang terdahulu.”"),
    Ayah(16, 68, "سَنَسِمُهٗ عَلَى الْخُرْطُوْمِ", "Sanasimuhū ‘alal-khurṭūm(i).", "Kelak dia akan Kami beri tanda pada belalai (hidung)-nya."),
    Ayah(17, 68, "اِنَّا بَلَوْنٰهُمْ كَمَا بَلَوْنَآ اَصْحٰبَ الْجَنَّةِۚ اِذْ اَقْسَمُوْا لَيَصْرِمُنَّهَا مُصْبِحِيْنَۙ", "Innā balaunāhum kamā balaunā aṣḥābal-jannah(ti), iż aqsamū layaṣrimunnahā muṣbiḥīn(a).", "Sesungguhnya Kami telah menguji mereka (orang musyrik Makkah) sebagaimana Kami telah menguji pemilik-pemilik kebun ketika mereka bersumpah bahwa mereka pasti akan memetik (hasil)-nya pada pagi hari,"),
    Ayah(18, 68, "وَلَا يَسْتَثْنُوْنَ", "Wa lā yastaṡnūn(a).", "tetapi mereka tidak mengecualikan (dengan mengucapkan, “Insyaallah”)."),
    Ayah(19, 68, "فَطَافَ عَلَيْهَا طَاۤىِٕفٌ مِّنْ رَّبِّكَ وَهُمْ نَاۤىِٕمُوْنَ", "Fa ṭāfa ‘alaihā ṭā'ifum mir rabbika wa hum nā'imūn(a).", "Lalu, kebun itu ditimpa bencana (yang datang) dari Tuhanmu ketika mereka sedang tidur."),
    Ayah(20, 68, "فَاَصْبَحَتْ كَالصَّرِيْمِۙ", "Fa aṣbaḥat kaṣ-ṣarīm(i).", "Maka, jadilah kebun itu hitam (karena terbakar) seperti malam yang gelap gulita."),
    Ayah(21, 68, "فَتَنَادَوْا مُصْبِحِيْنَۙ", "Fa tanādau muṣbiḥīn(a).", "Lalu, mereka saling memanggil pada pagi hari,"),
    Ayah(22, 68, "اَنِ اغْدُوْا عَلٰى حَرْثِكُمْ اِنْ كُنْتُمْ صٰرِمِيْنَ", "Anigdū ‘alā ḥarṡikum in kuntum ṣārimīn(a).", "“Pergilah pagi-pagi ke kebunmu jika kamu hendak memetik hasil.”"),
    Ayah(23, 68, "فَانْطَلَقُوْا وَهُمْ يَتَخَافَتُوْنَۙ", "Fanṭalaqū wa hum yatakhāfatūn(a).", "Mereka pun berangkat sambil berbisik-bisik,"),
    Ayah(24, 68, "اَنْ لَّا يَدْخُلَنَّهَا الْيَوْمَ عَلَيْكُمْ مِّسْكِيْنٌۙ", "Allā yadkhulannahal-yauma ‘alaikum miskīn(un).", "“Pada hari ini jangan sampai ada orang miskin yang masuk ke dalam kebunmu.”"),
    Ayah(25, 68, "وَّغَدَوْا عَلٰى حَرْدٍ قٰدِرِيْنَ", "Wa gadau ‘alā ḥardin qādirīn(a).", "Berangkatlah mereka pada pagi hari dengan niat menghalangi (orang-orang miskin). Mereka mengira mampu (melakukan hal itu)."),
    Ayah(26, 68, "فَلَمَّا رَاَوْهَا قَالُوْٓا اِنَّا لَضَاۤلُّوْنَۙ", "Falammā ra'auhā qālū innā laḍāllūn(a).", "Ketika melihat kebun itu, mereka berkata, “Sesungguhnya kita benar-benar orang sesat."),
    Ayah(27, 68, "بَلْ نَحْنُ مَحْرُوْمُوْنَ", "Bal naḥnu maḥrūmūn(a).", "Bahkan, kita tidak memperoleh apa pun.”"),
    Ayah(28, 68, "قَالَ اَوْسَطُهُمْ اَلَمْ اَقُلْ لَّكُمْ لَوْلَا تُسَبِّحُوْنَ", "Qāla ausaṭuhum alam aqul lakum lau lā tusabbiḥūn(a).", "Seorang yang paling bijak di antara mereka berkata, “Bukankah aku telah mengatakan kepadamu hendaklah kamu bertasbih (kepada Tuhanmu)?”"),
    Ayah(29, 68, "قَالُوْا سُبْحٰنَ رَبِّنَآ اِنَّا كُنَّا ظٰلِمِيْنَ", "Qālū subḥāna rabbinā innā kunnā ẓālimīn(a).", "Mereka mengucapkan, “Mahasuci Tuhan kami. Sungguh, kami adalah orang-orang yang zalim.”"),
    Ayah(30, 68, "فَاَقْبَلَ بَعْضُهُمْ عَلٰى بَعْضٍ يَّتَلَاوَمُوْنَ", "Fa'aqbala ba‘ḍuhum ‘alā ba‘ḍiy yatalāwamūn(a).", "Mereka saling berhadapan dengan saling mencela."),
    Ayah(31, 68, "قَالُوْا يٰوَيْلَنَآ اِنَّا كُنَّا طٰغِيْنَ", "Qālū yā wailanā innā kunnā ṭāgīn(a).", "Mereka berkata, “Aduh celaka kita! Sesungguhnya kita adalah orang-orang yang melampaui batas."),
    Ayah(32, 68, "عَسٰى رَبُّنَآ اَنْ يُّبْدِلَنَا خَيْرًا مِّنْهَآ اِنَّآ اِلٰى رَبِّنَا رٰغِبُوْنَ", "‘Asā rabbunā ay yubdilanā khairam minhā innā ilā rabbinā rāgibūn(a).", "Mudah-mudahan Tuhan memberikan ganti kepada kita dengan yang lebih baik daripadanya. Sesungguhnya kita mengharapkan (ampunan dan kebaikan) Tuhan kita.”"),
    Ayah(33, 68, "كَذٰلِكَ الْعَذَابُۗ وَلَعَذَابُ الْاٰخِرَةِ اَكْبَرُۘ لَوْ كَانُوْا يَعْلَمُوْنَ ࣖ", "Każālikal-‘ażāb(u), wa la‘ażābul-ākhirati akbar(u), lau kānū ya‘lamūn(a).", "Seperti itulah azab (di dunia). Sungguh, azab akhirat lebih besar sekiranya mereka mengetahui."),
    Ayah(34, 68, "اِنَّ لِلْمُتَّقِيْنَ عِنْدَ رَبِّهِمْ جَنّٰتِ النَّعِيْمِ", "Inna lil-muttaqīna ‘inda rabbihim jannātin-na‘īm(i).", "Sesungguhnya orang-orang yang bertakwa mendapatkan surga yang penuh kenikmatan di sisi Tuhannya."),
    Ayah(35, 68, "اَفَنَجْعَلُ الْمُسْلِمِيْنَ كَالْمُجْرِمِيْنَۗ", "Afanaj‘alul-muslimīna kal-mujrimīn(a).", "Apakah patut Kami memperlakukan orang-orang Islam (orang yang tunduk kepada اللّه) seperti orang-orang yang pendurhaka (orang kafir)?"),
    Ayah(36, 68, "مَا لَكُمْۗ كَيْفَ تَحْكُمُوْنَۚ", "Mā lakum, kaifa taḥkumūn(a).", "Mengapa kamu (berbuat demikian)? Bagaimana kamu mengambil putusan?"),
    Ayah(37, 68, "اَمْ لَكُمْ كِتٰبٌ فِيْهِ تَدْرُسُوْنَۙ", "Am lakum kitābun fīhi tadrusūn(a).", "Atau, apakah kamu mempunyai kitab (yang diturunkan اللّه) yang kamu pelajari?"),
    Ayah(38, 68, "اِنَّ لَكُمْ فِيْهِ لَمَا تَخَيَّرُوْنَۚ", "Inna lakum fīhi lamā takhayyarūn(a).", "Sesungguhnya di dalamnya kamu dapat memilih apa saja yang kamu sukai."),
    Ayah(39, 68, "اَمْ لَكُمْ اَيْمَانٌ عَلَيْنَا بَالِغَةٌ اِلٰى يَوْمِ الْقِيٰمَةِۙ اِنَّ لَكُمْ لَمَا تَحْكُمُوْنَۚ", "Am lakum aimānun ‘alainā bāligatun ilā yaumil-qiyāmah(ti), inna lakum lamā taḥkumūn(a).", "Atau, apakah kamu memperoleh (janji-janji yang diperkuat dengan) sumpah dari Kami, yang tetap berlaku sampai hari Kiamat, (yakni) bahwa kamu dapat mengambil putusan (sekehendakmu)?"),
    Ayah(40, 68, "سَلْهُمْ اَيُّهُمْ بِذٰلِكَ زَعِيْمٌۚ", "Salhum ayyuhum biżālika za‘īm(un).", "Tanyakanlah kepada mereka (kaum musyrik) siapakah di antara mereka yang bertanggung jawab terhadap (putusan yang diambil itu)."),
    Ayah(41, 68, "اَمْ لَهُمْ شُرَكَاۤءُۚ فَلْيَأْتُوْا بِشُرَكَاۤىِٕهِمْ اِنْ كَانُوْا صٰدِقِيْنَ", "Am lahum syurakā'(u), falya'tū bisyurakā'ihim in kānū ṣādiqīn(a).", "Atau, apakah mereka mempunyai sekutu-sekutu? Kalau begitu, hendaklah mereka mendatangkan sekutu-sekutunya jika mereka orang-orang benar."),
    Ayah(42, 68, "يَوْمَ يُكْشَفُ عَنْ سَاقٍ وَّيُدْعَوْنَ اِلَى السُّجُوْدِ فَلَا يَسْتَطِيْعُوْنَۙ", "Yauma yuksyafu ‘an sāqiw wa yud‘auna ilas-sujūdi falā yastaṭī‘ūn(a).", "(Ingatlah) pada hari ketika betis disingkapkan (yakni huru-hara di hari Kiamat) dan mereka diseru untuk bersujud. Namun, mereka tidak mampu."),
    Ayah(43, 68, "خَاشِعَةً اَبْصَارُهُمْ تَرْهَقُهُمْ ذِلَّةٌ ۗوَقَدْ كَانُوْا يُدْعَوْنَ اِلَى السُّجُوْدِ وَهُمْ سٰلِمُوْنَ", "Khāsyi‘atan abṣāruhum tarhaquhum żillah(tun), wa qad kānū yud‘auna ilas-sujūdi wa hum sālimun(a).", "Pandangan mereka tertunduk dan diliputi kehinaan. Sungguh, dahulu (di dunia) mereka telah diseru untuk bersujud pada waktu mereka sehat (tetapi mereka enggan)."),
    Ayah(44, 68, "فَذَرْنِيْ وَمَنْ يُّكَذِّبُ بِهٰذَا الْحَدِيْثِۗ سَنَسْتَدْرِجُهُمْ مِّنْ حَيْثُ لَا يَعْلَمُوْنَۙ", "Fażarnī wa may yukażżibu bihāżal-ḥadīṡi sanastadrijuhum min ḥaiṡu lā ya‘lamūn(a).", "Biarkan Aku bersama orang-orang yang mendustakan perkataan ini (Al-Qur’an). Kelak akan Kami biarkan mereka berangsur-angsur (menuju kebinasaan) dari arah yang tidak mereka ketahui."),
    Ayah(45, 68, "وَاُمْلِيْ لَهُمْۗ اِنَّ كَيْدِيْ مَتِيْنٌ", "Wa umlī lahum, inna kaidī matīn(un).", "Aku memberi tenggang waktu kepada mereka. Sesungguhnya rencana-Ku sangat teguh."),
    Ayah(46, 68, "اَمْ تَسْـَٔلُهُمْ اَجْرًا فَهُمْ مِّنْ مَّغْرَمٍ مُّثْقَلُوْنَۚ", "Am tas'aluhum ajran fahum mim magramim muṡqalūn(a).", "Ataukah engkau (Nabi Muhammad) meminta imbalan kepada mereka sehingga mereka dibebani utang?"),
    Ayah(47, 68, "اَمْ عِنْدَهُمُ الْغَيْبُ فَهُمْ يَكْتُبُوْنَ", "Am ‘indahumul-gaibu fahum yaktubūn(a).", "Ataukah mereka mengetahui yang gaib lalu mereka menuliskannya?"),
    Ayah(48, 68, "فَاصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تَكُنْ كَصَاحِبِ الْحُوْتِۘ اِذْ نَادٰى وَهُوَ مَكْظُوْمٌۗ", "Faṣbir liḥukmi rabbika wa lā takun kaṣāḥibil-ḥūt(i), iż nādā wa huwa makẓūm(un).", "Oleh karena itu, bersabarlah (Nabi Muhammad) terhadap ketetapan Tuhanmu dan janganlah seperti orang yang berada dalam (perut) ikan (Yunus) ketika dia berdoa dengan hati sedih."),
    Ayah(49, 68, "لَوْلَآ اَنْ تَدٰرَكَهٗ نِعْمَةٌ مِّنْ رَّبِّهٖ لَنُبِذَ بِالْعَرَاۤءِ وَهُوَ مَذْمُوْمٌ", "Lau lā an tadārakahū ni‘matum mir rabbihī lanubiża bil-‘arā'i wa huwa mażmūm(un).", "Seandainya dia tidak segera mendapat nikmat dari Tuhannya, pastilah dia dicampakkan ke tanah tandus dalam keadaan tercela."),
    Ayah(50, 68, "فَاجْتَبٰىهُ رَبُّهٗ فَجَعَلَهٗ مِنَ الصّٰلِحِيْنَ", "Fajtabāhu rabbuhū faja‘alahū minaṣ-ṣāliḥīn(a).", "Tuhannya lalu memilihnya dan menjadikannya termasuk orang-orang saleh."),
    Ayah(51, 68, "وَاِنْ يَّكَادُ الَّذِيْنَ كَفَرُوْا لَيُزْلِقُوْنَكَ بِاَبْصَارِهِمْ لَمَّا سَمِعُوا الذِّكْرَ وَيَقُوْلُوْنَ اِنَّهٗ لَمَجْنُوْنٌ ۘ", "Wa iy yakādul-lażīna kafarū layuzliqūnaka bi'abṣārihim lammā sami‘uż żikra wa yaqūlūna innahū lamajnūn(un).", "Sesungguhnya orang-orang yang kufur itu hampir-hampir menggelincirkanmu dengan pandangan matanya ketika mereka mendengar Al-Qur’an dan berkata, “Sesungguhnya dia (Nabi Muhammad) benar-benar orang gila.”"),
    Ayah(52, 68, "وَمَا هُوَ اِلَّا ذِكْرٌ لِّلْعٰلَمِيْنَ ࣖ", "Wa mā huwa illā żikrul lil-‘ālamīn(a).", "(Al-Qur’an) itu tidak lain kecuali peringatan bagi seluruh alam."),
)

internal fun quranFullAyahs69(): List<Ayah> = listOf(
    Ayah(1, 69, "اَلْحَاۤقَّةُۙ", "Al-ḥāqqah(tu).", "Al-Ḥāqqah (hari Kiamat yang pasti datang)."),
    Ayah(2, 69, "مَا الْحَاۤقَّةُ ۚ", "Mal-ḥāqqah(tu).", "Apakah al-Ḥāqqah itu?"),
    Ayah(3, 69, "وَمَآ اَدْرٰىكَ مَا الْحَاۤقَّةُ ۗ", "Wa mā adrāka mal-ḥāqqah(tu).", "Tahukah kamu apakah al-Ḥāqqah itu?"),
    Ayah(4, 69, "كَذَّبَتْ ثَمُوْدُ وَعَادٌ ۢبِالْقَارِعَةِ", "Każżabat ṡamūdu wa ‘ādum bil-qāri‘ah(ti).", "(Kaum) Samud dan ‘Ad telah mendustakan al-Qāri‘ah (hari Kiamat yang menggetarkan hati)."),
    Ayah(5, 69, "فَاَمَّا ثَمُوْدُ فَاُهْلِكُوْا بِالطَّاغِيَةِ", "Fa'ammā ṡamūdu fa uhlikū biṭ-ṭāgiyah(ti).", "Adapun (kaum) Samud, mereka telah dibinasakan dengan suara yang sangat keras,"),
    Ayah(6, 69, "وَاَمَّا عَادٌ فَاُهْلِكُوْا بِرِيْحٍ صَرْصَرٍ عَاتِيَةٍۙ", "Wa ammā ‘ādun fa'uhlikū birīḥin ṣarṣarin ‘ātiyah(tin).", "sedangkan (kaum) ‘Ad telah dibinasakan dengan angin topan yang sangat dingin."),
    Ayah(7, 69, "سَخَّرَهَا عَلَيْهِمْ سَبْعَ لَيَالٍ وَّثَمٰنِيَةَ اَيَّامٍۙ حُسُوْمًا فَتَرَى الْقَوْمَ فِيْهَا صَرْعٰىۙ كَاَنَّهُمْ اَعْجَازُ نَخْلٍ خَاوِيَةٍۚ", "Sakhkharahā ‘alaihim sab‘a layāliw wa ṡamāniyata ayyām(in), ḥusūman fataral-qauma fīhā ṣar‘ā, ka'annahum a‘jāzu nakhlin khāwiyah(tin).", "Dia menimpakan angin itu kepada mereka selama tujuh malam delapan hari terus-menerus. Maka, kamu melihat kaum (‘Ad) pada waktu itu mati bergelimpangan seperti batang-batang pohon kurma yang telah (lapuk) bagian dalamnya."),
    Ayah(8, 69, "فَهَلْ تَرٰى لَهُمْ مِّنْۢ بَاقِيَةٍ", "Fahal tarā lahum mim bāqiyah(tin).", "Adakah kamu melihat seorang pun yang masih tersisa di antara mereka?"),
    Ayah(9, 69, "وَجَاۤءَ فِرْعَوْنُ وَمَنْ قَبْلَهٗ وَالْمُؤْتَفِكٰتُ بِالْخَاطِئَةِۚ", "Wa jā'a fir‘aunu wa man qablahū wal-mu'tafikātu bil-khāṭi'ah(ti).", "Begitu juga, Firʻaun dan orang-orang yang sebelumnya serta (penduduk) negeri-negeri yang dijungkirbalikkan datang dengan membawa kesalahan yang besar."),
    Ayah(10, 69, "فَعَصَوْا رَسُوْلَ رَبِّهِمْ فَاَخَذَهُمْ اَخْذَةً رَّابِيَةً", "Fa ‘aṣau rasūla rabbihim fa akhażahum akhżatar rābiyah(tan).", "Mereka mendurhakai utusan Tuhannya, lalu Dia menyiksa mereka dengan siksaan yang sangat keras."),
    Ayah(11, 69, "اِنَّا لَمَّا طَغَا الْمَاۤءُ حَمَلْنٰكُمْ فِى الْجَارِيَةِۙ", "Innā lammā ṭagal-mā'u ḥamalnākum fil-jāriyah(ti).", "Sesungguhnya ketika air naik (sampai ke gunung), Kami membawa (nenek moyang)-mu ke dalam (bahtera) yang berlayar"),
    Ayah(12, 69, "لِنَجْعَلَهَا لَكُمْ تَذْكِرَةً وَّتَعِيَهَآ اُذُنٌ وَّاعِيَةٌ", "Linaj‘alahā lakum tażkirataw wa ta‘iyahā użunuw wā‘iyah(tun).", "agar Kami jadikan (peristiwa) itu sebagai peringatan bagi kamu dan agar diperhatikan oleh telinga yang mau mendengar."),
    Ayah(13, 69, "فَاِذَا نُفِخَ فِى الصُّوْرِ نَفْخَةٌ وَّاحِدَةٌ ۙ", "Fa iżā nufikha fiṣ-ṣūri nafkhatuw wāḥidah(tun).", "Apabila sangkakala ditiup dengan sekali tiupan"),
    Ayah(14, 69, "وَّحُمِلَتِ الْاَرْضُ وَالْجِبَالُ فَدُكَّتَا دَكَّةً وَّاحِدَةًۙ", "Wa ḥumilatil-arḍu wal-jibālu fa dukkatā dakkataw wāḥidah(tan).", "dan bumi serta gunung-gunung diangkat lalu dibenturkan dengan sekali benturan,"),
    Ayah(15, 69, "فَيَوْمَىِٕذٍ وَّقَعَتِ الْوَاقِعَةُۙ", "Fayauma'iżiw waqa‘atil-wāqi‘ah(tu).", "pada hari itu terjadilah kiamat."),
    Ayah(16, 69, "وَانْشَقَّتِ السَّمَاۤءُ فَهِيَ يَوْمَىِٕذٍ وَّاهِيَةٌۙ", "Wansyaqqatis-samā'u fahiya yauma'iżiw wāhiyah(tun).", "Langit juga terbelah karena pada hari itu ia rapuh."),
    Ayah(17, 69, "وَّالْمَلَكُ عَلٰٓى اَرْجَاۤىِٕهَاۗ وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَىِٕذٍ ثَمٰنِيَةٌ ۗ", "Wal-malaku ‘alā arjā'ihā, wa yaḥmilu ‘arsya rabbika fauqahum yauma'iżin ṡamāniyah(tun).", "Para malaikat berada di berbagai penjurunya (langit). Pada hari itu delapan malaikat menjunjung ʻArasy (singgasana) Tuhanmu di atas mereka."),
    Ayah(18, 69, "يَوْمَىِٕذٍ تُعْرَضُوْنَ لَا تَخْفٰى مِنْكُمْ خَافِيَةٌ", "Yauma'iżin tu‘raḍūna lā takhfā minkum khāfiyah(tun).", "Pada hari itu kamu dihadapkan (kepada Tuhanmu). Tidak ada sesuatu pun dari kamu yang tersembunyi."),
    Ayah(19, 69, "فَاَمَّا مَنْ اُوْتِيَ كِتٰبَهٗ بِيَمِيْنِهٖ فَيَقُوْلُ هَاۤؤُمُ اقْرَءُوْا كِتٰبِيَهْۚ", "Fa ammā man ūtiya kitābahū biyamīnihī fa yaqūlu hā'umuqra'ū kitābiyah.", "Adapun orang yang diberi catatan amalnya di tangan kanannya, dia berkata (kepada orang-orang di sekelilingnya), “Ambillah (dan) bacalah kitabku (ini)!"),
    Ayah(20, 69, "اِنِّيْ ظَنَنْتُ اَنِّيْ مُلٰقٍ حِسَابِيَهْۚ", "Innī ẓanantu annī mulāqin ḥisābiyah.", "Sesungguhnya (saat di dunia) aku yakin bahwa (suatu saat) aku akan menerima perhitungan diriku.”"),
    Ayah(21, 69, "فَهُوَ فِيْ عِيْشَةٍ رَّاضِيَةٍۚ", "Fa huwa fī ‘īsyatir rāḍiyah(tin).", "Maka, ia berada dalam kehidupan yang menyenangkan"),
    Ayah(22, 69, "فِيْ جَنَّةٍ عَالِيَةٍۙ", "Fī jannatin ‘āliyah(tin).", "dalam surga yang tinggi"),
    Ayah(23, 69, "قُطُوْفُهَا دَانِيَةٌ", "Quṭūfuhā dāniyah(tun).", "yang buah-buahannya dekat."),
    Ayah(24, 69, "كُلُوْا وَاشْرَبُوْا هَنِيْۤـًٔا ۢبِمَآ اَسْلَفْتُمْ فِى الْاَيَّامِ الْخَالِيَةِ", "Kulū wasyrabū hanī'am bimā aslaftum fil-ayyāmil-khāliyah(ti).", "(Dikatakan kepada mereka,) “Makan dan minumlah dengan nikmat sebagai balasan amal yang kamu kerjakan pada hari-hari yang telah lalu.”"),
    Ayah(25, 69, "وَاَمَّا مَنْ اُوْتِيَ كِتٰبَهٗ بِشِمَالِهٖ ەۙ فَيَقُوْلُ يٰلَيْتَنِيْ لَمْ اُوْتَ كِتٰبِيَهْۚ", "Wa ammā man ūtiya kitābahū bisyimālih(ī), fa yaqūlu yā laitanī lam ūta kitābiyah.", "Adapun orang yang diberi catatan amalnya di tangan kirinya berkata, “Seandainya saja aku tidak diberi catatan amalku"),
    Ayah(26, 69, "وَلَمْ اَدْرِ مَا حِسَابِيَهْۚ", "Wa lam adri mā ḥisābiyah.", "dan tidak mengetahui bagaimana perhitunganku."),
    Ayah(27, 69, "يٰلَيْتَهَا كَانَتِ الْقَاضِيَةَۚ", "Yā laitahā kānatil-qāḍiyah(ta).", "Seandainya saja ia (kematian) itulah yang menyudahi segala sesuatu."),
    Ayah(28, 69, "مَآ اَغْنٰى عَنِّيْ مَالِيَهْۚ", "Mā agnā ‘annī māliyah.", "Hartaku sama sekali tidak berguna bagiku."),
    Ayah(29, 69, "هَلَكَ عَنِّيْ سُلْطٰنِيَهْۚ", "Halaka ‘annī sulṭāniyah.", "Kekuasaanku telah hilang dariku.”"),
    Ayah(30, 69, "خُذُوْهُ فَغُلُّوْهُۙ", "Khużūhu fagullūh(u).", "(اللّه berfirman,) “Tangkap dia lalu belenggu tangannya ke lehernya."),
    Ayah(31, 69, "ثُمَّ الْجَحِيْمَ صَلُّوْهُۙ", "Ṡummal-jaḥīma ṣallūh(u).", "Kemudian, masukkan dia ke dalam (neraka) Jahim."),
    Ayah(32, 69, "ثُمَّ فِيْ سِلْسِلَةٍ ذَرْعُهَا سَبْعُوْنَ ذِرَاعًا فَاسْلُكُوْهُۗ", "Ṡumma fī silsilatin żar‘uhā sab‘ūna żirā‘an faslukūh(u).", "Kemudian, belit dia dengan rantai yang panjangnya tujuh puluh hasta."),
    Ayah(33, 69, "اِنَّهٗ كَانَ لَا يُؤْمِنُ بِاللّٰهِ الْعَظِيْمِۙ", "Innahū kāna lā yu'minu billāhil-‘aẓīm(i).", "Sesungguhnya dia tidak beriman kepada اللّه Yang Mahaagung."),
    Ayah(34, 69, "وَلَا يَحُضُّ عَلٰى طَعَامِ الْمِسْكِيْنِۗ", "Wa lā yaḥuḍḍu ‘alā ṭa‘āmil-miskīn(i).", "Dia juga tidak mendorong (orang lain) untuk memberi makan orang miskin."),
    Ayah(35, 69, "فَلَيْسَ لَهُ الْيَوْمَ هٰهُنَا حَمِيْمٌۙ", "Fa laisa lahul-yauma hāhunā ḥamīm(un).", "Maka, pada hari ini tidak ada seorang pun teman setia baginya di sini (neraka)."),
    Ayah(36, 69, "وَّلَا طَعَامٌ اِلَّا مِنْ غِسْلِيْنٍۙ", "Wa lā ṭa‘āmun illā min gislīn(in).", "Tidak ada makanan (baginya), kecuali dari darah dan nanah."),
    Ayah(37, 69, "لَّا يَأْكُلُهٗٓ اِلَّا الْخٰطِـُٔوْنَ ࣖ", "Lā ya'kuluhū illal-khāṭi'ūn(a).", "Tidak ada yang memakannya, kecuali para pendosa.”"),
    Ayah(38, 69, "فَلَآ اُقْسِمُ بِمَا تُبْصِرُوْنَۙ", "Falā uqsimu bimā tubṣirūn(a).", "Maka, Aku bersumpah demi apa yang kamu lihat"),
    Ayah(39, 69, "وَمَا لَا تُبْصِرُوْنَۙ", "Wa mā lā tubṣirūn(a).", "dan demi apa yang tidak kamu lihat,"),
    Ayah(40, 69, "اِنَّهٗ لَقَوْلُ رَسُوْلٍ كَرِيْمٍۙ", "Innahū laqaulu rasūlin karīm(in).", "sesungguhnya ia (Al-Qur’an) itu benar-benar wahyu (yang diturunkan kepada) Rasul yang mulia."),
    Ayah(41, 69, "وَّمَا هُوَ بِقَوْلِ شَاعِرٍۗ قَلِيْلًا مَّا تُؤْمِنُوْنَۙ", "Wa mā huwa biqauli syā‘ir(in), qalīlam mā tu'minūn(a).", "Ia (Al-Qur’an) bukanlah perkataan seorang penyair. Sedikit sekali kamu beriman (kepadanya)."),
    Ayah(42, 69, "وَلَا بِقَوْلِ كَاهِنٍۗ قَلِيْلًا مَّا تَذَكَّرُوْنَۗ", "Wa lā biqauli kāhin(in), qalīlam mā tażakkarūn(a).", "(Al-Qur’an) bukan pula perkataan tukang tenung. Sedikit sekali kamu mengambil pelajaran (darinya)."),
    Ayah(43, 69, "تَنْزِيْلٌ مِّنْ رَّبِّ الْعٰلَمِيْنَ", "Tanzīlum mir rabbil-‘ālamīn(a).", "(Al-Qur’an itu) diturunkan dari Tuhan semesta alam."),
    Ayah(44, 69, "وَلَوْ تَقَوَّلَ عَلَيْنَا بَعْضَ الْاَقَاوِيْلِۙ", "Wa lau taqawwala ‘alainā ba‘ḍal-aqāwīl(i).", "Sekiranya dia (Nabi Muhammad) mengada-adakan sebagian saja perkataan atas (nama) Kami,"),
    Ayah(45, 69, "لَاَخَذْنَا مِنْهُ بِالْيَمِيْنِۙ", "La'akhażnā minhu bil-yamīn(i).", "niscaya Kami benar-benar menyiksanya dengan penuh kekuatan."),
    Ayah(46, 69, "ثُمَّ لَقَطَعْنَا مِنْهُ الْوَتِيْنَۖ", "Ṡumma laqaṭa‘nā minhul-watīn(a).", "Kemudian, Kami benar-benar memotong urat nadinya."),
    Ayah(47, 69, "فَمَا مِنْكُمْ مِّنْ اَحَدٍ عَنْهُ حٰجِزِيْنَۙ", "Famā minkum min aḥadin ‘anhu ḥājizīn(a).", "Maka, tidak ada seorang pun dari kamu yang dapat menghalangi (Kami) darinya (pemotongan urat nadi itu)."),
    Ayah(48, 69, "وَاِنَّهٗ لَتَذْكِرَةٌ لِّلْمُتَّقِيْنَ", "Wa innahū latażkiratul lil-muttaqīn(a).", "Sesungguhnya ia (Al-Qur’an itu) benar-benar suatu pelajaran bagi orang-orang yang bertakwa."),
    Ayah(49, 69, "وَاِنَّا لَنَعْلَمُ اَنَّ مِنْكُمْ مُّكَذِّبِيْنَۗ", "Wa innā lana‘lamu anna minkum mukażżibīn(a).", "Sesungguhnya Kami benar-benar mengetahui bahwa di antara kamu ada para pendusta."),
    Ayah(50, 69, "وَاِنَّهٗ لَحَسْرَةٌ عَلَى الْكٰفِرِيْنَۚ", "Wa innahū laḥasratun ‘alal-kāfirīn(a).", "Sesungguhnya ia (pendustaan terhadap Al-Qur’an) benar-benar menjadi penyesalan bagi orang-orang kafir (di akhirat)."),
    Ayah(51, 69, "وَاِنَّهٗ لَحَقُّ الْيَقِيْنِ", "Wa innahū laḥaqqul-yaqīn(i).", "Sesungguhnya ia (Al-Qur’an itu) adalah kebenaran yang meyakinkan."),
    Ayah(52, 69, "فَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظِيْمِ ࣖ", "Fa sabbiḥ bismi rabbikal-‘aẓīm(i).", "Maka, bertasbihlah dengan (menyebut) nama Tuhanmu Yang Mahaagung."),
)

internal fun quranFullAyahs70(): List<Ayah> = listOf(
    Ayah(1, 70, "سَاَلَ سَاۤىِٕلٌۢ بِعَذَابٍ وَّاقِعٍۙ", "Sa'ala sā'ilum bi‘ażābiw wāqi‘(in).", "Seseorang (dengan nada mengejek) meminta (didatangkan) azab yang pasti akan terjadi"),
    Ayah(2, 70, "لِّلْكٰفِرِيْنَ لَيْسَ لَهٗ دَافِعٌۙ", "Lil-kāfirīna laisa lahū dāfi‘(un).", "bagi orang-orang kafir. Tidak seorang pun yang dapat menolaknya (azab)"),
    Ayah(3, 70, "مِّنَ اللّٰهِ ذِى الْمَعَارِجِۗ", "Minallāhi żil-ma‘ārij(i).", "dari اللّه, Pemilik tempat-tempat (untuk) naik."),
    Ayah(4, 70, "تَعْرُجُ الْمَلٰۤىِٕكَةُ وَالرُّوْحُ اِلَيْهِ فِيْ يَوْمٍ كَانَ مِقْدَارُهٗ خَمْسِيْنَ اَلْفَ سَنَةٍۚ", "Ta‘rujul-malā'ikatu war-rūḥu ilaihi fī yaumin kāna miqdāruhū khamsīna alfa sanah(tin).", "Para malaikat dan Rūḥ (Jibril) naik (menghadap) kepada-Nya dalam sehari yang kadarnya lima puluh ribu tahun."),
    Ayah(5, 70, "فَاصْبِرْ صَبْرًا جَمِيْلًا", "Faṣbir ṣabran jamīlā(n).", "Maka, bersabarlah dengan kesabaran yang baik."),
    Ayah(6, 70, "اِنَّهُمْ يَرَوْنَهٗ بَعِيْدًاۙ", "Innahum yaraunahū ba‘īdā(n).", "Sesungguhnya mereka memandangnya (siksaan itu) jauh (mustahil terjadi),"),
    Ayah(7, 70, "وَّنَرٰىهُ قَرِيْبًاۗ", "Wa narāhu qarībā(n).", "sedangkan Kami memandangnya dekat (pasti terjadi)."),
    Ayah(8, 70, "يَوْمَ تَكُوْنُ السَّمَاۤءُ كَالْمُهْلِۙ", "Yauma takūnus-samā'u kal-muhl(i).", "(Siksaan itu datang) pada hari (ketika) langit menjadi seperti luluhan perak,"),
    Ayah(9, 70, "وَتَكُوْنُ الْجِبَالُ كَالْعِهْنِۙ", "Wa takūnul-jibālu kal-‘ihn(i).", "gunung-gunung menjadi seperti bulu (yang beterbangan),"),
    Ayah(10, 70, "وَلَا يَسْـَٔلُ حَمِيْمٌ حَمِيْمًاۚ", "Wa lā yas'alu ḥamīmun ḥamīmā(n).", "dan tidak ada seorang pun teman setia yang menanyakan temannya,"),
    Ayah(11, 70, "يُبَصَّرُوْنَهُمْۗ يَوَدُّ الْمُجْرِمُ لَوْ يَفْتَدِيْ مِنْ عَذَابِ يَوْمِىِٕذٍۢ بِبَنِيْهِۙ", "Yubaṣṣarūnahum, yawaddul-mujrimu lau yaftadī min ‘ażābi yaumi'iżim bibanīh(i).", "(padahal) mereka saling melihat. Orang yang berbuat durhaka itu menginginkan sekiranya dia dapat menebus (dirinya) dari azab hari itu dengan anak-anaknya,"),
    Ayah(12, 70, "وَصَاحِبَتِهٖ وَاَخِيْهِۙ", "Wa ṣāḥibatihī wa akhīh(i).", "istrinya, saudaranya,"),
    Ayah(13, 70, "وَفَصِيْلَتِهِ الَّتِيْ تُـْٔوِيْهِۙ", "Wa faṣīlatihil-latī tu'wīh(i).", "keluarga yang melindunginya (di dunia),"),
    Ayah(14, 70, "وَمَنْ فِى الْاَرْضِ جَمِيْعًاۙ ثُمَّ يُنْجِيْهِۙ", "Wa man fil-arḍi jamī‘ā(n), ṡumma yunjīh(i).", "dan seluruh orang di bumi. Kemudian, (dia mengharapkan) tebusan itu dapat menyelamatkannya."),
    Ayah(15, 70, "كَلَّاۗ اِنَّهَا لَظٰىۙ", "Kallā, innahā laẓā.", "Sekali-kali tidak! Sesungguhnya ia (neraka) itu adalah api yang bergejolak"),
    Ayah(16, 70, "نَزَّاعَةً لِّلشَّوٰىۚ", "Nazzā‘atal lisy-syawā.", "yang mengelupaskan kulit kepala,"),
    Ayah(17, 70, "تَدْعُوْا مَنْ اَدْبَرَ وَتَوَلّٰىۙ", "Tad‘ū man adbara wa tawallā.", "yang memanggil orang yang berpaling dan menjauh (dari agama),"),
    Ayah(18, 70, "وَجَمَعَ فَاَوْعٰى", "Wa jama‘a fa'au‘ā.", "serta mengumpulkan (harta benda), lalu menyimpannya."),
    Ayah(19, 70, "۞ اِنَّ الْاِنْسَانَ خُلِقَ هَلُوْعًاۙ", "Innal-insāna khuliqa halu‘ā(n).", "Sesungguhnya manusia diciptakan dengan sifat keluh kesah lagi kikir."),
    Ayah(20, 70, "اِذَا مَسَّهُ الشَّرُّ جَزُوْعًاۙ", "Iżā massahusy-syarru jazū‘ā(n).", "Apabila ditimpa keburukan (kesusahan), ia berkeluh kesah."),
    Ayah(21, 70, "وَّاِذَا مَسَّهُ الْخَيْرُ مَنُوْعًاۙ", "Wa iżā massahul-khairu manū‘ā(n).", "Apabila mendapat kebaikan (harta), ia amat kikir,"),
    Ayah(22, 70, "اِلَّا الْمُصَلِّيْنَۙ", "Illal-muṣallīn(a).", "kecuali orang-orang yang mengerjakan salat,"),
    Ayah(23, 70, "الَّذِيْنَ هُمْ عَلٰى صَلَاتِهِمْ دَاۤىِٕمُوْنَۖ", "Allażīna hum ‘alā ṣalātihim dā'imūn(a).", "yang selalu setia mengerjakan salatnya,"),
    Ayah(24, 70, "وَالَّذِيْنَ فِيْٓ اَمْوَالِهِمْ حَقٌّ مَّعْلُوْمٌۖ", "Wal-lażīna fī amwālihim ḥaqqum ma‘lūm(un).", "yang di dalam hartanya ada bagian tertentu"),
    Ayah(25, 70, "لِّلسَّاۤىِٕلِ وَالْمَحْرُوْمِۖ", "Lis-sā'ili wal-maḥrūm(i).", "untuk orang (miskin) yang meminta-minta dan orang (miskin) yang menahan diri dari meminta-minta,"),
    Ayah(26, 70, "وَالَّذِيْنَ يُصَدِّقُوْنَ بِيَوْمِ الدِّيْنِۖ", "Wal-lażīna yuṣaddiqūna biyaumid-dīn(i).", "yang memercayai hari Pembalasan,"),
    Ayah(27, 70, "وَالَّذِيْنَ هُمْ مِّنْ عَذَابِ رَبِّهِمْ مُّشْفِقُوْنَۚ", "Wal-lażīna hum min ‘ażābi rabbihim musyfiqūn(a).", "dan yang takut terhadap azab Tuhannya."),
    Ayah(28, 70, "اِنَّ عَذَابَ رَبِّهِمْ غَيْرُ مَأْمُوْنٍۖ", "Inna ‘ażāba rabbihim gairu ma'mūn(in).", "Sesungguhnya tidak ada orang yang merasa aman dari azab Tuhan mereka."),
    Ayah(29, 70, "وَّالَّذِيْنَ هُمْ لِفُرُوْجِهِمْ حٰفِظُوْنَۙ", "Wal-lażīna hum lifurūjihim ḥāfiẓūn(a).", "(Termasuk orang yang selamat dari azab adalah) orang-orang yang menjaga kemaluannya,"),
    Ayah(30, 70, "اِلَّا عَلٰٓى اَزْوَاجِهِمْ اَوْ مَا مَلَكَتْ اَيْمَانُهُمْ فَاِنَّهُمْ غَيْرُ مَلُوْمِيْنَۚ", "Illā ‘alā azwājihim au mā malakat aimānuhum fa innahum gairu malūmīn(a).", "kecuali terhadap istri-istri mereka atau hamba sahaya yang mereka miliki. Sesungguhnya mereka tidak tercela (karena menggaulinya)."),
    Ayah(31, 70, "فَمَنِ ابْتَغٰى وَرَاۤءَ ذٰلِكَ فَاُولٰۤىِٕكَ هُمُ الْعَادُوْنَۚ", "Fa manibtagā warā'a żālika fa ulā'ika humul-‘ādūn(a).", "Maka, siapa yang mencari (pelampiasan syahwat) selain itu, mereka itulah orang-orang yang melampaui batas."),
    Ayah(32, 70, "وَالَّذِيْنَ هُمْ لِاَمٰنٰتِهِمْ وَعَهْدِهِمْ رٰعُوْنَۖ", "Wal-lażīna hum li'amānātihim wa ‘ahdihim rā'ūn(a).", "(Termasuk orang yang selamat dari azab adalah) orang-orang yang memelihara amanat dan janji mereka,"),
    Ayah(33, 70, "وَالَّذِيْنَ هُمْ بِشَهٰدٰتِهِمْ قَاۤىِٕمُوْنَۖ", "Wal-lażīna hum bisyahādātihim qā'imūn(a).", "yang memberikan kesaksiannya (secara benar),"),
    Ayah(34, 70, "وَالَّذِيْنَ هُمْ عَلٰى صَلَاتِهِمْ يُحَافِظُوْنَۖ", "Wal-lażīna hum ‘alā ṣalātihim yuḥāfiẓūn(a).", "dan yang memelihara salatnya."),
    Ayah(35, 70, "اُولٰۤىِٕكَ فِيْ جَنّٰتٍ مُّكْرَمُوْنَ ۗ ࣖ", "Ulā'ika fī jannātim mukramūn(a).", "Mereka itu (berada) di surga lagi dimuliakan."),
    Ayah(36, 70, "فَمَالِ الَّذِيْنَ كَفَرُوْا قِبَلَكَ مُهْطِعِيْنَۙ", "Famālil-lażīna kafarū qibalaka muhṭi‘īn(a).", "Mengapa orang-orang kafir itu bersegera datang ke arahmu (Nabi Muhammad)"),
    Ayah(37, 70, "عَنِ الْيَمِيْنِ وَعَنِ الشِّمَالِ عِزِيْنَ", "‘Anil-yamīni wa ‘anisy-syimāli ‘izīn(a).", "dari kanan dan dari kiri dengan berkelompok-kelompok?"),
    Ayah(38, 70, "اَيَطْمَعُ كُلُّ امْرِئٍ مِّنْهُمْ اَنْ يُّدْخَلَ جَنَّةَ نَعِيْمٍۙ", "Ayaṭma‘u kullumri'im minhum ay yudkhala jannata na‘īm(in).", "Apakah setiap orang dari mereka (orang-orang kafir itu) ingin dimasukkan ke dalam surga yang penuh kenikmatan?"),
    Ayah(39, 70, "كَلَّاۗ اِنَّا خَلَقْنٰهُمْ مِّمَّا يَعْلَمُوْنَ", "Kallā, innā khalaqnāhum mimmā ya‘malūn(a).", "Sekali-kali tidak! Sesungguhnya Kami menciptakan mereka dari apa yang mereka ketahui (air mani)."),
    Ayah(40, 70, "فَلَآ اُقْسِمُ بِرَبِّ الْمَشٰرِقِ وَالْمَغٰرِبِ اِنَّا لَقٰدِرُوْنَۙ", "Falā uqsimu birabbil-masyāriqi wal-magāribi innā laqādirūn(a).", "Maka, Aku bersumpah dengan Tuhan yang mengatur tempat-tempat terbit dan terbenamnya (matahari, bulan, dan bintang), sesungguhnya Kami benar-benar Mahakuasa"),
    Ayah(41, 70, "عَلٰٓى اَنْ نُّبَدِّلَ خَيْرًا مِّنْهُمْۙ وَمَا نَحْنُ بِمَسْبُوْقِيْنَ", "‘Alā an nubaddila khairam minhum, wa mā naḥnu bimasbūqīn(a).", "untuk mengganti (mereka) dengan (kaum) yang lebih baik daripada mereka. Kami sekali-kali tidak dapat dikalahkan."),
    Ayah(42, 70, "فَذَرْهُمْ يَخُوْضُوْا وَيَلْعَبُوْا حَتّٰى يُلٰقُوْا يَوْمَهُمُ الَّذِيْ يُوْعَدُوْنَۙ", "Fa żarhum yakhūḍū wa yal‘abū ḥattā yulāqū yaumahumul-lażī yū‘adūn(a)", "Maka, biarkanlah mereka tenggelam (dalam kesesatan) dan bermain-main (di dunia) sampai mereka menjumpai hari yang dijanjikan kepada mereka,"),
    Ayah(43, 70, "يَوْمَ يَخْرُجُوْنَ مِنَ الْاَجْدَاثِ سِرَاعًا كَاَنَّهُمْ اِلٰى نُصُبٍ يُّوْفِضُوْنَۙ", "Yauma yakhrujūna minal-ajdāṡi sirā‘an ka'annahum ilā nuṣubiy yūfiḍūn(a).", "(yaitu) pada hari ketika mereka keluar dari kubur dengan cepat seperti ketika mereka pergi dengan segera menuju berhala-berhala (sewaktu di dunia)."),
    Ayah(44, 70, "خَاشِعَةً اَبْصَارُهُمْ تَرْهَقُهُمْ ذِلَّةٌ ۗذٰلِكَ الْيَوْمُ الَّذِيْ كَانُوْا يُوْعَدُوْنَ ࣖ", "Khāsyi‘atan abṣāruhum tarhaquhum żillah(tun), żālikal-yaumul-lażī kānū yū‘adūn(a).", "Pandangan mereka tertunduk (serta) diliputi kehinaan. Itulah hari yang diancamkan kepada mereka."),
)

internal fun quranFullAyahs71(): List<Ayah> = listOf(
    Ayah(1, 71, "اِنَّآ اَرْسَلْنَا نُوْحًا اِلٰى قَوْمِهٖٓ اَنْ اَنْذِرْ قَوْمَكَ مِنْ قَبْلِ اَنْ يَّأْتِيَهُمْ عَذَابٌ اَلِيْمٌ", "Innā arsalnā nūḥan ilā qaumihī an anżir qaumaka min qabli ay ya'tiyahum ‘ażābun alīm(un).", "Sesungguhnya Kami telah mengutus Nuh kepada kaumnya (dengan perintah), “Berilah peringatan kepada kaummu sebelum datang azab yang pedih kepadanya!”"),
    Ayah(2, 71, "قَالَ يٰقَوْمِ اِنِّيْ لَكُمْ نَذِيْرٌ مُّبِيْنٌۙ", "Qāla yā qaumi innī lakum nażīrum mubīn(un).", "Dia (Nuh) berkata, “Wahai kaumku, sesungguhnya aku ini adalah seorang pemberi peringatan yang menjelaskan kepadamu,"),
    Ayah(3, 71, "اَنِ اعْبُدُوا اللّٰهَ وَاتَّقُوْهُ وَاَطِيْعُوْنِۙ", "Ani‘budullāha wattaqūhu wa aṭī‘ūn(i).", "(yaitu) sembahlah اللّه, bertakwalah kepada-Nya, dan taatlah kepadaku,"),
    Ayah(4, 71, "يَغْفِرْ لَكُمْ مِّنْ ذُنُوْبِكُمْ وَيُؤَخِّرْكُمْ اِلٰٓى اَجَلٍ مُّسَمًّىۗ اِنَّ اَجَلَ اللّٰهِ اِذَا جَاۤءَ لَا يُؤَخَّرُۘ لَوْ كُنْتُمْ تَعْلَمُوْنَ", "Yagfir lakum min żunūbikum wa yu'akhkhirkum ilā ajalim musammā(n), inna ajalallāhi iżā jā'a lā yu'akhkhar(u), lau kuntum ta‘lamūn(a).", "niscaya Dia akan mengampuni sebagian dosa-dosamu dan menangguhkanmu (memanjangkan umurmu) sampai pada batas waktu yang ditentukan. Sesungguhnya ketetapan اللّه itu, apabila telah datang, tidak dapat ditunda. Seandainya kamu mengetahui(-nya).”"),
    Ayah(5, 71, "قَالَ رَبِّ اِنِّيْ دَعَوْتُ قَوْمِيْ لَيْلًا وَّنَهَارًاۙ", "Qāla rabbi innī da‘atu qaumī lailaw wa nahārā(n).", "Dia (Nuh) berkata, “Ya Tuhanku, sesungguhnya aku telah menyeru kaumku siang dan malam,"),
    Ayah(6, 71, "فَلَمْ يَزِدْهُمْ دُعَاۤءِيْٓ اِلَّا فِرَارًا", "Falam yazidhum du‘ā'ī illā firārā(n).", "tetapi seruanku itu tidak menambah (iman) mereka, melainkan mereka (makin) lari (dari kebenaran)."),
    Ayah(7, 71, "وَاِنِّيْ كُلَّمَا دَعَوْتُهُمْ لِتَغْفِرَ لَهُمْ جَعَلُوْٓا اَصَابِعَهُمْ فِيْٓ اٰذَانِهِمْ وَاسْتَغْشَوْا ثِيَابَهُمْ وَاَصَرُّوْا وَاسْتَكْبَرُوا اسْتِكْبَارًاۚ", "Wa innī kullamā da‘autuhum litagfira lahum ja‘alū aṣābi‘ahum fī āżānihim wastagsyau ṡiyābahum wa aṣarrū wastakbarustikbārā(n).", "Sesungguhnya setiap kali aku menyeru mereka (untuk beriman) agar Engkau mengampuni mereka, mereka memasukkan anak jarinya ke telinganya dan menutupkan bajunya (ke wajahnya). Mereka pun tetap (mengingkari) dan sangat menyombongkan diri."),
    Ayah(8, 71, "ثُمَّ اِنِّيْ دَعَوْتُهُمْ جِهَارًاۙ", "Ṡumma innī da‘autuhum jihārā(n).", "Kemudian, sesungguhnya aku menyeru mereka dengan cara terang-terangan."),
    Ayah(9, 71, "ثُمَّ اِنِّيْٓ اَعْلَنْتُ لَهُمْ وَاَسْرَرْتُ لَهُمْ اِسْرَارًاۙ", "Ṡumma innī a‘lantu lahum wa asrartu lahum isrārā(n).", "Lalu, aku menyeru mereka secara terbuka dan diam-diam."),
    Ayah(10, 71, "فَقُلْتُ اسْتَغْفِرُوْا رَبَّكُمْ اِنَّهٗ كَانَ غَفَّارًاۙ", "Faqultustagfirū rabbakum innahū kāna gaffārā(n).", "Lalu, aku berkata (kepada mereka), “Mohonlah ampun kepada Tuhanmu. Sesungguhnya Dia Maha Pengampun."),
    Ayah(11, 71, "يُّرْسِلِ السَّمَاۤءَ عَلَيْكُمْ مِّدْرَارًاۙ", "Yursilis-samā'a ‘alaikum midrārā(n).", "(Jika kamu memohon ampun,) niscaya Dia akan menurunkan hujan yang lebat dari langit kepadamu,"),
    Ayah(12, 71, "وَّيُمْدِدْكُمْ بِاَمْوَالٍ وَّبَنِيْنَ وَيَجْعَلْ لَّكُمْ جَنّٰتٍ وَّيَجْعَلْ لَّكُمْ اَنْهٰرًاۗ", "Wa yumdidkum bi'amwāliw wa banīna wa yaj‘al lakum jannātiw wa yaj‘al lakum anhārā(n).", "memperbanyak harta dan anak-anakmu, serta mengadakan kebun-kebun dan sungai-sungai untukmu.”"),
    Ayah(13, 71, "مَا لَكُمْ لَا تَرْجُوْنَ لِلّٰهِ وَقَارًاۚ", "Mā lakum lā tarjūna lillāhi waqārā(n).", "Mengapa kamu tidak takut akan kebesaran اللّه?"),
    Ayah(14, 71, "وَقَدْ خَلَقَكُمْ اَطْوَارًا", "Wa qad khalaqakum aṭwārā(n).", "Padahal, sungguh, Dia telah menciptakanmu dalam beberapa tahapan (penciptaan)."),
    Ayah(15, 71, "اَلَمْ تَرَوْا كَيْفَ خَلَقَ اللّٰهُ سَبْعَ سَمٰوٰتٍ طِبَاقًاۙ", "Alam tara kaifa khalaqallāhu sab‘a samāwātin ṭibāqā(n).", "Tidakkah kamu memperhatikan bagaimana اللّه telah menciptakan tujuh langit berlapis-lapis?"),
    Ayah(16, 71, "وَّجَعَلَ الْقَمَرَ فِيْهِنَّ نُوْرًا وَّجَعَلَ الشَّمْسَ سِرَاجًا", "Wa ja‘alal-qamara fīhinna nūraw wa ja‘alasy-syamsa sirājā(n).", "Di sana Dia menjadikan bulan bercahaya dan matahari sebagai pelita (yang cemerlang)."),
    Ayah(17, 71, "وَاللّٰهُ اَنْۢبَتَكُمْ مِّنَ الْاَرْضِ نَبَاتًاۙ", "Wallāhu ambatakum minal-arḍi nabātā(n).", "اللّه benar-benar menciptakanmu dari tanah."),
    Ayah(18, 71, "ثُمَّ يُعِيْدُكُمْ فِيْهَا وَيُخْرِجُكُمْ اِخْرَاجًا", "Ṡumma yu‘īdukum fīhā wa yukhrijukum ikhrājā(n).", "Kemudian, dia akan mengembalikanmu ke dalamnya (tanah) dan mengeluarkanmu (pada hari Kiamat) dengan pasti."),
    Ayah(19, 71, "وَاللّٰهُ جَعَلَ لَكُمُ الْاَرْضَ بِسَاطًاۙ", "Wallāhu ja‘ala lakumul-arḍa bisāṭā(n).", "اللّه menjadikan bumi untukmu sebagai hamparan"),
    Ayah(20, 71, "لِّتَسْلُكُوْا مِنْهَا سُبُلًا فِجَاجًا ࣖ", "Litaslukū minhā subulan fijājā(n).", "agar kamu dapat pergi dengan leluasa di jalan-jalan yang luas."),
    Ayah(21, 71, "قَالَ نُوْحٌ رَّبِّ اِنَّهُمْ عَصَوْنِيْ وَاتَّبَعُوْا مَنْ لَّمْ يَزِدْهُ مَالُهٗ وَوَلَدُهٗٓ اِلَّا خَسَارًاۚ", "Qāla nūḥur rabbi innahum ‘aṣaunī wattaba‘ū mal lam yazidhu māluhū wa waladuhū illā khasārā(n).", "Nuh berkata, “Ya Tuhanku, sesungguhnya mereka durhaka kepadaku dan mengikuti orang-orang yang harta dan anak-anaknya hanya menambah kerugian baginya."),
    Ayah(22, 71, "وَمَكَرُوْا مَكْرًا كُبَّارًاۚ", "Wa makarū makran kubbārā(n).", "Mereka pun melakukan tipu daya yang sangat besar."),
    Ayah(23, 71, "وَقَالُوْا لَا تَذَرُنَّ اٰلِهَتَكُمْ وَلَا تَذَرُنَّ وَدًّا وَّلَا سُوَاعًا ەۙ وَّلَا يَغُوْثَ وَيَعُوْقَ وَنَسْرًاۚ", "Wa qālū lā tażarunna ālihatakum wa lā tażarunna waddaw wa lā suwā‘ā(n), wa lā yagūṡa wa ya‘ūqa wa nasrā(n).", "Mereka berkata, ‘Jangan sekali-kali kamu meninggalkan tuhan-tuhanmu dan jangan pula sekali-kali kamu meninggalkan Wadd, Suwā‘, Yagūṡ, Ya‘ūq, dan Nasr.’"),
    Ayah(24, 71, "وَقَدْ اَضَلُّوْا كَثِيْرًا ەۚ وَلَا تَزِدِ الظّٰلِمِيْنَ اِلَّا ضَلٰلًا", "Wa qad aḍallū kaṡīrā(n), wa lā tazidiẓ-ẓālimīna illā ḍalālā(n).", "Sungguh, mereka telah menyesatkan banyak orang. Janganlah Engkau tambahkan bagi orang-orang zalim itu selain kesesatan.”"),
    Ayah(25, 71, "مِمَّا خَطِيْۤـٰٔتِهِمْ اُغْرِقُوْا فَاُدْخِلُوْا نَارًا ەۙ فَلَمْ يَجِدُوْا لَهُمْ مِّنْ دُوْنِ اللّٰهِ اَنْصَارًا", "Mimmā khaṭī'ātihim ugriqū fa'udkhilū nārā(n), falam yajidū lahum min dūnillāhi anṣārā(n).", "Disebabkan kesalahan-kesalahan mereka, mereka ditenggelamkan, lalu dimasukkan ke neraka. Mereka tidak mendapat penolong selain اللّه."),
    Ayah(26, 71, "وَقَالَ نُوْحٌ رَّبِّ لَا تَذَرْ عَلَى الْاَرْضِ مِنَ الْكٰفِرِيْنَ دَيَّارًا", "Wa qāla nūḥur rabbi lā tażar ‘alal-arḍi minal-kāfirīna dayyārā(n).", "Nuh berkata, “Ya Tuhanku, janganlah Engkau biarkan seorang pun di antara orang-orang kafir itu tinggal di atas bumi."),
    Ayah(27, 71, "اِنَّكَ اِنْ تَذَرْهُمْ يُضِلُّوْا عِبَادَكَ وَلَا يَلِدُوْٓا اِلَّا فَاجِرًا كَفَّارًا", "Innaka in tażarhum yuḍillū ‘ibādaka wa lā yalidū illā fājiran kaffārā(n).", "Sesungguhnya jika Engkau biarkan mereka tinggal, niscaya mereka akan menyesatkan hamba-hamba-Mu. Mereka pun hanya akan melahirkan anak-anak yang jahat dan tidak tahu bersyukur."),
    Ayah(28, 71, "رَبِّ اغْفِرْ لِيْ وَلِوَالِدَيَّ وَلِمَنْ دَخَلَ بَيْتِيَ مُؤْمِنًا وَّلِلْمُؤْمِنِيْنَ وَالْمُؤْمِنٰتِۗ وَلَا تَزِدِ الظّٰلِمِيْنَ اِلَّا تَبَارًا ࣖ", "Rabbigfir lī wa liwālidayya wa liman dakhala baitiya mu'minaw wa lil-mu'minīna wal-mu'mināt(i), wa lā tazidiẓ-ẓālimīna illā tabārā(n).", "Ya Tuhanku, ampunilah aku, ibu bapakku, dan siapa pun yang memasuki rumahku dengan beriman dan semua orang yang beriman laki-laki dan perempuan. Janganlah Engkau tambahkan bagi orang-orang zalim itu selain kehancuran.”"),
)

internal fun quranFullAyahs72(): List<Ayah> = listOf(
    Ayah(1, 72, "قُلْ اُوْحِيَ اِلَيَّ اَنَّهُ اسْتَمَعَ نَفَرٌ مِّنَ الْجِنِّ فَقَالُوْٓا اِنَّا سَمِعْنَا قُرْاٰنًا عَجَبًاۙ", "Qul ūḥiya ilayya annahustama‘a nafarum minal-jinni fa qālū innā sami‘nā qur'ānan ‘ajabā(n).", "Katakanlah (Nabi Muhammad), “Telah diwahyukan kepadaku bahwa sekumpulan jin telah mendengarkan (Al-Qur’an yang kubaca).” Lalu, mereka berkata, “Kami telah mendengarkan bacaan yang menakjubkan,"),
    Ayah(2, 72, "يَّهْدِيْٓ اِلَى الرُّشْدِ فَاٰمَنَّا بِهٖۗ وَلَنْ نُّشْرِكَ بِرَبِّنَآ اَحَدًاۖ", "Yahdī ilar-rusydi fa'āmannā bih(ī), wa lan nusyrika birabbinā aḥadā(n).", "yang memberi petunjuk pada kebenaran, sehingga kami pun beriman padanya dan tidak akan mempersekutukan sesuatu pun dengan Tuhan kami."),
    Ayah(3, 72, "وَّاَنَّهٗ تَعٰلٰى جَدُّ رَبِّنَا مَا اتَّخَذَ صَاحِبَةً وَّلَا وَلَدًاۖ", "Wa annahū ta‘ālā jaddu rabbinā mattakhaża ṣāḥibataw wa lā waladā(n).", "Sesungguhnya Mahatinggi keagungan Tuhan kami. Dia tidak beristri dan tidak (pula) beranak."),
    Ayah(4, 72, "وَّاَنَّهٗ كَانَ يَقُوْلُ سَفِيْهُنَا عَلَى اللّٰهِ شَطَطًاۖ", "Wa annahū kāna yaqūlu safīhunā ‘alallāhi syaṭaṭā(n).", "Sesungguhnya orang yang bodoh di antara kami selalu mengucapkan (perkataan) yang melampaui batas terhadap اللّه."),
    Ayah(5, 72, "وَّاَنَّا ظَنَنَّآ اَنْ لَّنْ تَقُوْلَ الْاِنْسُ وَالْجِنُّ عَلَى اللّٰهِ كَذِبًاۙ", "Wa annā ẓanannā allan taqūlal-insu wal-jinnu ‘alallāhi każibā(n).", "Sesungguhnya kami mengira bahwa manusia dan jin itu tidak akan mengatakan perkataan yang dusta terhadap اللّه.”"),
    Ayah(6, 72, "وَّاَنَّهٗ كَانَ رِجَالٌ مِّنَ الْاِنْسِ يَعُوْذُوْنَ بِرِجَالٍ مِّنَ الْجِنِّ فَزَادُوْهُمْ رَهَقًاۖ", "Wa annahū kāna rijālum minal insi ya‘ūżūna birijālim minal-jinni fa zādūhum rahaqā(n).", "Sesungguhnya ada beberapa orang laki-laki dari (kalangan) manusia yang meminta perlindungan kepada beberapa laki-laki dari (kalangan) jin sehingga mereka (jin) menjadikan mereka (manusia) bertambah sesat."),
    Ayah(7, 72, "وَّاَنَّهُمْ ظَنُّوْا كَمَا ظَنَنْتُمْ اَنْ لَّنْ يَّبْعَثَ اللّٰهُ اَحَدًاۖ", "Wa annahum ẓannū kamā ẓanantum allay yab‘aṡallāhu aḥadā(n).", "Sesungguhnya mereka (jin) mengira sebagaimana kamu (orang musyrik Makkah) mengira bahwa اللّه tidak akan membangkitkan kembali siapa pun (pada hari Kiamat)."),
    Ayah(8, 72, "وَّاَنَّا لَمَسْنَا السَّمَاۤءَ فَوَجَدْنٰهَا مُلِئَتْ حَرَسًا شَدِيْدًا وَّشُهُبًاۖ", "Wa annā lamasnas-samā'a fa wajadnāhā muli'at ḥarasan syadīdaw wa syuhubā(n).", "(Jin berkata lagi,) “Sesungguhnya kami (jin) telah mencoba mengetahui (rahasia) langit. Maka, kami mendapatinya penuh dengan penjagaan yang kuat dan panah-panah api."),
    Ayah(9, 72, "وَّاَنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَاعِدَ لِلسَّمْعِۗ فَمَنْ يَّسْتَمِعِ الْاٰنَ يَجِدْ لَهٗ شِهَابًا رَّصَدًاۖ", "Wa annā kunnā naq‘udu minhā maqā‘ida lis-sam‘(i), famay yastami‘il-āna yajid lahū syihābar raṣadā(n).", "Sesungguhnya kami (jin) dahulu selalu menduduki beberapa tempat (di langit) untuk mencuri dengar (berita-beritanya). Akan tetapi, sekarang siapa yang (mencoba) mencuri dengar pasti akan menjumpai panah api yang mengintai (untuk membakarnya)."),
    Ayah(10, 72, "وَّاَنَّا لَا نَدْرِيْٓ اَشَرٌّ اُرِيْدَ بِمَنْ فِى الْاَرْضِ اَمْ اَرَادَ بِهِمْ رَبُّهُمْ رَشَدًاۙ", "Wa annā lā nadrī asyarrun urīda biman fil-arḍi am arāda bihim rabbuhum rasyadā(n).", "Sesungguhnya kami tidak mengetahui apakah keburukan yang dikehendaki terhadap siapa yang di bumi ataukah Tuhan mereka menghendaki kebaikan terhadap mereka."),
    Ayah(11, 72, "وَّاَنَّا مِنَّا الصّٰلِحُوْنَ وَمِنَّا دُوْنَ ذٰلِكَۗ كُنَّا طَرَاۤىِٕقَ قِدَدًاۙ", "Wa annā minnaṣ-ṣāliḥūna wa minnā dūna żālik(a), kunnā ṭarā'iqa qidadā(n).", "Sesungguhnya di antara kami ada yang saleh dan di antara kami ada (pula) yang tidak demikian halnya. Kami menempuh jalan yang berbeda-beda."),
    Ayah(12, 72, "وَّاَنَّا ظَنَنَّآ اَنْ لَّنْ نُّعْجِزَ اللّٰهَ فِى الْاَرْضِ وَلَنْ نُّعْجِزَهٗ هَرَبًاۖ", "Wa annā ẓanannā allan nu‘jizallāha fil-arḍi wa lan nu‘jizahū harabā(n).", "Sesungguhnya kami yakin bahwa kami tidak akan mampu melepaskan diri (dari kekuasaan) اللّه di bumi dan tidak (pula) dapat lari melepaskan diri (dari)-Nya."),
    Ayah(13, 72, "وَّاَنَّا لَمَّا سَمِعْنَا الْهُدٰىٓ اٰمَنَّا بِهٖۗ فَمَنْ يُّؤْمِنْۢ بِرَبِّهٖ فَلَا يَخَافُ بَخْسًا وَّلَا رَهَقًاۖ", "Wa annā lammā sami‘nal-hudā āmannā bih(ī), famay yu'mim birabbihī falā yakhāfu bakhsaw wa lā rahaqā(n).", "Sesungguhnya ketika mendengar petunjuk (Al-Qur’an), kami pun beriman kepadanya. Maka, siapa yang beriman kepada Tuhannya tidak (perlu) takut akan pengurangan (pahala amalnya) dan tidak (takut pula) akan kesulitan (akibat penambahan dosa)."),
    Ayah(14, 72, "وَّاَنَّا مِنَّا الْمُسْلِمُوْنَ وَمِنَّا الْقٰسِطُوْنَۗ فَمَنْ اَسْلَمَ فَاُولٰۤىِٕكَ تَحَرَّوْا رَشَدًا", "Wa annā minnal-muslimūna wa minnal-qāsiṭūn(a), faman aslama fa ulā'ika taḥarrau rasyadā(n).", "Sesungguhnya di antara kami ada yang muslim dan ada (pula) yang menyimpang dari kebenaran. Siapa yang (memeluk) Islam telah memilih jalan yang benar."),
    Ayah(15, 72, "وَاَمَّا الْقٰسِطُوْنَ فَكَانُوْا لِجَهَنَّمَ حَطَبًاۙ", "Wa ammal-qāsiṭūna fa kānū lijahannama ḥaṭabā(n).", "Adapun para penyimpang dari kebenaran menjadi bahan bakar (neraka) Jahanam.”"),
    Ayah(16, 72, "وَّاَنْ لَّوِ اسْتَقَامُوْا عَلَى الطَّرِيْقَةِ لَاَسْقَيْنٰهُمْ مَّاۤءً غَدَقًاۙ", "Wa allawistaqāmū ‘alaṭ-ṭarīqati la'asqaināhum mā'an gadaqā(n).", "Seandainya mereka tetap berjalan lurus di atas jalan itu (agama Islam), niscaya Kami akan mencurahkan air yang banyak (rezeki yang cukup)."),
    Ayah(17, 72, "لِّنَفْتِنَهُمْ فِيْهِۗ وَمَنْ يُّعْرِضْ عَنْ ذِكْرِ رَبِّهٖ يَسْلُكْهُ عَذَابًا صَعَدًاۙ", "Linaftinahum fīh(i), wa may yu‘riḍ ‘an żikri rabbihī yasluk-hu ‘ażāban ṣa‘adā(n).", "Dengan (cara) itu Kami hendak menguji mereka. Siapa yang berpaling dari peringatan Tuhannya niscaya akan dimasukkan-Nya ke dalam azab yang sangat berat."),
    Ayah(18, 72, "وَّاَنَّ الْمَسٰجِدَ لِلّٰهِ فَلَا تَدْعُوْا مَعَ اللّٰهِ اَحَدًاۖ", "Wa annal-masājida lillāhi falā tad‘ū ma‘allāhi aḥadā(n).", "Sesungguhnya masjid-masjid itu milik اللّه. Maka, janganlah menyembah apa pun bersamaan dengan (menyembah) اللّه."),
    Ayah(19, 72, "وَّاَنَّهٗ لَمَّا قَامَ عَبْدُ اللّٰهِ يَدْعُوْهُ كَادُوْا يَكُوْنُوْنَ عَلَيْهِ لِبَدًاۗ ࣖ", "Wa annahū lammā qāma ‘abdullāhi yad‘ūhu kādū yakūnūna ‘alaihi libadā(n).", "Sesungguhnya ketika hamba اللّه (Nabi Muhammad) berdiri menyembah-Nya (melaksanakan salat), mereka (jin-jin) itu berdesakan mengerumuninya."),
    Ayah(20, 72, "قُلْ اِنَّمَآ اَدْعُوْا رَبِّيْ وَلَآ اُشْرِكُ بِهٖٓ اَحَدًا", "Qul innamā ad‘ū rabbī wa lā usyriku bihī aḥadā(n).", "Katakanlah (Nabi Muhammad), “Sesungguhnya aku hanya menyembah Tuhanku dan aku tidak mempersekutukan-Nya dengan apa pun.”"),
    Ayah(21, 72, "قُلْ اِنِّيْ لَآ اَمْلِكُ لَكُمْ ضَرًّا وَّلَا رَشَدًا", "Qul innī lā amliku lakum ḍarraw wa lā rasyadā(n).", "Katakanlah, “Sesungguhnya aku tidak mampu (menolak) mudarat dan tidak (pula mampu mendatangkan) kebaikan kepadamu.”"),
    Ayah(22, 72, "قُلْ اِنِّيْ لَنْ يُّجِيْرَنِيْ مِنَ اللّٰهِ اَحَدٌ ەۙ وَّلَنْ اَجِدَ مِنْ دُوْنِهٖ مُلْتَحَدًا ۙ", "Qul innī lay yujīranī minallāhi aḥad(un), wa lan ajida min dūnihī multaḥadā(n).", "Katakanlah, “Sesungguhnya tidak ada seorang pun yang dapat melindungiku dari (azab) اللّه dan aku tidak akan memperoleh tempat berlindung selain-Nya."),
    Ayah(23, 72, "اِلَّا بَلٰغًا مِّنَ اللّٰهِ وَرِسٰلٰتِهٖۗ وَمَنْ يَّعْصِ اللّٰهَ وَرَسُوْلَهٗ فَاِنَّ لَهٗ نَارَ جَهَنَّمَ خٰلِدِيْنَ فِيْهَآ اَبَدًاۗ", "Illā balāgam minallāhi wa risālātih(ī), wa may ya‘ṣillāha wa rasūlahū fa inna lahū nāra jahannama khālidīna fīhā abadā(n).", "(Yang aku mampu lakukan) hanyalah menyampaikan (peringatan) dari اللّه dan risalah-Nya. Siapa yang mendurhakai اللّه dan Rasul-Nya sesungguhnya akan mendapat (azab) neraka Jahanam. Mereka kekal di dalamnya selama-lamanya.”"),
    Ayah(24, 72, "حَتّٰىٓ اِذَا رَاَوْا مَا يُوْعَدُوْنَ فَسَيَعْلَمُوْنَ مَنْ اَضْعَفُ نَاصِرًا وَّاَقَلُّ عَدَدًاۗ", "Ḥattā iżā ra'au mā yū‘adūna fasaya‘lamūna man aḍ‘afu nāṣiraw wa aqallu ‘adadā(n).", "Dengan demikian, apabila melihat (azab) yang diancamkan kepadanya, mereka akan mengetahui siapakah yang lebih lemah penolongnya dan lebih sedikit jumlahnya."),
    Ayah(25, 72, "قُلْ اِنْ اَدْرِيْٓ اَقَرِيْبٌ مَّا تُوْعَدُوْنَ اَمْ يَجْعَلُ لَهٗ رَبِّيْٓ اَمَدًا", "Qul in adrī aqarībum mā tū‘adūna am yaj‘alu lahū rabbī amadā(n).", "Katakanlah (Nabi Muhammad), “Aku tidak mengetahui apakah (azab) yang diancamkan kepadamu itu sudah dekat atau Tuhanku menjadikan waktunya masih lama.”"),
    Ayah(26, 72, "عٰلِمُ الْغَيْبِ فَلَا يُظْهِرُ عَلٰى غَيْبِهٖٓ اَحَدًاۙ", "‘Ālimul-gaibi falā yuẓhiru ‘alā gaibihī aḥadā(n).", "Dia mengetahui yang gaib. Lalu, Dia tidak memperlihatkan yang gaib itu kepada siapa pun,"),
    Ayah(27, 72, "اِلَّا مَنِ ارْتَضٰى مِنْ رَّسُوْلٍ فَاِنَّهٗ يَسْلُكُ مِنْۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهٖ رَصَدًاۙ", "Illā manirtaḍā mir rasūlin fa innahū yasluku mim baini yadaihi wa min khalfihī raṣadā(n).", "kecuali kepada rasul yang diridai-Nya. Sesungguhnya Dia menempatkan penjaga-penjaga (malaikat) di depan dan di belakangnya."),
    Ayah(28, 72, "لِّيَعْلَمَ اَنْ قَدْ اَبْلَغُوْا رِسٰلٰتِ رَبِّهِمْ وَاَحَاطَ بِمَا لَدَيْهِمْ وَاَحْصٰى كُلَّ شَيْءٍ عَدَدًا ࣖ", "Liya‘lama an qad ablagū risālāti rabbihim wa aḥāṭa bimā ladaihim wa aḥṣā kulla syai'in ‘adadā(n).", "(Yang demikian itu) agar Dia mengetahui bahwa (rasul-rasul itu) benar-benar telah menyampaikan risalah-risalah Tuhannya, sedangkan (ilmu-Nya) meliputi apa yang ada pada mereka. Dia menghitung segala sesuatu satu per satu."),
)

internal fun quranFullAyahs73(): List<Ayah> = listOf(
    Ayah(1, 73, "يٰٓاَيُّهَا الْمُزَّمِّلُۙ", "Yā ayyuhal-muzzammil(u).", "Wahai orang yang berkelumun (Nabi Muhammad),"),
    Ayah(2, 73, "قُمِ الَّيْلَ اِلَّا قَلِيْلًاۙ", "Qumil-laila illā qalīlā(n).", "bangunlah (untuk salat) pada malam hari, kecuali sebagian kecil,"),
    Ayah(3, 73, "نِّصْفَهٗٓ اَوِ انْقُصْ مِنْهُ قَلِيْلًاۙ", "Niṣfahū awinquṣ minhu qalīlā(n).", "(yaitu) seperduanya, kurang sedikit dari itu,"),
    Ayah(4, 73, "اَوْ زِدْ عَلَيْهِ وَرَتِّلِ الْقُرْاٰنَ تَرْتِيْلًاۗ", "Au zid ‘alaihi wa rattilil-qur'āna tartīlā(n).", "atau lebih dari (seperdua) itu. Bacalah Al-Qur’an itu dengan perlahan-lahan."),
    Ayah(5, 73, "اِنَّا سَنُلْقِيْ عَلَيْكَ قَوْلًا ثَقِيْلًا", "Innā sanulqī ‘alaika qaulan ṡaqīlā(n).", "Sesungguhnya Kami akan menurunkan perkataan yang berat kepadamu."),
    Ayah(6, 73, "اِنَّ نَاشِئَةَ الَّيْلِ هِيَ اَشَدُّ وَطْـًٔا وَّاَقْوَمُ قِيْلًاۗ", "Inna nāsyi'atal-laili hiya asyaddu waṭ'aw wa aqwamu qīlā(n).", "Sesungguhnya bangun malam itu lebih kuat (pengaruhnya terhadap jiwa) dan lebih mantap ucapannya."),
    Ayah(7, 73, "اِنَّ لَكَ فِى النَّهَارِ سَبْحًا طَوِيْلًاۗ", "Inna laka fin-nahāri sabḥan ṭawīlā(n).", "Sesungguhnya pada siang hari engkau memiliki kesibukan yang panjang."),
    Ayah(8, 73, "وَاذْكُرِ اسْمَ رَبِّكَ وَتَبَتَّلْ اِلَيْهِ تَبْتِيْلًاۗ", "Ważkurisma rabbika wa tabattal ilaihi tabtīlā(n).", "Sebutlah nama Tuhanmu dan beribadahlah kepada-Nya dengan sepenuh hati."),
    Ayah(9, 73, "رَبُّ الْمَشْرِقِ وَالْمَغْرِبِ لَآ اِلٰهَ اِلَّا هُوَ فَاتَّخِذْهُ وَكِيْلًا", "Rabbul-masyriqi wal-magribi lā ilāha illā huwa fattakhiżhu wakīlā(n).", "(اللّه) adalah Tuhan timur dan barat. Tidak ada tuhan selain Dia. Maka, jadikanlah Dia sebagai pelindung."),
    Ayah(10, 73, "وَاصْبِرْ عَلٰى مَا يَقُوْلُوْنَ وَاهْجُرْهُمْ هَجْرًا جَمِيْلًا", "Waṣbir ‘alā mā yaqūlūna wahjurhum hajran jamīlā(n).", "Bersabarlah (Nabi Muhammad) terhadap apa yang mereka katakan dan tinggalkanlah mereka dengan cara yang baik."),
    Ayah(11, 73, "وَذَرْنِيْ وَالْمُكَذِّبِيْنَ اُولِى النَّعْمَةِ وَمَهِّلْهُمْ قَلِيْلًا", "Wa żarnī wal-mukażżibīna ulin-na‘mati wa mahhilhum qalīlā(n).", "Biarkanlah Aku (yang bertindak) terhadap para pendusta yang memiliki segala kenikmatan hidup dan berilah mereka penangguhan sementara."),
    Ayah(12, 73, "اِنَّ لَدَيْنَآ اَنْكَالًا وَّجَحِيْمًاۙ", "Inna ladainā ankālaw wa jaḥīmā(n).", "Sesungguhnya di sisi Kami ada belenggu-belenggu (yang berat), (neraka) Jahim,"),
    Ayah(13, 73, "وَّطَعَامًا ذَا غُصَّةٍ وَّعَذَابًا اَلِيْمًا", "Wa ṭa‘āman żā guṣṣatiw wa ‘ażāban alīmā(n).", "makanan yang menyumbat kerongkongan, dan azab yang pedih."),
    Ayah(14, 73, "يَوْمَ تَرْجُفُ الْاَرْضُ وَالْجِبَالُ وَكَانَتِ الْجِبَالُ كَثِيْبًا مَّهِيْلًا", "Yauma tarjuful-arḍu wal-jibālu wa kānatil-jibālu kaṡībam mahīlā(n).", "(Ingatlah) pada hari (ketika) bumi dan gunung-gunung berguncang keras dan gunung-gunung itu menjadi seperti onggokan pasir yang tercurah."),
    Ayah(15, 73, "اِنَّآ اَرْسَلْنَآ اِلَيْكُمْ رَسُوْلًا ەۙ شَاهِدًا عَلَيْكُمْ كَمَآ اَرْسَلْنَآ اِلٰى فِرْعَوْنَ رَسُوْلًا ۗ", "Innā arsalnā ilaikum rasūlā(n), syāhidan ‘alaikum kamā arsalnā ilā fir‘auna rasūlā(n).", "Sesungguhnya Kami telah mengutus seorang rasul (Nabi Muhammad) kepadamu sebagai saksi atasmu, sebagaimana Kami telah mengutus seorang rasul kepada Fir‘aun."),
    Ayah(16, 73, "فَعَصٰى فِرْعَوْنُ الرَّسُوْلَ فَاَخَذْنٰهُ اَخْذًا وَّبِيْلًاۚ", "Fa ‘aṣā fir‘aunar-rasūla fa akhażnāhu akhżaw wabīlā(n).", "Namun, Fir‘aun mendurhakai rasul itu sehingga Kami siksa dia dengan siksaan yang berat."),
    Ayah(17, 73, "فَكَيْفَ تَتَّقُوْنَ اِنْ كَفَرْتُمْ يَوْمًا يَّجْعَلُ الْوِلْدَانَ شِيْبًاۖ", "Fakaifa tattaqūna in kafartum yaumay yaj‘alul-wildāna syībā(n).", "Lalu, bagaimanakah kamu akan dapat menjaga dirimu (dari azab) hari yang menjadikan anak-anak beruban jika kamu tetap kufur?"),
    Ayah(18, 73, "ۨالسَّمَاۤءُ مُنْفَطِرٌۢ بِهٖۗ كَانَ وَعْدُهٗ مَفْعُوْلًا", "As-samā'u munfaṭirum bih(ī), kāna wa‘duhū maf‘ūlā(n).", "Langit terbelah padanya (hari itu). Janji-Nya pasti terlaksana."),
    Ayah(19, 73, "اِنَّ هٰذِهٖ تَذْكِرَةٌ ۚ فَمَنْ شَاۤءَ اتَّخَذَ اِلٰى رَبِّهٖ سَبِيْلًا ࣖ", "Inna hāżihī tażkirah(tun), faman syā'attakhaża ilā rabbihī sabīlā(n).", "Sesungguhnya ini adalah peringatan. Siapa yang berkehendak niscaya mengambil jalan (yang lurus) kepada Tuhannya."),
    Ayah(20, 73, "۞ اِنَّ رَبَّكَ يَعْلَمُ اَنَّكَ تَقُوْمُ اَدْنٰى مِنْ ثُلُثَيِ الَّيْلِ وَنِصْفَهٗ وَثُلُثَهٗ وَطَاۤىِٕفَةٌ مِّنَ الَّذِيْنَ مَعَكَۗ وَاللّٰهُ يُقَدِّرُ الَّيْلَ وَالنَّهَارَۗ عَلِمَ اَنْ لَّنْ تُحْصُوْهُ فَتَابَ عَلَيْكُمْ فَاقْرَءُوْا مَا تَيَسَّرَ مِنَ الْقُرْاٰنِۗ عَلِمَ اَنْ سَيَكُوْنُ مِنْكُمْ مَّرْضٰىۙ وَاٰخَرُوْنَ يَضْرِبُوْنَ فِى الْاَرْضِ يَبْتَغُوْنَ مِنْ فَضْلِ اللّٰهِ ۙوَاٰخَرُوْنَ يُقَاتِلُوْنَ فِيْ سَبِيْلِ اللّٰهِ ۖفَاقْرَءُوْا مَا تَيَسَّرَ مِنْهُۙ وَاَقِيْمُوا الصَّلٰوةَ وَاٰتُوا الزَّكٰوةَ وَاَقْرِضُوا اللّٰهَ قَرْضًا حَسَنًاۗ وَمَا تُقَدِّمُوْا لِاَنْفُسِكُمْ مِّنْ خَيْرٍ تَجِدُوْهُ عِنْدَ اللّٰهِ ۙهُوَ خَيْرًا وَّاَعْظَمَ اَجْرًاۗ وَاسْتَغْفِرُوا اللّٰهَ ۗاِنَّ اللّٰهَ غَفُوْرٌ رَّحِيْمٌ ࣖ", "Inna rabbaka ya‘lamu annaka taqūmu adnā min ṡuluṡayil-laili wa niṣfahū wa ṡuluṡahū wa ṭā'ifatum minal-lażīna ma‘ak(a), wallāhu yuqaddirul-laila wan-nahār(a), ‘alima allan tuḥṣūhu fa tāba ‘alaikum faqra'ū mā tayassara minal-qur'ān(i), ‘alima an sayakūnu minkum marḍā, wa ākharūna yaḍribūna fil-arḍi yabtagūna min faḍlillāh(i), wa ākharūna yuqātilūna fī sabīlillāh(i), faqra'ū mā tayassara minh(u), wa aqīmuṣ-ṣalāta wa ātuz-zakāta wa aqriḍullāha qarḍan ḥasanā(n), wa mā tuqaddimū li'anfusikum min khairin tajidūhu ‘indallāh(i), huwa khairaw wa a‘ẓama ajrā(n), wastagfirullāh(a), innallāha gafūrur raḥīm(un).", "Sesungguhnya Tuhanmu mengetahui bahwa engkau (Nabi Muhammad) berdiri (salat) kurang dari dua pertiga malam, atau seperdua malam atau sepertiganya dan (demikian pula) segolongan dari orang-orang yang bersamamu. اللّه menetapkan ukuran malam dan siang. اللّه mengetahui bahwa kamu tidak dapat menghitungnya (secara terperinci waktu-waktu tersebut sehingga menyulitkanmu dalam melaksanakan salat malam). Maka, Dia kembali (memberi keringanan) kepadamu. Oleh karena itu, bacalah (ayat) Al-Qur’an yang mudah (bagimu). Dia mengetahui bahwa akan ada di antara kamu orang-orang yang sakit, dan yang lain berjalan di bumi mencari sebagian karunia اللّه serta yang lain berperang di jalan اللّه, maka bacalah apa yang mudah (bagimu) darinya (Al-Qur’an). Tegakkanlah salat, tunaikanlah zakat, dan berikanlah pinjaman kepada اللّه pinjaman yang baik. Kebaikan apa saja yang kamu perbuat untuk dirimu niscaya kamu memperoleh (balasan)-nya di sisi اللّه sebagai balasan yang paling baik dan yang paling besar pahalanya. Mohonlah ampunan kepada اللّه. Sesungguhnya اللّه Maha Pengampun lagi Maha Penyayang."),
)

internal fun quranFullAyahs74(): List<Ayah> = listOf(
    Ayah(1, 74, "يٰٓاَيُّهَا الْمُدَّثِّرُۙ", "Yā ayyuhal-muddaṡṡir(u).", "Wahai orang yang berselimut (Nabi Muhammad),"),
    Ayah(2, 74, "قُمْ فَاَنْذِرْۖ", "Qum fa'anżir.", "bangunlah, lalu berilah peringatan!"),
    Ayah(3, 74, "وَرَبَّكَ فَكَبِّرْۖ", "Wa rabbaka fakabbir.", "Tuhanmu, agungkanlah!"),
    Ayah(4, 74, "وَثِيَابَكَ فَطَهِّرْۖ", "Wa ṡiyābaka faṭahhir.", "Pakaianmu, bersihkanlah!"),
    Ayah(5, 74, "وَالرُّجْزَ فَاهْجُرْۖ", "War-rujza fahjur.", "Segala (perbuatan) yang keji, tinggalkanlah!"),
    Ayah(6, 74, "وَلَا تَمْنُنْ تَسْتَكْثِرُۖ", "Wa lā tamnun tastakṡir(u).", "Janganlah memberi (dengan maksud) memperoleh (balasan) yang lebih banyak!"),
    Ayah(7, 74, "وَلِرَبِّكَ فَاصْبِرْۗ", "Wa lirabbika faṣbir.", "Karena Tuhanmu, bersabarlah!"),
    Ayah(8, 74, "فَاِذَا نُقِرَ فِى النَّاقُوْرِۙ", "Fa iżā nuqira fin-nāqūr(i).", "Apabila sangkakala ditiup,"),
    Ayah(9, 74, "فَذٰلِكَ يَوْمَىِٕذٍ يَّوْمٌ عَسِيْرٌۙ", "Fa żālika yauma'iżiy yaumun ‘asīr(un).", "hari itulah hari yang sulit,"),
    Ayah(10, 74, "عَلَى الْكٰفِرِيْنَ غَيْرُ يَسِيْرٍ", "‘Alal-kāfirīna gairu yasīr(in).", "(yang) tidak mudah bagi orang-orang kafir."),
    Ayah(11, 74, "ذَرْنِيْ وَمَنْ خَلَقْتُ وَحِيْدًاۙ", "Żarnī wa man khalaqtu waḥīdā(n).", "Biarkanlah Aku (yang bertindak) terhadap orang yang Aku ciptakan dia dalam kesendirian."),
    Ayah(12, 74, "وَّجَعَلْتُ لَهٗ مَالًا مَّمْدُوْدًاۙ", "Wa ja‘altu lahū mālam mamdūdā(n).", "Aku beri dia kekayaan yang berlimpah,"),
    Ayah(13, 74, "وَّبَنِيْنَ شُهُوْدًاۙ", "Wa banīna syuhūdā(n).", "anak-anak yang selalu bersamanya,"),
    Ayah(14, 74, "وَّمَهَّدْتُّ لَهٗ تَمْهِيْدًاۙ", "Wa mahhattu lahū tamhīdā(n).", "dan Aku beri dia kelapangan (hidup) seluas-luasnya."),
    Ayah(15, 74, "ثُمَّ يَطْمَعُ اَنْ اَزِيْدَۙ", "Ṡumma yaṭma‘u an azīd(a).", "Kemudian, dia ingin sekali agar Aku menambahnya."),
    Ayah(16, 74, "كَلَّاۗ اِنَّهٗ كَانَ لِاٰيٰتِنَا عَنِيْدًاۗ", "Kallā, innahū kāna li'āyātinā ‘anīdā(n).", "Sekali-kali tidak! Sesungguhnya dia telah menentang ayat-ayat Kami (Al-Qur’an)."),
    Ayah(17, 74, "سَاُرْهِقُهٗ صَعُوْدًاۗ", "Sa'urhiquhū ṣa‘ūdā(n).", "Aku akan membebaninya dengan pendakian yang memayahkan."),
    Ayah(18, 74, "اِنَّهٗ فَكَّرَ وَقَدَّرَۙ", "Innahū fakkara wa qaddar(a).", "Sesungguhnya dia telah memikirkan dan menetapkan (apa yang ditetapkannya)."),
    Ayah(19, 74, "فَقُتِلَ كَيْفَ قَدَّرَۙ", "Faqutila kaifa qaddar(a).", "Maka, binasalah dia. Bagaimanakah dia menetapkan?"),
    Ayah(20, 74, "ثُمَّ قُتِلَ كَيْفَ قَدَّرَۙ", "Ṡumma qutila kaifa qaddar(a).", "Kemudian, binasalah dia. Bagaimanakah dia menetapkan?"),
    Ayah(21, 74, "ثُمَّ نَظَرَۙ", "Ṡumma naẓar(a).", "Kemudian dia memikirkan (untuk melecehkan Al-Qur’an)."),
    Ayah(22, 74, "ثُمَّ عَبَسَ وَبَسَرَۙ", "Ṡumma ‘abasa wa basar(a).", "Kemudian, dia berwajah masam dan cemberut (karena tidak menemukan kelemahan Al-Qur’an)."),
    Ayah(23, 74, "ثُمَّ اَدْبَرَ وَاسْتَكْبَرَۙ", "Ṡumma adbara wastakbar(a).", "Kemudian, dia berpaling (dari kebenaran) dan menyombongkan diri."),
    Ayah(24, 74, "فَقَالَ اِنْ هٰذَآ اِلَّا سِحْرٌ يُّؤْثَرُۙ", "Faqāla in hāżā illā siḥruy yu'ṡar(u).", "Lalu, dia berkata, “(Al-Qur’an) ini tidak lain, kecuali sihir yang dipelajari (dari orang-orang terdahulu)."),
    Ayah(25, 74, "اِنْ هٰذَآ اِلَّا قَوْلُ الْبَشَرِۗ", "In hāżā illā qaulul-basyar(i).", "Ini tidak lain kecuali perkataan manusia.”"),
    Ayah(26, 74, "سَاُصْلِيْهِ سَقَرَ", "Sa'uṣlīhi saqar(a).", "Aku akan memasukkannya ke dalam (neraka) Saqar."),
    Ayah(27, 74, "وَمَآ اَدْرٰىكَ مَا سَقَرُۗ", "Wa mā adrāka mā saqar(a).", "Tahukah kamu apa (neraka) Saqar itu?"),
    Ayah(28, 74, "لَا تُبْقِيْ وَلَا تَذَرُۚ", "Lā tubqī wa lā tażar(u).", "(Neraka Saqar itu) tidak meninggalkan (sedikit pun bagian jasmani) dan tidak membiarkan(-nya luput dari siksaan)."),
    Ayah(29, 74, "لَوَّاحَةٌ لِّلْبَشَرِۚ", "Lawwāḥatul lil-basyar(i).", "(Neraka Saqar itu) menghanguskan kulit manusia."),
    Ayah(30, 74, "عَلَيْهَا تِسْعَةَ عَشَرَۗ", "‘Alaihā tis‘ata ‘asyar(a).", "Di atasnya ada sembilan belas (malaikat penjaga)."),
    Ayah(31, 74, "وَمَا جَعَلْنَآ اَصْحٰبَ النَّارِ اِلَّا مَلٰۤىِٕكَةً ۖوَّمَا جَعَلْنَا عِدَّتَهُمْ اِلَّا فِتْنَةً لِّلَّذِيْنَ كَفَرُوْاۙ لِيَسْتَيْقِنَ الَّذِيْنَ اُوْتُوا الْكِتٰبَ وَيَزْدَادَ الَّذِيْنَ اٰمَنُوْٓا اِيْمَانًا وَّلَا يَرْتَابَ الَّذِيْنَ اُوْتُوا الْكِتٰبَ وَالْمُؤْمِنُوْنَۙ وَلِيَقُوْلَ الَّذِيْنَ فِيْ قُلُوْبِهِمْ مَّرَضٌ وَّالْكٰفِرُوْنَ مَاذَآ اَرَادَ اللّٰهُ بِهٰذَا مَثَلًاۗ كَذٰلِكَ يُضِلُّ اللّٰهُ مَنْ يَّشَاۤءُ وَيَهْدِيْ مَنْ يَّشَاۤءُۗ وَمَا يَعْلَمُ جُنُوْدَ رَبِّكَ اِلَّا هُوَۗ وَمَا هِيَ اِلَّا ذِكْرٰى لِلْبَشَرِ ࣖ", "Wa mā ja‘alnā aṣḥāban-nāri illā malā'ikah(tan), wa mā ja‘alnā ‘iddatahum illā fitnatal lil-lażīna kafarū, liyastaiqinal-lażīna ūtul-kitāba wa yazdādal-lażīna āmanū īmānaw wa lā yartābal-lażīna ūtul-kitāba wal-mu'minūn(a), wa liyaqūlal-lażīna fī qulūbihim maraḍuw wal-kāfirūna māżā arādallāhu bihāżā maṡalā(n), każālika yuḍillullāhu may yasyā'u wa yahdī may yasyā'(u), wa mā ya‘lamu junūda rabbika illā huw(a), wa mā hiya illā żikrā lil-basyar(i).", "Kami tidak menjadikan para penjaga neraka, kecuali para malaikat dan Kami tidak menentukan bilangan mereka itu, kecuali sebagai cobaan bagi orang-orang kafir. (Yang demikian itu) agar orang-orang yang diberi kitab menjadi yakin, orang yang beriman bertambah imannya, orang-orang yang diberi kitab dan orang-orang mukmin itu tidak ragu-ragu, serta orang-orang yang di dalam hatinya ada penyakit dan orang-orang kafir (berkata,) “Apakah yang dikehendaki اللّه dengan (bilangan) ini sebagai suatu perumpamaan?” Demikianlah اللّه membiarkan sesat orang-orang yang Dia kehendaki (berdasarkan kecenderungan dan pilihan mereka sendiri) dan memberi petunjuk kepada orang-orang yang Dia kehendaki (berdasarkan kesiapan mereka untuk menerima petunjuk). Tidak ada yang mengetahui bala tentara Tuhanmu kecuali Dia sendiri. Ia (neraka Saqar itu) tidak lain hanyalah peringatan bagi manusia."),
    Ayah(32, 74, "كَلَّا وَالْقَمَرِۙ", "Kallā wal-qamar(i).", "Sekali-kali tidak! Demi bulan,"),
    Ayah(33, 74, "وَالَّيْلِ اِذْ اَدْبَرَۙ", "Wal-laili iż adbar(a).", "demi malam ketika telah berlalu,"),
    Ayah(34, 74, "وَالصُّبْحِ اِذَآ اَسْفَرَۙ", "Waṣ-ṣubḥi iżā asfar(a).", "dan demi subuh apabila mulai terang,"),
    Ayah(35, 74, "اِنَّهَا لَاِحْدَى الْكُبَرِۙ", "Innahā la'iḥdal-kubar(i).", "sesungguhnya ia (neraka Saqar itu) benar-benar salah satu (bencana) yang sangat besar,"),
    Ayah(36, 74, "نَذِيْرًا لِّلْبَشَرِۙ", "Nażīral lil-basyar(i).", "sebagai peringatan bagi manusia,"),
    Ayah(37, 74, "لِمَنْ شَاۤءَ مِنْكُمْ اَنْ يَّتَقَدَّمَ اَوْ يَتَاَخَّرَۗ", "Liman syā'a minkum ay yataqaddama au yata'akhkhar(a).", "(yaitu) bagi siapa di antara kamu yang ingin maju (meraih kebajikan) atau mundur (dengan berbuat maksiat)."),
    Ayah(38, 74, "كُلُّ نَفْسٍۢ بِمَا كَسَبَتْ رَهِيْنَةٌۙ", "Kullu nafsim bimā kasabat rahīnah(tun).", "Setiap orang bertanggung jawab atas apa yang telah ia lakukan,"),
    Ayah(39, 74, "اِلَّآ اَصْحٰبَ الْيَمِيْنِ ۛ", "Illā aṣḥābal-yamīn(i).", "kecuali golongan kanan,"),
    Ayah(40, 74, "فِيْ جَنّٰتٍ ۛ يَتَسَاۤءَلُوْنَۙ", "Fī jannātin - yatasā'alūn(a).", "berada di dalam surga yang mereka saling bertanya"),
    Ayah(41, 74, "عَنِ الْمُجْرِمِيْنَۙ", "‘Anil-mujrimīn(a).", "tentang (keadaan) para pendurhaka,"),
    Ayah(42, 74, "مَا سَلَكَكُمْ فِيْ سَقَرَ", "Mā salakakum fī saqar(a).", "“Apa yang menyebabkan kamu masuk ke dalam (neraka) Saqar?”"),
    Ayah(43, 74, "قَالُوْا لَمْ نَكُ مِنَ الْمُصَلِّيْنَۙ", "Qālū lam naku minal-muṣallīn(a).", "Mereka menjawab, “Dahulu kami tidak termasuk orang-orang yang melaksanakan salat"),
    Ayah(44, 74, "وَلَمْ نَكُ نُطْعِمُ الْمِسْكِيْنَۙ", "Wa lam naku nuṭ‘imul-miskīn(a).", "dan kami (juga) tidak memberi makan orang miskin."),
    Ayah(45, 74, "وَكُنَّا نَخُوْضُ مَعَ الْخَاۤىِٕضِيْنَۙ", "Wa kunnā nakhūḍu ma‘al-khā'iḍīn(a).", "Bahkan, kami selalu berbincang (untuk tujuan yang batil) bersama para pembincang,"),
    Ayah(46, 74, "وَكُنَّا نُكَذِّبُ بِيَوْمِ الدِّيْنِۙ", "Wa kunnā nukażżibu biyaumid-dīn(i).", "dan kami selalu mendustakan hari Pembalasan,"),
    Ayah(47, 74, "حَتّٰىٓ اَتٰىنَا الْيَقِيْنُۗ", "Ḥattā atānal-yaqīn(u).", "hingga datang kepada kami kematian.”"),
    Ayah(48, 74, "فَمَا تَنْفَعُهُمْ شَفَاعَةُ الشّٰفِعِيْنَۗ", "Famā tanfa‘uhum syafā‘atusy-syāfi‘īn(a).", "Maka, tidak berguna lagi bagi mereka syafaat (pertolongan) dari para pemberi syafaat."),
    Ayah(49, 74, "فَمَا لَهُمْ عَنِ التَّذْكِرَةِ مُعْرِضِيْنَۙ", "Famā lahum ‘anit-tażkirati mu‘riḍīn(a).", "Lalu, mengapa mereka (orang-orang kafir) berpaling dari peringatan (اللّه)"),
    Ayah(50, 74, "كَاَنَّهُمْ حُمُرٌ مُّسْتَنْفِرَةٌۙ", "Ka'annahum ḥumurum mustanfirah(tun).", "seakan-akan mereka keledai liar yang terkejut"),
    Ayah(51, 74, "فَرَّتْ مِنْ قَسْوَرَةٍۗ", "Farrat min qaswarah(tin).", "lari dari singa."),
    Ayah(52, 74, "بَلْ يُرِيْدُ كُلُّ امْرِئٍ مِّنْهُمْ اَنْ يُّؤْتٰى صُحُفًا مُّنَشَّرَةًۙ", "Bal yurīdu kullumri'im minhum ay yu'tā ṣuḥufam munasysyarah(tan).", "Bahkan, setiap orang dari mereka ingin diberi lembaran-lembaran (kitab) yang terbuka."),
    Ayah(53, 74, "كَلَّاۗ بَلْ لَّا يَخَافُوْنَ الْاٰخِرَةَۗ", "Kallā, bal lā yakhāfūnal-ākhirah(ta).", "Sekali-kali tidak! Sebenarnya mereka tidak takut pada akhirat."),
    Ayah(54, 74, "كَلَّآ اِنَّهٗ تَذْكِرَةٌ ۚ", "Kallā innahū tażkirah(tun).", "Sekali-kali tidak! Sesungguhnya (Al-Qur’an) itu adalah suatu peringatan."),
    Ayah(55, 74, "فَمَنْ شَاۤءَ ذَكَرَهٗۗ", "Faman syā'a żakarah(ū).", "Siapa yang berkehendak tentu mengambil pelajaran darinya."),
    Ayah(56, 74, "وَمَا يَذْكُرُوْنَ اِلَّآ اَنْ يَّشَاۤءَ اللّٰهُ ۗهُوَ اَهْلُ التَّقْوٰى وَاَهْلُ الْمَغْفِرَةِ ࣖ", "Wa mā yażkurūna illā ay yasyā'allāh(u), huwa ahlut-taqwā wa ahlul-magfirah(ti).", "Mereka tidak akan mengambil pelajaran darinya (Al-Qur’an), kecuali (jika) اللّه menghendakinya. Dialah yang (kita) patut bertakwa kepada-Nya dan yang berhak memberi ampunan."),
)

internal fun quranFullAyahs75(): List<Ayah> = listOf(
    Ayah(1, 75, "لَآ اُقْسِمُ بِيَوْمِ الْقِيٰمَةِۙ", "Lā uqsimu biyaumil-qiyāmah(ti).", "Aku bersumpah demi hari Kiamat."),
    Ayah(2, 75, "وَلَآ اُقْسِمُ بِالنَّفْسِ اللَّوَّامَةِ", "Wa lā uqsimu bin nafsil-lawwāmah(ti).", "Aku bersumpah demi jiwa yang sangat menyesali (dirinya sendiri)."),
    Ayah(3, 75, "اَيَحْسَبُ الْاِنْسَانُ اَلَّنْ نَّجْمَعَ عِظَامَهٗ ۗ", "Ayaḥsabul-insānu allan najma‘a ‘iẓāmah(ū).", "Apakah manusia mengira bahwa Kami tidak akan mengumpulkan (kembali) tulang-belulangnya?"),
    Ayah(4, 75, "بَلٰى قٰدِرِيْنَ عَلٰٓى اَنْ نُّسَوِّيَ بَنَانَهٗ", "Balā qādirīna ‘alā an nusawwiya banānah(ū).", "Tentu, (bahkan) Kami mampu menyusun (kembali) jari-jemarinya dengan sempurna."),
    Ayah(5, 75, "بَلْ يُرِيْدُ الْاِنْسَانُ لِيَفْجُرَ اَمَامَهٗۚ", "Bal yurīdul-insānu liyafjura amāmah(ū).", "Akan tetapi, manusia hendak berbuat maksiat terus-menerus."),
    Ayah(6, 75, "يَسْـَٔلُ اَيَّانَ يَوْمُ الْقِيٰمَةِۗ", "Yas'alu ayyāna yaumul-qiyāmah(ti).", "Dia bertanya, “Kapankah hari Kiamat itu?”"),
    Ayah(7, 75, "فَاِذَا بَرِقَ الْبَصَرُۙ", "Fa iżā bariqal-baṣar(u).", "Apabila mata terbelalak (ketakutan),"),
    Ayah(8, 75, "وَخَسَفَ الْقَمَرُۙ", "Wa khasafal-qamar(u).", "bulan pun telah hilang cahayanya,"),
    Ayah(9, 75, "وَجُمِعَ الشَّمْسُ وَالْقَمَرُۙ", "Wa jumi‘asy-syamsu wal-qamar(u).", "serta matahari dan bulan dikumpulkan,"),
    Ayah(10, 75, "يَقُوْلُ الْاِنْسَانُ يَوْمَىِٕذٍ اَيْنَ الْمَفَرُّۚ", "Yaqūlul-insānu yauma'iżin ainal-mafarr(u).", "pada hari itu manusia berkata, “Ke mana tempat lari?”"),
    Ayah(11, 75, "كَلَّا لَا وَزَرَۗ", "Kallā lā wazar(a).", "Sekali-kali tidak! Tidak ada tempat berlindung."),
    Ayah(12, 75, "اِلٰى رَبِّكَ يَوْمَىِٕذِ ِۨالْمُسْتَقَرُّۗ", "Ilā rabbika yauma'iżinil-mustaqarr(u).", "(Hanya) kepada Tuhanmu tempat kembali pada hari itu."),
    Ayah(13, 75, "يُنَبَّؤُا الْاِنْسَانُ يَوْمَىِٕذٍۢ بِمَا قَدَّمَ وَاَخَّرَۗ", "Yunabba'ul-insānu yauma'iżim bimā qaddama wa akhkhar(a).", "Pada hari itu diberitakan kepada manusia apa yang telah dia kerjakan dan apa yang telah dia lalaikan."),
    Ayah(14, 75, "بَلِ الْاِنْسَانُ عَلٰى نَفْسِهٖ بَصِيْرَةٌۙ", "Balil-insānu ‘alā nafsihī baṣīrah(tun).", "Bahkan, manusia menjadi saksi atas dirinya sendiri"),
    Ayah(15, 75, "وَّلَوْ اَلْقٰى مَعَاذِيْرَهٗۗ", "Wa lau alqā ma‘āżīrah(ū).", "walaupun dia mengemukakan alasan-alasan(-nya)."),
    Ayah(16, 75, "لَا تُحَرِّكْ بِهٖ لِسَانَكَ لِتَعْجَلَ بِهٖۗ", "Lā tuḥarrik bihī lisānaka lita‘jala bih(ī).", "Jangan engkau (Nabi Muhammad) gerakkan lidahmu (untuk membaca Al-Qur’an) karena hendak tergesa-gesa (menguasai)-nya."),
    Ayah(17, 75, "اِنَّ عَلَيْنَا جَمْعَهٗ وَقُرْاٰنَهٗ ۚ", "Inna ‘alainā jam‘ahū wa qur'ānah(ū).", "Sesungguhnya tugas Kamilah untuk mengumpulkan (dalam hatimu) dan membacakannya."),
    Ayah(18, 75, "فَاِذَا قَرَأْنٰهُ فَاتَّبِعْ قُرْاٰنَهٗ ۚ", "Fa iżā qara'nāhu fattabi‘ qur'ānah(ū).", "Maka, apabila Kami telah selesai membacakannya, ikutilah bacaannya itu."),
    Ayah(19, 75, "ثُمَّ اِنَّ عَلَيْنَا بَيَانَهٗ ۗ", "Ṡumma inna ‘alainā bayānah(ū).", "Kemudian, sesungguhnya tugas Kami (pula)-lah (untuk) menjelaskannya."),
    Ayah(20, 75, "كَلَّا بَلْ تُحِبُّوْنَ الْعَاجِلَةَۙ", "Kallā bal tuḥibbūnal-‘ājilah(ta).", "Sekali-kali tidak! Bahkan, kamu mencintai kehidupan dunia,"),
    Ayah(21, 75, "وَتَذَرُوْنَ الْاٰخِرَةَۗ", "Wa tażarūnal-‘ākhirah(ta).", "dan mengabaikan (kehidupan) akhirat."),
    Ayah(22, 75, "وُجُوْهٌ يَّوْمَىِٕذٍ نَّاضِرَةٌۙ", "Wujūhuy yauma'iżin nāḍirah(tun).", "Wajah-wajah (orang mukmin) pada hari itu berseri-seri"),
    Ayah(23, 75, "اِلٰى رَبِّهَا نَاظِرَةٌ ۚ", "Ilā rabbihā nāẓirah(tun).", "(karena) memandang Tuhannya."),
    Ayah(24, 75, "وَوُجُوْهٌ يَّوْمَىِٕذٍۢ بَاسِرَةٌۙ", "Wa wujūhuy yauma'iżim bāsirah(tun).", "Wajah-wajah (orang kafir) pada hari itu muram"),
    Ayah(25, 75, "تَظُنُّ اَنْ يُّفْعَلَ بِهَا فَاقِرَةٌ ۗ", "Taẓunnu ay yuf‘ala bihā fāqirah(tun).", "(karena) mereka yakin akan ditimpakan kepadanya malapetaka yang sangat dahsyat."),
    Ayah(26, 75, "كَلَّآ اِذَا بَلَغَتِ التَّرَاقِيَۙ", "Kallā iżā balagatit-tarāqiy(a).", "Sekali-kali tidak! Apabila (nyawa) telah sampai di kerongkongan,"),
    Ayah(27, 75, "وَقِيْلَ مَنْ ۜرَاقٍۙ", "Wa qīla man…rāq(in).", "dan dikatakan (kepadanya), “Siapa yang (dapat) menyembuhkan?”"),
    Ayah(28, 75, "وَّظَنَّ اَنَّهُ الْفِرَاقُۙ", "Wa ẓanna annahul-firāq(u).", "Dia pun yakin bahwa itulah waktu perpisahan (dengan dunia),"),
    Ayah(29, 75, "وَالْتَفَّتِ السَّاقُ بِالسَّاقِۙ", "Waltaffatis-sāqu bis-sāq(i).", "dan bertautlah betis (kiri) dengan betis (kanan)."),
    Ayah(30, 75, "اِلٰى رَبِّكَ يَوْمَىِٕذِ ِۨالْمَسَاقُ ۗ ࣖ", "Ilā rabbika yauma'iżinil-masāq(u).", "Kepada Tuhanmulah pada hari itu (manusia) digiring."),
    Ayah(31, 75, "فَلَا صَدَّقَ وَلَا صَلّٰىۙ", "Falā ṣaddaqa wa lā ṣallā.", "Dia tidak membenarkan (Al-Qur’an dan Rasul) dan tidak melaksanakan salat."),
    Ayah(32, 75, "وَلٰكِنْ كَذَّبَ وَتَوَلّٰىۙ", "Wa lākin każżaba wa tawallā.", "Akan tetapi, dia mendustakan (Al-Qur’an) dan berpaling (dari kebenaran)."),
    Ayah(33, 75, "ثُمَّ ذَهَبَ اِلٰٓى اَهْلِهٖ يَتَمَطّٰىۗ", "Ṡumma żahaba ilā ahlihī yatamaṭṭā.", "Kemudian, dia pergi kepada keluarganya dengan menyombongkan diri."),
    Ayah(34, 75, "اَوْلٰى لَكَ فَاَوْلٰىۙ", "Aulā laka fa'aulā.", "Celakalah kamu! Maka, celakalah!"),
    Ayah(35, 75, "ثُمَّ اَوْلٰى لَكَ فَاَوْلٰىۗ", "Ṡumma aulā laka fa'aulā.", "Kemudian, celakalah kamu! Maka, celakalah!"),
    Ayah(36, 75, "اَيَحْسَبُ الْاِنْسَانُ اَنْ يُّتْرَكَ سُدًىۗ", "Ayaḥsabul-insānu ay yutraka sudā(n).", "Apakah manusia mengira akan dibiarkan begitu saja (tanpa pertanggungjawaban)?"),
    Ayah(37, 75, "اَلَمْ يَكُ نُطْفَةً مِّنْ مَّنِيٍّ يُّمْنٰى", "Alam yaku nuṭfatam mim maniyyiy yumnā.", "Bukankah dia dahulu setetes mani yang ditumpahkan (ke dalam rahim)?"),
    Ayah(38, 75, "ثُمَّ كَانَ عَلَقَةً فَخَلَقَ فَسَوّٰىۙ", "Ṡumma kāna ‘alaqatan fa khalaqa fa sawwā.", "Kemudian, (mani itu) menjadi sesuatu yang melekat, lalu Dia menciptakan dan menyempurnakannya."),
    Ayah(39, 75, "فَجَعَلَ مِنْهُ الزَّوْجَيْنِ الذَّكَرَ وَالْاُنْثٰىۗ", "Fa ja‘ala minhuz-zaujainiż-żakara wal-unṡā.", "Lalu, Dia menjadikan darinya sepasang laki-laki dan perempuan."),
    Ayah(40, 75, "اَلَيْسَ ذٰلِكَ بِقٰدِرٍ عَلٰٓى اَنْ يُّحْيِ َۧ الْمَوْتٰى ࣖ", "Alaisa żālika biqādirin ‘alā ay yuḥyiyal-mautā.", "Bukankah (اللّه) itu kuasa (pula) menghidupkan orang mati?"),
)

internal fun quranFullAyahs76(): List<Ayah> = listOf(
    Ayah(1, 76, "هَلْ اَتٰى عَلَى الْاِنْسَانِ حِيْنٌ مِّنَ الدَّهْرِ لَمْ يَكُنْ شَيْـًٔا مَّذْكُوْرًا", "Hal atāka ‘alal-insāni ḥīnum minad-dahri lam yakun syai'am mażkūrā(n).", "Bukankah telah datang kepada manusia suatu waktu dari masa yang ia belum merupakan sesuatu yang dapat disebut?"),
    Ayah(2, 76, "اِنَّا خَلَقْنَا الْاِنْسَانَ مِنْ نُّطْفَةٍ اَمْشَاجٍۖ نَّبْتَلِيْهِ فَجَعَلْنٰهُ سَمِيْعًاۢ بَصِيْرًا", "Innā khalaqnal-insāna min nuṭfatin amsyājin nabtalīhi fa ja‘alnāhu samī‘am baṣīrā(n).", "Sesungguhnya Kami telah menciptakan manusia dari setetes mani yang bercampur. Kami hendak mengujinya (dengan perintah dan larangan) sehingga menjadikannya dapat mendengar dan melihat."),
    Ayah(3, 76, "اِنَّا هَدَيْنٰهُ السَّبِيْلَ اِمَّا شَاكِرًا وَّاِمَّا كَفُوْرًا", "Innā hadaināhus-sabīla immā syākiraw wa immā kafūrā(n).", "Sesungguhnya Kami telah menunjukkan kepadanya jalan (yang lurus); ada yang bersyukur dan ada pula yang sangat kufur."),
    Ayah(4, 76, "اِنَّآ اَعْتَدْنَا لِلْكٰفِرِيْنَ سَلٰسِلَا۟ وَاَغْلٰلًا وَّسَعِيْرًا", "Innā a‘tadnā lil-kāfirīna salāsila wa aglālaw wa sa‘īrā(n).", "Sesungguhnya Kami telah menyediakan bagi orang-orang kafir rantai, belenggu, dan api (neraka) Sa‘ir (yang menyala-nyala)."),
    Ayah(5, 76, "اِنَّ الْاَبْرَارَ يَشْرَبُوْنَ مِنْ كَأْسٍ كَانَ مِزَاجُهَا كَافُوْرًاۚ", "Innal-abrāra yasyrabūna min ka'sin kāna mizājuhā kāfūrā(n).", "Sesungguhnya orang-orang yang berbuat kebajikan akan minum (khamar) dari gelas yang campurannya air kafur,"),
    Ayah(6, 76, "عَيْنًا يَّشْرَبُ بِهَا عِبَادُ اللّٰهِ يُفَجِّرُوْنَهَا تَفْجِيْرًا", "‘Ainay yasyrabu bihā ‘ibādullāhi yufajjirūnahā tafjīrā(n).", "(yaitu) mata air (dalam surga) yang diminum oleh hamba-hamba اللّه dan dapat mereka pancarkan dengan mudah."),
    Ayah(7, 76, "يُوْفُوْنَ بِالنَّذْرِ وَيَخَافُوْنَ يَوْمًا كَانَ شَرُّهٗ مُسْتَطِيْرًا", "Yūfūna bin-nażri wa yakhāfūna yauman kāna syarruhū mustaṭīrā(n).", "Mereka memenuhi nazar dan takut akan suatu hari yang azabnya merata di mana-mana."),
    Ayah(8, 76, "وَيُطْعِمُوْنَ الطَّعَامَ عَلٰى حُبِّهٖ مِسْكِيْنًا وَّيَتِيْمًا وَّاَسِيْرًا", "Wa yuṭ‘imūnaṭ-ṭa‘āma ‘alā ḥubbihī miskīnaw wa yatīmaw wa asīrā(n).", "Mereka memberikan makanan yang disukainya kepada orang miskin, anak yatim, dan tawanan."),
    Ayah(9, 76, "اِنَّمَا نُطْعِمُكُمْ لِوَجْهِ اللّٰهِ لَا نُرِيْدُ مِنْكُمْ جَزَاۤءً وَّلَا شُكُوْرًا", "Innamā nuṭ‘imukum liwajhillāhi lā nurīdu minkum jazā'aw wa lā syukūrā(n).", "(Mereka berkata,) “Sesungguhnya kami memberi makanan kepadamu hanya demi rida اللّه. Kami tidak mengharap balasan dan terima kasih darimu."),
    Ayah(10, 76, "اِنَّا نَخَافُ مِنْ رَّبِّنَا يَوْمًا عَبُوْسًا قَمْطَرِيْرًا", "Innā nakhāfu mir rabbinā yauman ‘abūsan qamṭarīrā(n).", "Sesungguhnya kami takut akan (azab) Tuhan kami pada suatu hari (ketika) orang-orang berwajah masam penuh kesulitan.”"),
    Ayah(11, 76, "فَوَقٰىهُمُ اللّٰهُ شَرَّ ذٰلِكَ الْيَوْمِ وَلَقّٰىهُمْ نَضْرَةً وَّسُرُوْرًاۚ", "Fa waqāhumullāhu syarra żālikal-yaumi wa laqqāhum naḍrataw wa surūrā(n).", "Maka, اللّه melindungi mereka dari keburukan hari itu dan memberikan keceriaan dan kegembiraan kepada mereka."),
    Ayah(12, 76, "وَجَزٰىهُمْ بِمَا صَبَرُوْا جَنَّةً وَّحَرِيْرًاۙ", "Wa jazāhum bimā ṣabarū jannataw wa ḥarīrā(n).", "Dia memberikan balasan kepada mereka atas kesabarannya (berupa) surga dan (pakaian) sutra."),
    Ayah(13, 76, "مُّتَّكِـِٕيْنَ فِيْهَا عَلَى الْاَرَاۤىِٕكِۚ لَا يَرَوْنَ فِيْهَا شَمْسًا وَّلَا زَمْهَرِيْرًاۚ", "Muttaki'īna fīhā ‘alal-arā'ik(i), lā yarauna fīhā syamsaw wa lā zamharīrā(n).", "Di dalamnya mereka duduk bersandar di atas dipan. Di sana mereka tidak merasakan terik matahari dan dingin yang menusuk."),
    Ayah(14, 76, "وَدَانِيَةً عَلَيْهِمْ ظِلٰلُهَا وَذُلِّلَتْ قُطُوْفُهَا تَذْلِيْلًا", "Wa dāniyatan ‘alaihim ẓilāluhā wa żullilat quṭūfuhā tażlīlā(n).", "Naungan (pepohonan)-nya dekat di atas mereka dan sangat dimudahkan untuk memetik (buah)-nya."),
    Ayah(15, 76, "وَيُطَافُ عَلَيْهِمْ بِاٰنِيَةٍ مِّنْ فِضَّةٍ وَّاَكْوَابٍ كَانَتْ قَوَارِيْرَا۠", "Wa yuṭāfu ‘alaihim bi'āniyatim min fiḍḍatiw wa akwābin kānat qawārīrā.", "Diedarkan kepada mereka bejana-bejana dari perak dan gelas-gelas yang sangat bening (kacanya),"),
    Ayah(16, 76, "قَوَارِيْرَا۟ مِنْ فِضَّةٍ قَدَّرُوْهَا تَقْدِيْرًا", "Qawārīra min fiḍḍatin qaddarūhā taqdīrā(n).", "kaca yang sangat bening terbuat dari perak. Mereka menentukan ukuran sesuai (dengan kehendak mereka)."),
    Ayah(17, 76, "وَيُسْقَوْنَ فِيْهَا كَأْسًا كَانَ مِزَاجُهَا زَنْجَبِيْلًاۚ", "Wa yusqauna fīhā ka'san kāna mizājuhā zanjabīlā(n).", "Di sana mereka diberi segelas minuman bercampur jahe"),
    Ayah(18, 76, "عَيْنًا فِيْهَا تُسَمّٰى سَلْسَبِيْلًا", "‘Ainan fīhā tusammā salsabīlā(n).", "(yang didatangkan dari) sebuah mata air (di surga) yang dinamakan Salsabil."),
    Ayah(19, 76, "۞ وَيَطُوْفُ عَلَيْهِمْ وِلْدَانٌ مُّخَلَّدُوْنَۚ اِذَا رَاَيْتَهُمْ حَسِبْتَهُمْ لُؤْلُؤًا مَّنْثُوْرًا", "Wa yaṭūfu ‘alaihim wildānum mukhalladūn(a), iżā ra'aitahum ḥasibtahum lu'lu'am manṡūrā(n).", "Mereka dikelilingi oleh para pemuda yang tetap muda. Apabila melihatnya, kamu akan mengira bahwa mereka adalah mutiara yang bertaburan."),
    Ayah(20, 76, "وَاِذَا رَاَيْتَ ثَمَّ رَاَيْتَ نَعِيْمًا وَّمُلْكًا كَبِيْرًا", "Wa iżā ra'aita ṡamma ra'aita na‘īmaw wa mulkan kabīrā(n).", "Apabila melihat (keadaan) di sana (surga), niscaya engkau akan melihat berbagai kenikmatan dan kerajaan yang besar."),
    Ayah(21, 76, "عٰلِيَهُمْ ثِيَابُ سُنْدُسٍ خُضْرٌ وَّاِسْتَبْرَقٌۖ وَّحُلُّوْٓا اَسَاوِرَ مِنْ فِضَّةٍۚ وَسَقٰىهُمْ رَبُّهُمْ شَرَابًا طَهُوْرًا", "‘Āliyahum ṡiyābu sundusin khuḍruw wa istabraq(un), wa ḥullū asāwira min fiḍḍah(tin), wa saqāhum rabbuhum syarāban ṭahūrā(n).", "Mereka berpakaian sutra halus yang hijau, sutra tebal, dan memakai gelang perak. Tuhan memberikan kepada mereka minuman yang suci."),
    Ayah(22, 76, "اِنَّ هٰذَا كَانَ لَكُمْ جَزَاۤءً وَّكَانَ سَعْيُكُمْ مَّشْكُوْرًا ࣖ", "Inna hāżā kāna lakum jazā'aw wa kāna sa‘yukum masykūrā(n).", "Sesungguhnya ini adalah balasan untukmu dan usahamu diterima dengan baik."),
    Ayah(23, 76, "اِنَّا نَحْنُ نَزَّلْنَا عَلَيْكَ الْقُرْاٰنَ تَنْزِيْلًاۚ", "Innā naḥnu nazzalnā ‘alaikal-qur'āna tanzīlā(n).", "Sesungguhnya Kamilah yang benar-benar menurunkan Al-Qur’an kepadamu (Nabi Muhammad) secara berangsur-angsur."),
    Ayah(24, 76, "فَاصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تُطِعْ مِنْهُمْ اٰثِمًا اَوْ كَفُوْرًاۚ", "Faṣbir liḥukmi rabbika wa lā tuṭi‘ minhum āṡiman au kafūrā(n).", "Maka, bersabarlah untuk (melaksanakan) ketetapan Tuhanmu dan jangan ikuti pendosa dan orang yang sangat kufur di antara mereka."),
    Ayah(25, 76, "وَاذْكُرِ اسْمَ رَبِّكَ بُكْرَةً وَّاَصِيْلًاۚ", "Ważkurisma rabbika bukrataw wa aṣīlā(n).", "Sebutlah nama Tuhanmu pada (waktu) pagi dan petang."),
    Ayah(26, 76, "وَمِنَ الَّيْلِ فَاسْجُدْ لَهٗ وَسَبِّحْهُ لَيْلًا طَوِيْلًا", "Wa minal-laili fasjud lahū wa sabbiḥhu lailan ṭawīlā(n).", "Pada sebagian malam bersujudlah kepada-Nya dan bertasbihlah kepada-Nya pada malam yang panjang."),
    Ayah(27, 76, "اِنَّ هٰٓؤُلَاۤءِ يُحِبُّوْنَ الْعَاجِلَةَ وَيَذَرُوْنَ وَرَاۤءَهُمْ يَوْمًا ثَقِيْلًا", "Inna hā'ulā'i yuḥibbūnal-‘ājilata wa yażarūna warā'ahum yauman ṡaqīlā(n)", "Sesungguhnya mereka (orang-orang kafir) itu mencintai kehidupan dunia dan meninggalkan di belakang mereka hari yang berat (akhirat)."),
    Ayah(28, 76, "نَحْنُ خَلَقْنٰهُمْ وَشَدَدْنَآ اَسْرَهُمْۚ وَاِذَا شِئْنَا بَدَّلْنَآ اَمْثَالَهُمْ تَبْدِيْلًا", "Naḥnu khalaqnāhum wa syadadnā asrahum, wa iżā syi'nā baddalnā amṡālahum tabdīlā(n).", "Kami telah menciptakan mereka dan menguatkan persendian tubuh mereka. Jika berkehendak, Kami dapat mengganti (mereka) dengan orang-orang yang serupa mereka."),
    Ayah(29, 76, "اِنَّ هٰذِهٖ تَذْكِرَةٌ ۚ فَمَنْ شَاۤءَ اتَّخَذَ اِلٰى رَبِّهٖ سَبِيْلًا", "Inna hāżihī tażkirah(tun), faman syā'attakhaża ilā rabbihī sabīlā(n).", "Sesungguhnya ini adalah peringatan. Maka, siapa yang menghendaki (kebaikan bagi dirinya) tentu mengambil jalan menuju Tuhannya."),
    Ayah(30, 76, "وَمَا تَشَاۤءُوْنَ اِلَّآ اَنْ يَّشَاۤءَ اللّٰهُ ۗاِنَّ اللّٰهَ كَانَ عَلِيْمًا حَكِيْمًاۖ", "Wa mā tasyā'ūna illā ay yasyā'allāh(u), innallāha kāna ‘alīman ḥakīmā(n).", "Kamu tidak menghendaki (sesuatu) kecuali apabila dikehendaki اللّه. Sesungguhnya اللّه Maha Mengetahui lagi Mahabijaksana."),
    Ayah(31, 76, "يُّدْخِلُ مَنْ يَّشَاۤءُ فِيْ رَحْمَتِهٖۗ وَالظّٰلِمِيْنَ اَعَدَّ لَهُمْ عَذَابًا اَلِيْمًا ࣖ", "Yudkhilu may yasyā'u fī raḥmatih(ī), waẓ-ẓālimīna a‘adda lahum ‘ażāban alīmā(n).", "Dia memasukkan siapa pun yang Dia kehendaki ke dalam rahmat-Nya (surga). Bagi orang-orang zalim Dia sediakan azab yang pedih."),
)

